	["%s profile: %d values map to EldoUI, made into a new profile."] = { one = "%s-Profil: %d Wert passt zu EldoUI und wurde zu einem neuen Profil.", other = "%s-Profil: %d Werte passen zu EldoUI und wurden zu einem neuen Profil." },
	["%s reset to its defaults."] = "%s auf Standardwerte zurückgesetzt.",
	["%s set in %d modules."] = { one = "%s in %d Modul gesetzt.", other = "%s in %d Modulen gesetzt." },
	["%s sets up your controller's buttons, so EldoUI leaves the controller bars to it."] = "%s richtet die Tasten Eures Controllers ein, daher überlässt EldoUI ihm die Controllerleisten.",
	["%s settings"] = "Einstellungen für %s",
	["%s shows only %q in EllesmereUI; EldoUI has no such rule, so it is always shown."] = "%s erscheint in EllesmereUI nur %q; EldoUI kennt keine solche Regel, daher wird es immer angezeigt.",
	["%s stays off while %s is loaded."] = "%s bleibt aus, solange %s geladen ist.",
	["%s stays on %s (%s), so %s gets no key."] = "%s bleibt auf %s (%s), daher bekommt %s keine Taste.",
	["%s style %s applied."] = "%s: Stil %s angewendet.",
	["%s switched some EldoUI modules off. They are fully gone after a reload. Undo UI amount switches back what it changed."] = "%s hat einige EldoUI-Module ausgeschaltet. Nach einem Neuladen sind sie ganz weg. UI-Umfang rückgängig schaltet zurück, was geändert wurde.",
	["%s to %s"] = "%s → %s",
	["%s to %s: %s"] = "%s → %s: %s",
	["%s to %s: just above %s"] = "%s → %s: direkt über %s",
