	["%s uses a layout that can't be put in a string, so it can't be exported."] = "%s verwendet ein Layout, das sich nicht in einen String packen lässt, daher ist kein Export möglich.",
	["%s wants to send you EldoUI settings:\n%s (%.1f KB)\n\nAccept to receive them. You see what they change before anything is applied."] = "%s möchte Euch EldoUI-Einstellungen senden:\n%s (%.1f KB)\n\nNehmt an, um sie zu empfangen. Ihr seht, was sie ändern, bevor etwas übernommen wird.",
	["%s was switched on outside EldoUI. Type %s to switch it off."] = "%s wurde außerhalb von EldoUI eingeschaltet. Gebt %s ein, um es auszuschalten.",
	["%s will be disabled for this character"] = "%s wird für diesen Charakter deaktiviert",
	["%s with %d frames."] = "%s mit %d Rahmen.",
	["%s's own look"] = "Eigene Optik von %s",
