	["%s, kept %s when you forgot the character"] = "%s, aufbewahrt %s, als Ihr den Charakter vergessen habt",
	["%s, the skin this layout was made for. It changes with the next layout you pick. Accent: %s."] = "%s, der Skin, für den dieses Layout gemacht wurde. Er wechselt mit dem nächsten Layout, das Ihr wählt. Akzent: %s.",
	["%s, then %s"] = "%s, dann %s",
