	["%s: EldoUI's after a reload (%s is off for this character)"] = "%s: nach einem Neuladen bei EldoUI (%s ist für diesen Charakter aus)",
	["%s: a background with no datatexts; EldoUI's panels always hold datatexts"] = "%s: ein Hintergrund ohne Datentexte; die Leisten von EldoUI enthalten immer Datentexte",
