	["%s: off for this character at Finish"] = "%s: beim Abschließen für diesen Charakter aus",
	["%s: off in the string"] = "%s: im String aus",
	["%s: placed by the layout again."] = "%s: wieder vom Layout platziert.",
	["%s: position %q can't be read"] = "%s: Position %q kann nicht gelesen werden",
	["%s: positions, sizes and visibility read; the rest is EllesmereUI's own look"] = "%s: Positionen, Größen und Sichtbarkeit gelesen; der Rest ist die eigene Optik von EllesmereUI",
	["%s: replace your %s"] = "%s: ersetzt Eure %s",
