	["...and %d more on the What's New page."] = "...und %d weitere auf der Seite Neuigkeiten.",
	["/eui <module> on | off | toggle, or /eui <module> for its settings"] = "/eui <module> on | off | toggle, oder /eui <module> für seine Einstellungen",
	["1 change undone."] = "1 Änderung rückgängig gemacht.",
	["1 fix."] = "1 Fehlerbehebung.",
