	["61 new features, 105 improvements and 150 fixes."] = "61 neue Funktionen, 105 Verbesserungen und 150 Fehlerbehebungen.",
	["8 fixes."] = "8 Fehlerbehebungen.",
	["<addon>  save another addon's setup into EldoUI (%s)"] = "<addon>  die Einrichtung eines anderen Addons in EldoUI speichern (%s)",
	["<kind> ...  in-game checks that print what the game reports"] = "<kind> ...  Prüfungen im Spiel, die ausgeben, was das Spiel meldet",
	["<module>  same as /eui <module> off"] = "<module>  wie /eui <module> off",
	["<module>  same as /eui <module> on"] = "<module>  wie /eui <module> on",
	["<name> | undo  apply a layout preset, or undo the last setup change (no name lists them)"] = "<name> | undo  eine Layoutvorlage anwenden oder die letzte Änderung der Einrichtung rückgängig machen (ohne Namen werden sie aufgelistet)",
	["<new name>  rename the profile this character uses"] = "<new name>  das Profil umbenennen, das dieser Charakter verwendet",
	["<party | raid | guild | player> [all | general | positions | global | <module> | <list>]  offer settings to a group, guild or player"] = "<party | raid | guild | player> [all | general | positions | global | <module> | <list>]  Einstellungen einer Gruppe, Gilde oder einem Spieler anbieten",
	["<profile>  copy chosen modules from another profile"] = "<profile>  ausgewählte Module aus einem anderen Profil kopieren",
	["<words>  open the options with every setting that matches"] = "<words>  die Optionen mit allen passenden Einstellungen öffnen",
	["A 1-pixel shadow under EldoUI's text, softer when there is an outline too. With no outline, the shadow keeps text readable over bright ground."] = "Ein 1-Pixel-Schatten unter den Texten von EldoUI, weicher, wenn auch eine Kontur da ist. Ohne Kontur hält der Schatten Text auf hellem Untergrund lesbar.",
	["A Lua error was logged. Type %s to see it."] = "Ein Lua-Fehler wurde protokolliert. Gebt %s ein, um ihn anzusehen.",
	["A Soulstone on an ally is the warlock's ally save: Create Soulstone is on the Resurrection button."] = "Ein Seelenstein auf einem Verbündeten ist die Rettung des Hexenmeisters für Verbündete: Seelenstein herstellen liegt auf der Taste Wiederbelebung.",
	["A bar that shows on mouse-over"] = "Eine Leiste, die bei Mauskontakt erscheint",
	["A bar with gold, FPS ..."] = "Eine Leiste mit Gold, FPS ...",
	["A border, glow or tint in the threat color (Colors page). Only the game's threat state is used; the game's color curve shows it even where the state is hidden."] = "Ein Rand, Leuchten oder Farbton in der Bedrohungsfarbe (Seite Farben). Nur der Bedrohungsstatus des Spiels wird verwendet; die Farbkurve des Spiels zeigt ihn auch dort, wo der Status verborgen ist.",
	["A bright line at the end of the cast bar fill."] = "Eine helle Linie am Ende der Füllung der Zauberleiste.",
	["A bundle with %d parts."] = { one = "Ein Bündel mit %d Teil.", other = "Ein Bündel mit %d Teilen." },
	["A character on the picked profile. Its own picks from its setup are checked below; a character without a saved setup gets EldoUI's suggestions."] = "Ein Charakter im gewählten Profil. Seine eigene Auswahl aus seiner Einrichtung ist unten angehakt; ein Charakter ohne gespeicherte Einrichtung erhält die Vorschläge von EldoUI.",
	["A character on this profile whose keys differ from this key set (a new character, or keys the game reset). Ask me: one alert with a preview. Automatic: its keys are set out of combat, with a backup and Undo. Off: nothing happens. Keys you set yourself are never written over."] = "Ein Charakter in diesem Profil, dessen Tasten von diesem Tastensatz abweichen (ein neuer Charakter oder vom Spiel zurückgesetzte Tasten). Nachfragen: ein Hinweis mit Vorschau. Automatisch: Seine Tasten werden außerhalb des Kampfes gesetzt, mit Sicherung und Rückgängig. Aus: Nichts passiert. Tasten, die Ihr selbst belegt habt, werden nie überschrieben.",
	["A chat reset can't be undone"] = "Das Zurücksetzen des Chats lässt sich nicht rückgängig machen",
	["A class bar for every class but the shaman keeps your buffs, auras and key cooldowns in view."] = "Eine Klassenleiste für jede Klasse außer dem Schamanen behält Eure Stärkungszauber, Auren und wichtigen Abklingzeiten im Blick.",
	["A copy from before is on the Saved data page."] = "Eine Kopie vom vorherigen Stand liegt auf der Seite „Gespeicherte Daten“.",
	["A copy is kept first: Undo in the alert or the Saved data page puts it back."] = "Zuvor wird eine Kopie aufbewahrt: „Rückgängig“ im Hinweis oder die Seite „Gespeicherte Daten“ stellt es wieder her.",
	["A defensive you use often."] = "Ein Defensivzauber, den Ihr oft nutzt.",
	["A dropped window's corner lands on this grid, in pixels. 1 places it freely."] = "Die Ecke eines abgelegten Fensters rastet auf diesem Raster ein, in Pixeln. 1 platziert es frei.",
	["A faded window becomes solid while you point at it."] = "Ein ausgeblendetes Fenster wird wieder deckend, solange Ihr darauf zeigt.",
	["A fear, not a stun."] = "Ein Furchteffekt, keine Betäubung.",
	["A few of the game's own interface settings that fit EldoUI. Only what is checked changes, and \"Blizzard default\" in /eui puts your own values back."] = "Einige Interface-Einstellungen des Spiels, die zu EldoUI passen. Nur was angehakt ist, ändert sich, und \"Blizzard-Standard\" in /eui stellt Eure eigenen Werte wieder her.",
	["A few short steps set up the whole UI. Every step is optional: Skip leaves that part as it is."] = "Ein paar kurze Schritte richten die gesamte Oberfläche ein. Jeder Schritt ist freiwillig: Überspringen lässt diesen Teil, wie er ist.",
	["A finisher: spends combo points."] = "Ein Finisher: verbraucht Kombopunkte.",
	["A form: faster on foot, no spells while in it."] = "Eine Gestalt: zu Fuß schneller, in ihr keine Zauber.",
	["A glow while the game marks the spell as important. The look is on the Glows page (Cast bars: important spells), shared by every cast bar."] = "Ein Leuchten, solange das Spiel den Zauber als wichtig markiert. Die Optik steht auf der Seite „Leuchteffekte“ (Zauberleisten: wichtige Zauber) und gilt für alle Zauberleisten.",
	["A home-made swing timer would need hidden combat stats, so EldoUI skins Blizzard's built-in timer instead."] = "Ein eigener Schlagtimer bräuchte verborgene Kampfwerte, daher gibt EldoUI stattdessen dem eingebauten Timer von Blizzard einen Skin.",
	["A key the key sets never take."] = "Eine Taste, die die Tastensätze nie belegen.",
	["A layer chip on the minimap shows your layer and hops you to another with a click."] = "Eine Layer-Anzeige an der Minikarte zeigt Euren Layer und bringt Euch per Klick auf einen anderen.",
	["A layout places all your frames at once. A style changes the look of one part. UI amount picks how many helpers are on. A pack sets all three in one click."] = "Ein Layout platziert alle Eure Rahmen auf einmal. Ein Stil ändert die Optik eines Teils. UI-Umfang legt fest, wie viele Helfer an sind. Ein Paket setzt alle drei mit einem Klick.",
	["A level only switches EldoUI modules on or off. It never moves frames or changes your skin, key bindings or other addons."] = "Eine Stufe schaltet nur EldoUI-Module ein oder aus. Sie verschiebt nie Rahmen und ändert nie Euren Skin, Eure Tastenbelegung oder andere Addons.",
	["A locked frame can't be dragged by accident. The arrows and the X and Y boxes still move it."] = "Ein gesperrter Rahmen lässt sich nicht versehentlich ziehen. Die Pfeile und die Felder X und Y verschieben ihn weiterhin.",
	["A mark at the percent."] = "Eine Markierung beim Prozentwert.",
	["A menu opens where you click it."] = "Ein Menü öffnet sich dort, wo Ihr klickt.",
	["A modern take on the original look: your frame and your target's sit low beside the center for short eye travel, over two bar rows, with the party on the left and the same round minimap."] = "Eine moderne Fassung der ursprünglichen Optik: Euer Rahmen und der Eures Ziels sitzen tief neben der Mitte für kurze Blickwege, über zwei Leistenreihen, mit der Gruppe links und derselben runden Minikarte.",
	["A module switched off is fully gone after a reload."] = "Ein ausgeschaltetes Modul ist nach einem Neuladen ganz weg.",
	["A module that is off does nothing and costs nothing; Blizzard's own version of that part of the UI stays. Turning a module off fully brings back Blizzard's version after a reload, which Finish offers. Every module can be switched later in /eui > Modules or with the switch next to it in the options sidebar."] = "Ein ausgeschaltetes Modul tut nichts und kostet nichts; Blizzards eigene Version dieses Teils der Oberfläche bleibt. Wird ein Modul ausgeschaltet, kommt Blizzards Version nach einem Neuladen vollständig zurück; der Abschluss bietet dieses Neuladen an. Jedes Modul lässt sich später unter /eui > Module oder mit dem Schalter daneben in der Seitenleiste der Optionen umschalten.",
	["A mount or travel spell you own."] = "Ein Reittier oder Reisezauber, den Ihr besitzt.",
	["A new Keys and spells step shows your keys, class spells and macros first and changes nothing on your bars until you press Apply."] = "Ein neuer Schritt Tasten und Zauber zeigt zuerst Eure Tasten, Klassenzauber und Makros und ändert nichts an Euren Leisten, bis Ihr auf Übernehmen drückt.",
	["A new profile %s, a copy with the %s role. %s stays as it is."] = "Ein neues Profil %s, eine Kopie mit der Rolle %s. %s bleibt, wie es ist.",
	["A newer version of %s is out: %s (you have %s)."] = "Eine neuere Version von %s ist erschienen: %s (Ihr habt %s).",
	["A player (by name)"] = "Ein Spieler (nach Name)",
	["A player's guild name."] = "Der Gildenname eines Spielers.",
	["A player's name with their chosen title."] = "Der Name eines Spielers mit seinem gewählten Titel.",
	["A player's race."] = "Das Volk eines Spielers.",
	["A player's rank in their guild."] = "Der Rang eines Spielers in seiner Gilde.",
	["A profile called \"%s\", fresh from EldoUI's defaults. Your current profile stays as it is, so you can switch back in /eui > Profiles."] = "Ein Profil namens \"%s\", frisch aus den Standardwerten von EldoUI. Euer aktuelles Profil bleibt, wie es ist, sodass Ihr unter /eui > Profile zurückwechseln könnt.",
	["A profile holds the layout, skin, styles, modules and the Blizzard UI switches, and characters can share one. This page puts this character on a profile that is set up already and changes nothing in it.\n\nWhat belongs to the character is set up for it: chat tabs, game settings, other addons' profiles, click-casting for a class that has none on the profile yet, and class spells and macros on empty buttons. Each comes from what the character you copy from picked in its own setup, or from EldoUI's suggestions when it has no saved setup. Uncheck a part to leave it as it is.\n\nA profile set up for another role can be copied for this character's role: the copy gets the role, and the original stays as it is.\n\nAttach keeps a backup first. The last page lists every change with Revert this, and Undo the whole setup (or /eui install undo) puts this character back on the profile it used before. Full setup instead goes through every step on its own."] = "Ein Profil enthält Layout, Skin, Stile, Module und die Schalter für die Blizzard-Oberfläche, und mehrere Charaktere können sich eins teilen. Diese Seite ordnet diesen Charakter einem bereits eingerichteten Profil zu und ändert darin nichts.\n\nWas zum Charakter gehört, wird für ihn eingerichtet: Chatreiter, Spieleinstellungen, Profile anderer Addons, Klickzauber für eine Klasse, die im Profil noch keine hat, sowie Klassenzauber und Makros auf leeren Aktionstasten. Alles stammt aus dem, was der Charakter, von dem Ihr kopiert, in seiner eigenen Einrichtung gewählt hat, oder aus den Vorschlägen von EldoUI, wenn er keine gespeicherte Einrichtung hat. Wählt einen Teil ab, um ihn so zu lassen, wie er ist.\n\nEin Profil, das für eine andere Rolle eingerichtet ist, lässt sich für die Rolle dieses Charakters kopieren: Die Kopie erhält die Rolle, und das Original bleibt, wie es ist.\n\nZuordnen legt zuerst eine Sicherung an. Die letzte Seite listet jede Änderung mit Dies zurücknehmen auf, und Gesamte Einrichtung rückgängig machen (oder /eui install undo) setzt diesen Charakter wieder auf das Profil, das er vorher verwendet hat. Vollständige Einrichtung geht stattdessen jeden Schritt einzeln durch.",
	["A profile named %s already exists. Use %s."] = "Ein Profil namens %s existiert bereits. Verwendet %s.",
	["A profile with that name already exists."] = "Ein Profil mit diesem Namen existiert bereits.",
	["A quiet center: unit frames high, level with the resource bar, three stacked bar rows."] = "Eine ruhige Mitte: Einheitenrahmen hoch, auf Höhe der Ressourcenleiste, drei gestapelte Leistenreihen.",
	["A quiet screen: thin unit and group frames, no keybind text, a small minimap and a quiet info bar."] = "Ein ruhiger Bildschirm: schmale Einheiten- und Gruppenrahmen, keine Tastenbeschriftung, eine kleine Minikarte und eine ruhige Infoleiste.",
	["A raid warning appears in the middle of the screen."] = "Eine Schlachtzugswarnung erscheint in der Bildschirmmitte.",
	["A ready check starts."] = "Ein Bereitschaftscheck beginnt.",
	["A recipe one of your characters can learn later"] = "Ein Rezept, das einer Eurer Charaktere später erlernen kann",
	["A recipe one of your characters can learn now"] = "Ein Rezept, das einer Eurer Charaktere jetzt erlernen kann",
	["A red band inside the frame."] = "Ein rotes Band innerhalb des Rahmens.",
	["A role is not a layout. Healer moves your party and raid frames next to the center (a few frames that sat there step outward) and turns on dispel and boss debuff highlights. Tank adds threat colors and the threat meter. Melee and Ranged keep the layout as it is; Ranged also shows the five-second rule on your mana bar.\n\nClick-casting (healers): a binding casts a spell on the frame you click, e.g. Shift + left click casts your fast heal on that party member. EldoUI suggests spells from your spellbook; only the ones you tick are bound, plain left and right click stay target and menu, and nothing casts by itself. Change or remove them any time in /eui > Click Casting."] = "Eine Rolle ist kein Layout. Heiler rückt Eure Gruppen- und Schlachtzugsrahmen neben die Mitte (einige Rahmen, die dort saßen, weichen nach außen) und schaltet Hervorhebungen für bannbare Effekte und Boss-Schwächungszauber ein. Tank ergänzt Bedrohungsfarben und die Bedrohungsanzeige. Nahkampf und Distanz lassen das Layout, wie es ist; Distanz zeigt zusätzlich die Fünf-Sekunden-Regel auf Eurer Manaleiste.\n\nKlickzauber (Heiler): Eine Belegung wirkt einen Zauber auf den Rahmen, den Ihr anklickt, z. B. wirkt Umschalt + Linksklick Eure schnelle Heilung auf dieses Gruppenmitglied. EldoUI schlägt Zauber aus Eurem Zauberbuch vor; belegt werden nur die, die Ihr anhakt, einfacher Links- und Rechtsklick bleiben Ziel und Menü, und nichts wird von selbst gewirkt. Ändert oder entfernt sie jederzeit unter /eui > Klickzauber.",
	["A role moves a few frames on top of your layout: healers get group frames near the center, tanks get threat colors."] = "Eine Rolle verschiebt ein paar Rahmen über Eurem Layout: Heiler erhalten Gruppenrahmen nahe der Mitte, Tanks Bedrohungsfarben.",
	["A root, snare or second control spell."] = "Ein Festhalte-, Verlangsamungs- oder zweiter Kontrollzauber.",
	["A saved value EldoUI can't read is set aside here, never deleted. Put back returns it to its place and sets aside what sits there now."] = "Ein gespeicherter Wert, den EldoUI nicht lesen kann, wird hier beiseitegelegt, nie gelöscht. Zurücklegen bringt ihn an seinen Platz zurück und legt beiseite, was jetzt dort liegt.",
	["A second movement spell, or a travel form."] = "Ein zweiter Bewegungszauber oder eine Reisegestalt.",
	["A second shade above this percent, for abilities that work on healthy units."] = "Eine zweite Schattierung über diesem Prozentwert, für Fähigkeiten, die bei gesunden Einheiten wirken.",
	["A second way to stop or push away an enemy."] = "Eine zweite Möglichkeit, einen Gegner aufzuhalten oder wegzustoßen.",
	["A setting"] = "Eine Einstellung",
	["A shaped portrait frame, a heavy divider between health and power and a shaded name strip."] = "Ein geformter Porträtrahmen, ein kräftiger Trenner zwischen Gesundheit und Ressource und ein schattierter Namensstreifen.",
	["A short explanation of this step."] = "Eine kurze Erklärung zu diesem Schritt.",
	["A short flash on the frame when your target changes. Follows General > Animations."] = "Ein kurzes Aufblitzen am Rahmen, wenn Euer Ziel wechselt. Folgt Allgemein > Animationen.",
	["A slow pulsing border, no movement round the frame."] = "Ein langsam pulsierender Rand, keine Bewegung um den Rahmen.",
	["A small layer over your layout for the job you do in groups. Boss frames, boss mod bars and your cast bar never move by role."] = "Eine kleine Ebene über Eurem Layout für Eure Aufgabe in Gruppen. Bossrahmen, Bossmod-Leisten und Eure Zauberleiste bewegen sich nie mit der Rolle.",
	["A soft shadow around EldoUI windows and panels in the flat skins, Modern and Minimal Modern."] = "Ein weicher Schatten um Fenster und Panels von EldoUI in den flachen Skins Modern und Minimal Modern.",
	["A sound when a cast starts that the game marks as important. Stays silent where the game hides that flag. Off by default; no preset turns it on."] = "Ein Ton, wenn ein Zauber beginnt, den das Spiel als wichtig markiert. Bleibt still, wo das Spiel diese Markierung verbirgt. Standardmäßig aus; keine Vorlage schaltet ihn ein.",
	["A speed aspect, not a dash: a hit dazes you while it is on."] = "Ein Tempo-Aspekt, kein Sprint: Solange er aktiv ist, macht Euch jeder Treffer benommen.",
	["A spell ID, the exact spell name, or Shift-click a spell link into the box. Press Enter."] = "Eine Zauber-ID, der genaue Zaubername oder ein per Umschaltklick ins Feld eingefügter Zauberlink. Drückt die Eingabetaste.",
	["A spell for your role: a taunt, a mark or a slow fall."] = "Ein Zauber für Eure Rolle: ein Spott, ein Mal oder Langsamer Fall.",
	["A spell you learn at a trainer or with a talent, when its button is empty. Ask me: one alert with a preview. Automatic: it goes on its button out of combat, with Undo. Off: nothing happens."] = "Ein Zauber, den Ihr bei einem Lehrer oder durch ein Talent erlernt, wenn seine Aktionstaste leer ist. Nachfragen: ein Hinweis mit Vorschau. Automatisch: Er kommt außerhalb des Kampfes auf seine Aktionstaste, mit Rückgängig. Aus: Nichts passiert.",
	["A step-by-step setup with Express, preset packs, UI amount and the Overview page."] = "Eine Schritt-für-Schritt-Einrichtung mit Express, Vorlagenpaketen, UI-Umfang und der Seite Übersicht.",
	["A style sets the look of this part in one click. Picking another style replaces it, settings included, so pick the style first and fine-tune after."] = "Ein Stil legt die Optik dieses Teils mit einem Klick fest. Ein anderer Stil ersetzt ihn samt Einstellungen, wählt also zuerst den Stil und passt danach fein an.",
	["A subtle color in the background of EldoUI windows and panels: Midnight blue, Pine green, Wine red or Dusk violet. None keeps the plain dark panels. Text keeps its contrast in every tint."] = "Eine dezente Farbe im Hintergrund der Fenster und Panels von EldoUI: Mitternachtsblau, Kieferngrün, Weinrot oder Dämmerviolett. Nichts behält die schlichten dunklen Panels. Text behält in jedem Farbton seinen Kontrast.",
	["A subtle tint in the background of EldoUI windows and panels."] = "Ein dezenter Farbton im Hintergrund der Fenster und Panels von EldoUI.",
	["A text string with the list, to share or keep."] = "Ein Textstring mit der Liste, zum Teilen oder Aufbewahren.",
	["A tidy modern screen: everything under your character, quiet flat panels with a fine edge and EldoUI's helpers."] = "Ein aufgeräumter moderner Bildschirm: alles unter Eurem Charakter, ruhige flache Panels mit feinem Rand und die Helfer von EldoUI.",
	["A window dropped close to a screen edge sits flush against it."] = "Ein Fenster, das nahe am Bildschirmrand abgelegt wird, liegt bündig daran an.",
	["A window that would be taller than the screen at its scale is shown a little smaller. Its saved scale stays."] = "Ein Fenster, das bei seiner Skalierung höher als der Bildschirm wäre, wird etwas kleiner angezeigt. Seine gespeicherte Skalierung bleibt.",
	["A/D strafe"] = "A/D seitwärts",
	["A/D strafe only: Mouse 4 and Mouse 5 press buttons 6 and 7 of bars 1 to 3, with Shift and Ctrl for bars 2 and 3."] = "Nur A/D seitwärts: Maustaste 4 und 5 drücken die Aktionstasten 6 und 7 der Leisten 1 bis 3, mit Umschalt und Strg für die Leisten 2 und 3.",
	["AM"] = "AM",
	["Above"] = "Oberhalb",
	["Above health"] = "Über der Gesundheit",
	["Absorb shield"] = "Absorptionsschild",
	["Accent color"] = "Akzentfarbe",
	["Accent color, art style, fonts, bar texture, colors and the other General settings. Your layout stays; check Layout to take that too."] = "Akzentfarbe, Grafikstil, Schriftarten, Leistentextur, Farben und die übrigen allgemeinen Einstellungen. Euer Layout bleibt; kreuzt „Layout“ an, um es ebenfalls zu übernehmen.",
	["Accent follows the theme accent (General). Class uses your class color. Custom uses the color you pick."] = "Akzent folgt dem Akzent des Themas (Allgemein). Klasse verwendet Eure Klassenfarbe. Benutzerdefiniert verwendet die Farbe, die Ihr wählt.",
	["Accent, panels, sounds and scale for the whole UI."] = "Akzent, Panels, Töne und Skalierung für die gesamte Oberfläche.",
	["Accessibility"] = "Barrierefreiheit",
	["Accessibility preset %s applied."] = "Vorlage für Barrierefreiheit %s angewendet.",
	["Accessibility settings put back."] = "Einstellungen zur Barrierefreiheit wiederhergestellt.",
	["Accessibility: %s"] = "Barrierefreiheit: %s",
	["Accessibility: keep"] = "Barrierefreiheit: behalten",
	["Account-wide lists"] = "Accountweite Listen",
	["Account-wide lists (all)"] = "Accountweite Listen (alle)",
	["Achievements"] = "Erfolge",
	["Across from the screen point in the title to the same point of the frame: a higher number moves it right, a lower one left. Press Enter to apply."] = "Waagerecht vom Bildschirmpunkt im Titel zum selben Punkt des Rahmens: Eine höhere Zahl verschiebt ihn nach rechts, eine niedrigere nach links. Drückt die Eingabetaste zum Übernehmen.",
	["Action Bars and Cooldowns"] = "Aktionsleisten und Abklingzeiten",
	["Action bar procs"] = "Procs auf Aktionsleisten",
	["Action bars"] = "Aktionsleisten",
	["Action bars and buttons"] = "Aktionsleisten und -tasten",
	["Action button look, cooldown text and proc alerts"] = "Optik der Aktionstasten, Abklingzeittext und Proc-Hinweise",
	["Action buttons"] = "Aktionstasten",
	["Activate"] = "Aktivieren",
	["Activate added Edit Mode layouts"] = "Hinzugefügte Layouts im Bearbeitungsmodus aktivieren",
	["Acts for you: a spell you learn goes on an empty button with its key, out of combat."] = "Handelt für Euch: Ein Zauber, den Ihr lernt, kommt außerhalb des Kampfes mit seiner Taste auf eine leere Aktionstaste.",
	["Acts for you: when you learn a higher rank of a spell, your buttons with a lower rank get the new one, out of combat."] = "Handelt für Euch: Lernt Ihr einen höheren Rang eines Zaubers, erhalten Eure Aktionstasten mit niedrigerem Rang außerhalb des Kampfes den neuen.",
	["Acts for you: your class's out-of-combat spells (travel, tracking, poisons, pet care) go on the empty buttons of bars 4 and 5, out of combat."] = "Handelt für Euch: Die Zauber Eurer Klasse für außerhalb des Kampfes (Reisen, Aufspüren, Gifte, Tierpflege) kommen außerhalb des Kampfes auf die leeren Aktionstasten der Leisten 4 und 5.",
	["Add a spell"] = "Zauber hinzufügen",
	["Add the class macros"] = "Klassenmakros hinzufügen",
	["Add to Edit Mode"] = "Zum Bearbeitungsmodus hinzufügen",
	["Add to Edit Mode is off: %s."] = "Zum Bearbeitungsmodus hinzufügen ist aus: %s.",
	["Add to Edit Mode: EldoUI saves it as a new account layout for you, out of combat."] = "Zum Bearbeitungsmodus hinzufügen: EldoUI speichert es für Euch außerhalb des Kampfes als neues Account-Layout.",
	["AddOn list"] = "AddOn-Liste",
	["Added the Edit Mode layout %s and made it active."] = "Layout %s im Bearbeitungsmodus hinzugefügt und aktiviert.",
	["Added the Edit Mode layout %s."] = "Layout %s im Bearbeitungsmodus hinzugefügt.",
	["Addon messages are restricted right now. Sending continues when the restriction ends."] = "Addon-Nachrichten sind gerade eingeschränkt. Das Senden geht weiter, sobald die Einschränkung endet.",
	["Addon messages are restricted right now. The offer goes out when the restriction ends."] = "Addon-Nachrichten sind gerade eingeschränkt. Das Angebot wird gesendet, sobald die Einschränkung endet.",
	["Addon profiles"] = "Addon-Profile",
	["Addon profiles are set up when combat ends."] = "Addon-Profile werden eingerichtet, sobald der Kampf endet.",
	["Addon setups: %s"] = "Addon-Einrichtungen: %s",
	["Addon: %s"] = "Addon: %s",
	["Addons found"] = "Gefundene Addons",
	["Addons may not work out their own death analysis, so Blizzard's recap stays."] = "Addons dürfen keine eigene Todesanalyse erstellen, daher bleibt Blizzards Todesrückblick.",
	["Addons you already use"] = "Addons, die Ihr bereits verwendet",
	["Addons you use that do the same job as part of EldoUI, and who handles each job."] = "Addons, die Ihr verwendet und die dieselbe Aufgabe wie ein Teil von EldoUI übernehmen, und wer welche Aufgabe übernimmt.",
	["Address book and quick send"] = "Adressbuch und Schnellversand",
	["After High contrast"] = "Nach Hoher Kontrast",
	["After the time below without a fight, target, movement, cast or loot, every EldoUI frame dims. Any of those, or the Show HUD key, brings it back."] = "Nach der unten eingestellten Zeit ohne Kampf, Ziel, Bewegung, Zauber oder Beute werden alle EldoUI-Rahmen abgedunkelt. Eines davon oder die Taste HUD anzeigen holt sie zurück.",
	["Alegreya SC"] = "Alegreya SC",
	["Alerts, banners and messages"] = "Warnungen, Banner und Meldungen",
	["Alerts, toasts and banners"] = "Warnungen, Hinweise und Banner",
	["Alignment guides"] = "Ausrichtungshilfen",
	["All"] = "Alle",
	["All follow the skin"] = "Alle folgen dem Skin",
	["All frame positions"] = "Alle Rahmenpositionen",
	["All frames"] = "Alle Rahmen",
	["All frames reset to the current layout."] = "Alle Rahmen auf das aktuelle Layout zurückgesetzt.",
	["All lists"] = "Alle Listen",
	["All modules"] = "Alle Module",
	["All nine WoW: Forever dungeons have their own Journal pages, and quests say where they sit in their chain."] = "Alle neun Dungeons von WoW: Forever haben eigene Seiten im Tagebuch, und Quests zeigen, wo sie in ihrer Questreihe stehen.",
	["All of them already have the settings of %s: nothing to copy."] = "Alle haben bereits die Einstellungen von %s: Es gibt nichts zu kopieren.",
	["All set"] = "Alles bereit",
	["Alliance"] = "Allianz",
	["Alliance or Horde."] = "Allianz oder Horde.",
	["Allow list (only these)"] = "Erlaubnisliste (nur diese)",
	["Allow lists show only their spells; block lists hide them. Built-in lists keep their type."] = "Erlaubnislisten zeigen nur ihre Zauber; Sperrlisten blenden sie aus. Eingebaute Listen behalten ihren Typ.",
	["Already on"] = "Bereits an",
	["Already set"] = "Bereits gesetzt",
	["Already set on this character"] = "Bei diesem Charakter bereits gesetzt",
	["Also add the class macros"] = "Auch die Klassenmakros hinzufügen",
	["Also done by EldoUI"] = "Auch von EldoUI übernommen",
	["Also on this spot"] = "Auch an dieser Stelle",
	["Also on this spot: %s. Right-click to pick one."] = "Auch an dieser Stelle: %s. Rechtsklick, um einen auszuwählen.",
	["Also put class spells on empty buttons"] = "Auch Klassenzauber auf leere Aktionstasten legen",
	["Also turns off %s: EldoUI's modules take over their jobs."] = "Schaltet außerdem %s aus: EldoUIs Module übernehmen ihre Aufgaben.",
	["Also turns on Move and scale for %s in Blizzard UI."] = "Schaltet für %s außerdem Verschieben und skalieren in Blizzard-UI ein.",
	["Also used by %s. The change is theirs too."] = "Wird auch von %s verwendet. Die Änderung gilt auch für sie.",
	["Also used by %s. They get a new, empty profile Default, and the setup opens at their next login."] = "Wird auch von %s verwendet. Diese Charaktere erhalten ein neues, leeres Profil Default, und die Einrichtung öffnet sich bei ihrem nächsten Login.",
	["Also used by %s. They go back to the profile Default."] = "Wird auch von %s verwendet. Diese Charaktere wechseln zurück zum Profil Default.",
	["Alt"] = "Alt",
	["Alt overview"] = "Twink-Übersicht",
	["Alt setup"] = "Twink-Einrichtung",
	["Alt+drag its side panels to detach them."] = "Alt+Ziehen an den Seitenpanels löst sie ab.",
	["Alt-click"] = "Alt-Klick",
	["Always"] = "Immer",
	["Always (in the profile)"] = "Immer (im Profil)",
	["Always keeps dragged places in the profile. The others forget them at logout or when the window closes. Scales are always kept."] = "Immer behält gezogene Positionen im Profil. Die anderen vergessen sie beim Ausloggen oder wenn sich das Fenster schließt. Skalierungen bleiben immer erhalten.",
	["Always pays with your own gold."] = "Bezahlt immer mit Eurem eigenen Gold.",
	["Always show it"] = "Immer anzeigen",
	["Always show them"] = "Immer anzeigen",
	["Always shown"] = "Immer angezeigt",
	["Always: never fades. Combat only: in combat. Mouse over: while the mouse is on it. Minimal: in combat or with a target. Quiet: while you are active. A change below makes it Custom."] = "Immer: wird nie ausgeblendet. Nur im Kampf: im Kampf. Mouseover: solange die Maus darauf ist. Minimal: im Kampf oder mit Ziel. Ruhig: solange Ihr aktiv seid. Eine Änderung unten macht daraus Benutzerdefiniert.",
	["An EllesmereUI or ElvUI profile becomes an EldoUI layout. After the preview, apply it as a new profile or to this one; both can be undone."] = "Ein EllesmereUI- oder ElvUI-Profil wird zu einem EldoUI-Layout. Wendet es nach der Vorschau als neues Profil oder auf dieses an; beides lässt sich rückgängig machen.",
	["An NPC's title (Innkeeper, Flight Master). Outside instances only."] = "Der Titel eines NSCs (Gastwirt, Flugmeister). Nur außerhalb von Instanzen.",
	["An older copy of this contact."] = "Eine ältere Kopie dieses Kontakts.",
	["An older shape of this list."] = "Eine ältere Form dieser Liste.",
	["An open center for every class: three bar blocks in a row, unit frames low and far apart."] = "Eine offene Mitte für jede Klasse: drei Leistenblöcke nebeneinander, Einheitenrahmen tief und weit auseinander.",
	["An open middle and a quiet screen: high frames, the quietest skin and only what you need to play."] = "Eine offene Mitte und ein ruhiger Bildschirm: hohe Rahmen, der ruhigste Skin und nur, was Ihr zum Spielen braucht.",
	["Anchor"] = "Ankerpunkt",
	["And %d more."] = { one = "Und %d weiterer.", other = "Und %d weitere." },
	["Animations"] = "Animationen",
	["Ankh"] = "Ankh",
	["Another character set up EldoUI on this account already. Pick the profile this character should use: the profile stays as it is, and only this character's own parts are set up. Attach keeps a backup first."] = "Ein anderer Charakter hat EldoUI auf diesem Account bereits eingerichtet. Wählt das Profil, das dieser Charakter verwenden soll: Das Profil bleibt, wie es ist, und nur die eigenen Teile dieses Charakters werden eingerichtet. Zuordnen legt zuerst eine Sicherung an.",
	["Another character set up EldoUI on this account. Put this one on a profile you already have, as it is: only this character's own parts are set up."] = "Ein anderer Charakter hat EldoUI auf diesem Account eingerichtet. Ordnet diesen einem Profil zu, das Ihr bereits habt, so wie es ist: Nur die eigenen Teile dieses Charakters werden eingerichtet.",
	["Another tank has it"] = "Anderer Tank hat die Aggro",
	["Answer in the addon's own window to finish: %s"] = "Antwortet im eigenen Fenster des Addons, um abzuschließen: %s",
	["Any"] = "Beliebig",
	["Any empty part of the window"] = "Jeder leere Teil des Fensters",
	["Appearance"] = "Aussehen",
	["Applied"] = "Angewendet",
	["Applied %d parts of the bundle."] = { one = "%d Teil des Bündels angewendet.", other = "%d Teile des Bündels angewendet." },
	["Applied last"] = "Zuletzt angewendet",
	["Applies at Finish"] = "Wird beim Abschließen übernommen",
	["Applies at once. The first full look keeps following your layout's skin."] = "Wirkt sofort. Die erste vollständige Optik folgt weiterhin dem Skin Eures Layouts.",
	["Applies every pick you haven't applied yet and shows what changed."] = "Wendet jede noch nicht angewendete Auswahl an und zeigt, was sich geändert hat.",
	["Applies the summary above. Parts on Keep stay exactly as they are."] = "Wendet die Zusammenfassung oben an. Teile auf Behalten bleiben genau, wie sie sind.",
	["Applies this step's pick and goes on to the next step. It also keeps the previews you picked on the steps before."] = "Wendet die Auswahl dieses Schritts an und geht zum nächsten Schritt. Die Vorschauen, die Ihr in den vorherigen Schritten gewählt habt, bleiben ebenfalls erhalten.",
	["Apply"] = "Übernehmen",
	["Apply %s"] = "%s übernehmen",
	["Apply %s to all of them"] = "%s auf alle übernehmen",
	["Apply %s?\n\n%s.\n\nOnly empty buttons get a spell and your own actions stay. Your current keys are saved first, and Undo puts everything back."] = "%s übernehmen?\n\n%s.\n\nNur leere Aktionstasten erhalten einen Zauber, und Eure eigenen Aktionen bleiben. Eure aktuellen Tasten werden zuerst gesichert, und Rückgängig stellt alles wieder her.",
	["Apply UI amount"] = "UI-Umfang übernehmen",
	["Apply a layout"] = "Layout anwenden",
	["Apply a preset pack in one click, or go through the steps: each one shows its pick at once, and %s puts it back."] = "Wendet mit einem Klick ein Vorlagenpaket an oder geht die Schritte durch: Jeder zeigt seine Auswahl sofort, und %s macht sie rückgängig.",
	["Apply also turns on auto repair (your own gold), junk selling and fast loot."] = "Übernehmen schaltet außerdem automatische Reparatur (mit Eurem eigenen Gold), Verkauf von Plunder und schnelles Plündern ein.",
	["Apply and continue"] = "Übernehmen und weiter",
	["Apply as a new layout"] = "Als neues Layout anwenden",
	["Apply can also put your known class spells on empty buttons of bars 1 to 3. A button with your own action keeps it, and nothing moves by itself later: after you learn new spells, apply again to fill their buttons."] = "Übernehmen kann Eure bekannten Klassenzauber auch auf leere Aktionstasten der Leisten 1 bis 3 legen. Eine Aktionstaste mit Eurer eigenen Aktion behält sie, und später verschiebt sich nichts von selbst: Wenn Ihr neue Zauber gelernt habt, übernehmt erneut, um ihre Aktionstasten zu füllen.",
	["Apply checked parts"] = "Angehakte Teile übernehmen",
	["Apply complete look"] = "Komplette Optik übernehmen",
	["Apply the %s keys and class spells?\n\n%s.\n\nOnly empty buttons get a spell: your own actions stay, and nothing moves. Your current keys are saved first, and Undo puts back the keys and takes the spells off again."] = "Tasten und Klassenzauber von %s übernehmen?\n\n%s.\n\nNur leere Aktionstasten erhalten einen Zauber: Eure eigenen Aktionen bleiben, und nichts wird verschoben. Eure aktuellen Tasten werden zuerst gesichert, und Rückgängig stellt die Tasten wieder her und nimmt die Zauber wieder herunter.",
	["Apply the %s keys?\n\n%s.\n\nOnly keys change: spells and bars stay as they are. Your current keys are saved first, and Undo last key set puts them back."] = "Tasten von %s übernehmen?\n\n%s.\n\nNur Tasten ändern sich: Zauber und Leisten bleiben, wie sie sind. Eure aktuellen Tasten werden zuerst gesichert, und „Letzten Tastensatz rückgängig“ stellt sie wieder her.",
	["Apply the pack"] = "Paket übernehmen",
	["Apply to all (%d)"] = "Auf alle übernehmen (%d)",
	["April"] = "April",
	["Arcane"] = "Arkan",
	["Arcane Intellect and armor reminders you click to cast, the consumable bar with conjured food and water first and your mana gem, the travel button for your teleports and portals, rune and powder counters with a restock, conjuring, Evocation and Blink on empty action slots, and a mana gem macro. The class bar shows your buffs, key cooldowns and reagents"] = "Erinnerungen an Arkane Intelligenz und Rüstung, die Ihr zum Wirken anklickt, die Verbrauchsgüterleiste mit herbeigezauberten Speisen und Getränken zuerst und Eurem Manaedelstein, die Reisetaste für Eure Teleporte und Portale, Zähler für Runen und Pulver mit Nachkauf, Herbeizaubern, Hervorrufung und Blinzeln auf leeren Aktionsplätzen und ein Makro für den Manaedelstein. Die Klassenleiste zeigt Eure Stärkungszauber, wichtigen Abklingzeiten und Reagenzien",
	["Arcane Powder"] = "Arkanes Pulver",
	["Arcane resistance"] = "Arkanwiderstand",
	["Are you sure?"] = "Seid Ihr sicher?",
	["Area, finisher or resource spells for your role."] = "Flächen-, Finisher- oder Ressourcenzauber für Eure Rolle.",
	["Arrow across"] = "Pfeil waagerecht",
	["Arrow anchor"] = "Ankerpunkt des Pfeils",
	["Arrow anchor on the screen"] = "Ankerpunkt des Pfeils auf dem Bildschirm",
	["Arrow on the layout's waypoint arrow spot"] = "Pfeil an der Stelle des Wegpunktpfeils im Layout",
	["Arrow up and down"] = "Pfeil senkrecht",
	["As the game shows it"] = "So, wie das Spiel es zeigt",
	["Ashwood Seed"] = "Eschenholzsamen",
	["Ask when you start using a controller"] = "Fragen, sobald Ihr einen Controller benutzt",
	["Asks again at your next login."] = "Fragt beim nächsten Einloggen erneut.",
	["Asks once more, then sets the keys shown, the class spells and macros you checked and the checked spell ranks."] = "Fragt noch einmal nach und setzt dann die gezeigten Tasten, die angehakten Klassenzauber und Makros und die angehakten Zauberränge.",
	["At Finish, %s is turned off for this character (after one reload) and EldoUI does this job."] = "Beim Abschließen wird %s für diesen Charakter ausgeschaltet (nach einem Neuladen), und EldoUI übernimmt diese Aufgabe.",
	["At least 40 pixels of every window stay on screen, so you can always grab it again."] = "Von jedem Fenster bleiben mindestens 40 Pixel auf dem Bildschirm, damit Ihr es immer wieder greifen könnt.",
	["At most this many icons from this group. Share: an equal share of the widget's icon limit."] = "Höchstens so viele Symbole aus dieser Gruppe. Anteil: ein gleicher Anteil am Symbollimit des Widgets.",
	["At your next login or /reload this part is brought up to date again. The copy from before the update stays."] = "Beim nächsten Einloggen oder /reload wird dieser Teil wieder aktualisiert. Die Kopie von vor dem Update bleibt erhalten.",
	["Attach"] = "Zuordnen",
	["Attach anyway"] = "Trotzdem zuordnen",
	["Attach this character to..."] = "Diesen Charakter zuordnen zu...",
	["Attach to"] = "Anheften an",
	["Attached to %s (%s)"] = "Angeheftet an %s (%s)",
	["Auction house"] = "Auktionshaus",
	["Auction price line"] = "Auktionspreiszeile",
	["August"] = "August",
	["Aura expiring"] = "Aura läuft ab",
	["Aura filters"] = "Aurenfilter",
	["Aura icons"] = "Aurensymbole",
	["Aura pop-in"] = "Aura-Einblendung",
	["Auras and cooldowns: The Healthstone reminder shows only when you or a warlock in your group can make one, so a warlock who has not learned Create Healthstone yet is no longer asked for one."] = "Auren und Abklingzeiten: Die Erinnerung an Gesundheitssteine erscheint nur, wenn Ihr oder ein Hexenmeister in Eurer Gruppe einen herstellen könnt, daher wird ein Hexenmeister, der Gesundheitsstein herstellen noch nicht erlernt hat, nicht mehr danach gefragt.",
	["Auras the game marks as boss auras."] = "Auren, die das Spiel als Bossauren markiert.",
	["Auras the game shows on all nameplates."] = "Auren, die das Spiel auf allen Namensplaketten zeigt.",
	["Auras the game shows on your personal resource display."] = "Auren, die das Spiel auf Eurer persönlichen Ressourcenanzeige zeigt.",
	["Auras the game shows with priority on raid frames."] = "Auren, die das Spiel auf Schlachtzugsrahmen bevorzugt zeigt.",
	["Auto UI scale keeps the full layout width on 16:10 screens."] = "Die automatische UI-Skalierung behält auf 16:10-Bildschirmen die volle Layoutbreite.",
	["Auto draws every screen as the 2560x1440 canvas the layouts are made on, so they look as designed. Pixel perfect makes one UI unit one pixel; frames keep their 1440p size and can overlap."] = "Auto stellt jeden Bildschirm als die 2560x1440-Fläche dar, für die die Layouts gemacht sind, sodass sie wie entworfen aussehen. Pixelgenau macht eine UI-Einheit zu einem Pixel; Rahmen behalten ihre 1440p-Größe und können sich überlappen.",
	["Auto: 1440p (%.4f)"] = "Auto: 1440p (%.4f)",
	["Auto: 1440p (recommended)"] = "Auto: 1440p (empfohlen)",
	["Auto: your character's faction"] = "Auto: Fraktion Eures Charakters",
	["Automatic spell rank upgrades now cover every action bar you use and keep lower ranks you place by hand."] = "Automatische Rangverbesserungen für Zauber umfassen jetzt jede Aktionsleiste, die Ihr nutzt, und behalten niedrigere Ränge, die Ihr von Hand platziert.",
	["Autorun"] = "Automatisch laufen",
	["Back"] = "Zurück",
	["Back to its layout position (also Shift-right-click on the frame)."] = "Zurück an seine Layoutposition (auch Umschalt-Rechtsklick auf den Rahmen).",
	["Back up my setup"] = "Meine Einrichtung sichern",
	["Backed up"] = "Gesichert",
	["Backups"] = "Sicherungen",
	["Backups can be put back out of combat only."] = "Sicherungen lassen sich nur außerhalb des Kampfes wiederherstellen.",
	["Bad"] = "Schlecht",
	["Bag Bar"] = "Taschenleiste",
	["Bag and bank windows share the same look and stay sharp at any window scale."] = "Taschen- und Bankfenster teilen dieselbe Optik und bleiben bei jeder Fensterskalierung scharf.",
	["Bag bar"] = "Taschenleiste",
	["Bag bar (backpack, bag slots, keyring)"] = "Taschenleiste (Rucksack, Taschenplätze, Schlüsselbund)",
	["Bags"] = "Taschen",
	["Bags (container windows)"] = "Taschen (Behälterfenster)",
	["Bags and Economy"] = "Taschen und Wirtschaft",
	["Bags and loot: EldoUI's bank window offers more bank space again: a button on its side bar buys the next bank tab, with its price and the game's own confirmation, also when the bag bar is off."] = "Taschen und Beute: Das Bankfenster von EldoUI bietet wieder mehr Bankplatz: Eine Schaltfläche auf seiner Seitenleiste kauft den nächsten Bankreiter, mit seinem Preis und der Bestätigung des Spiels, auch wenn die Taschenleiste aus ist.",
	["Bags and loot: Every item in the loot window shows, also one whose details the game keeps hidden, and a row from the last loot no longer disappears under a new item."] = "Taschen und Beute: Das Beutefenster zeigt jeden Gegenstand, auch einen, dessen Details das Spiel verbirgt, und eine Zeile der letzten Beute verschwindet nicht mehr unter einem neuen Gegenstand.",
	["Bags and loot: Every loot roll gets its roll bar at once, also while the item's details are still loading, so no roll is missed or shown in the game's own window instead."] = "Taschen und Beute: Jeder Beutewurf bekommt sofort seine Würfelleiste, auch solange die Details des Gegenstands noch laden, sodass kein Wurf verpasst oder stattdessen im Fenster des Spiels gezeigt wird.",
	["Bags and loot: Right-clicking a potion, food or other usable item in the bag window uses it again."] = "Taschen und Beute: Ein Rechtsklick auf einen Trank, Essen oder einen anderen benutzbaren Gegenstand im Taschenfenster benutzt ihn wieder.",
	["Bags and loot: Roll bars stay in the order their rolls started, so a new roll joins at the end instead of pushing the others down."] = "Taschen und Beute: Würfelleisten bleiben in der Reihenfolge, in der ihre Würfe begonnen haben, sodass ein neuer Wurf hinten anschließt, statt die anderen nach unten zu schieben.",
	["Bags and loot: The Consumable Bar can show a button each for your cure against disease, bleeding and poison, picking the one that fits your level, and each can get a key."] = "Taschen und Beute: Die Verbrauchsgüterleiste kann je eine Schaltfläche für Euer Mittel gegen Krankheit, Blutung und Gift zeigen, mit dem Mittel, das zu Eurer Stufe passt, und jede kann eine Taste bekommen.",
	["Bags and loot: The game's own roll windows no longer reappear over the action bars after a loading screen while EldoUI's roll bars replace them."] = "Taschen und Beute: Die Würfelfenster des Spiels tauchen nach einem Ladebildschirm nicht mehr über den Aktionsleisten auf, solange die Würfelleisten von EldoUI sie ersetzen.",
	["Bags and loot: The loot window closes with Escape, closing it ends the loot, an empty corpse or chest no longer leaves the loot open, and a leftover loot confirmation closes with the loot."] = "Taschen und Beute: Das Beutefenster schließt mit Esc, Schließen beendet das Plündern, eine leere Leiche oder Truhe lässt die Beute nicht mehr offen, und eine übrig gebliebene Beutebestätigung schließt sich mit der Beute.",
	["Bags and loot: Turning off the loot window's Move switch gives the game's loot window its own scale back without upsetting Edit Mode."] = "Taschen und Beute: Schaltet Ihr das Verschieben des Beutefensters aus, bekommt das Beutefenster des Spiels seine eigene Skalierung zurück, ohne den Bearbeitungsmodus durcheinanderzubringen.",
	["Bags and loot: With the game's roll windows moved, each one opens directly on the roll spot and stays where it opened while other rolls start and end."] = "Taschen und Beute: Sind die Würfelfenster des Spiels verschoben, öffnet sich jedes direkt am Würfelplatz und bleibt, wo es sich geöffnet hat, während andere Würfe beginnen und enden.",
	["Bags on the layout's bag corner"] = "Taschen in der Taschenecke des Layouts",
	["Bags, bank, merchant, mail, auction house, trade, loot and rolls, quest/gossip dialogs, stable and barber."] = "Taschen, Bank, Händler, Post, Auktionshaus, Handel, Beute und Würfe, Quest- und Gesprächsdialoge, Stall und Barbier.",
	["Bank and guild bank"] = "Bank und Gildenbank",
	["Bank on the layout's bank corner"] = "Bank in der Bankecke des Layouts",
	["Bar %d is here"] = "Leiste %d ist hier",
	["Bar %d page 2, button %d"] = "Leiste %d Seite 2, Platz %d",
	["Bar %d shows another bar while %s is held, and %s is part of your keys there."] = "Leiste %d zeigt eine andere Leiste, solange %s gedrückt ist, und %s gehört dort zu Euren Tasten.",
	["Bar %d, button %d"] = "Leiste %d, Platz %d",
	["Bar %d, button %d: %s"] = "Leiste %d, Platz %d: %s",
	["Bar %d, button %d: kept your own action (%s not placed)"] = "Leiste %d, Platz %d: Eure eigene Aktion behalten (%s nicht platziert)",
	["Bar %d: %s + key"] = "Leiste %d: %s + Taste",
	["Bar %d: Shift + side button"] = "Leiste %d: Umschalt + Seitentaste",
	["Bar %d: plain keys"] = "Leiste %d: einfache Tasten",
	["Bar %d: the side buttons"] = "Leiste %d: die Seitentasten",
	["Bar %s appears when you point at its spot. Its buttons and keys always work."] = "Leiste %s erscheint, wenn Ihr auf ihre Stelle zeigt. Ihre Aktionstasten und Tasten funktionieren immer.",
	["Bar 1 on 12 side buttons, Shift for bar 2."] = "Leiste 1 auf 12 Seitentasten, Umschalt für Leiste 2.",
	["Bar 1 shows your stance page, so its class spells are only shown: put them on the stance you use."] = "Leiste 1 zeigt Eure Haltungsseite, daher werden ihre Klassenzauber nur angezeigt: Legt sie auf die Haltung, die Ihr nutzt.",
	["Bar 1 stance page %d, button %d"] = "Leiste 1 Haltungsseite %d, Platz %d",
	["Bar 10"] = "Leiste 10",
	["Bar 1: 1 to =, bar 2: Shift + 1 to =, bar 3: Ctrl + 1 to =. Movement keys stay as they are."] = "Leiste 1: 1 bis =, Leiste 2: Umschalt + 1 bis =, Leiste 3: Strg + 1 bis =. Bewegungstasten bleiben, wie sie sind.",
	["Bar 1: 1 to =. Shift and Ctrl for bars 2 and 3."] = "Leiste 1: 1 bis =. Umschalt und Strg für die Leisten 2 und 3.",
	["Bar 2"] = "Leiste 2",
	["Bar 3"] = "Leiste 3",
	["Bar 3 button %d keeps its action (%s), no key from the set."] = "Leiste 3, Platz %d behält seine Aktion (%s), keine Taste aus dem Schema.",
	["Bar 3 has 9 buttons; its last three keys use the Consumable Bar: health potion, healthstone, and mana potion or bandage."] = "Leiste 3 hat 9 Plätze; ihre letzten drei Tasten nutzen die Verbrauchsgüterleiste: Heiltrank, Gesundheitsstein und Manatrank oder Verband.",
	["Bar 4"] = "Leiste 4",
	["Bar 4 and the other bars stay manual: their keys and spells are yours."] = "Leiste 4 und die anderen Leisten bleiben manuell, mit Euren eigenen Tasten und Zaubern.",
	["Bar 4 and the other bars: Manual. They keep their keys and spells; a key they hold stays theirs unless you give it below. A button marked ~ is hidden in this layout: its key works."] = "Leiste 4 und die anderen Leisten: Manuell. Sie behalten ihre Tasten und Zauber; eine Taste, die sie belegen, bleibt bei ihnen, außer Ihr vergebt sie unten. Eine mit ~ markierte Aktionstaste ist in diesem Layout ausgeblendet, ihre Taste funktioniert aber.",
	["Bar 5"] = "Leiste 5",
	["Bar 6"] = "Leiste 6",
	["Bar 7"] = "Leiste 7",
	["Bar 8"] = "Leiste 8",
	["Bar 9"] = "Leiste 9",
	["Bar across"] = "Leiste waagerecht",
	["Bar anchor"] = "Ankerpunkt der Leiste",
	["Bar anchor on the screen"] = "Ankerpunkt der Leiste auf dem Bildschirm",
	["Bar layout"] = "Leistenlayout",
	["Bar on the layout's data bar edge"] = "Leiste am Datenleistenrand des Layouts",
	["Bar page key: taken off, so bar 1 never swaps its spells in a fight."] = "Taste für Leistenseiten: entfernt, damit Leiste 1 im Kampf nie ihre Zauber wechselt.",
	["Bar texture"] = "Leistentextur",
	["Bar texture, smooth bars, panel opacity and tint, frame shadows and every module's bar texture in one place."] = "Leistentextur, sanfte Leisten, Deckkraft und Farbton der Panels, Rahmenschatten und die Leistentextur jedes Moduls an einem Ort.",
	["Bar up and down"] = "Leiste senkrecht",
	["Barber shop and character customization"] = "Barbier und Charakteranpassung",
	["Barlow Condensed"] = "Barlow Condensed",
	["Bars"] = "Leisten",
	["Bars %s appear when you point at their spot. Their buttons and keys always work."] = "Leisten %s erscheinen, wenn Ihr auf ihre Stelle zeigt. Ihre Aktionstasten und Tasten funktionieren immer.",
	["Bars 1 to 3 hide their keys, so you can't see the keys you just set."] = "Die Leisten 1 bis 3 blenden ihre Tasten aus, daher seht Ihr die gerade gesetzten Tasten nicht.",
	["Bars 1-8, pet, stance and vehicle bars, the zone ability, the totem bar, button look and gamepad bar. Changes wait until out of combat."] = "Leisten 1-8, Begleiter-, Haltungs- und Fahrzeugleisten, die Zonenfähigkeit, die Totemleiste, die Optik der Aktionstasten und die Gamepad-Leiste. Änderungen warten bis nach dem Kampf.",
	["Bars 4 and 5 filled: %s. /eui fillbars undo takes them off again."] = "Leisten 4 und 5 gefüllt: %s. /eui fillbars undo nimmt sie wieder herunter.",
	["Bars glide to new values instead of jumping. The game animates them, so this works in combat too."] = "Leisten gleiten zu neuen Werten, statt zu springen. Das Spiel animiert sie, daher funktioniert das auch im Kampf.",
	["Bars that show on mouse-over"] = "Leisten, die bei Mauskontakt erscheinen",
	["Base"] = "Basis",
	["Base size of the countdown numbers; 16 is normal. Action bars, bag slots and aura icons scale their own number size by this."] = "Grundgröße der Countdown-Zahlen; 16 ist normal. Aktionsleisten, Taschenplätze und Aurensymbole skalieren ihre eigene Zahlengröße danach.",
	["Base text size of EldoUI windows and bars."] = "Grundtextgröße von Fenstern und Leisten von EldoUI.",
	["Bash, on Hard control in Bear Form, is the druid stop."] = "Hieb auf Harte Kontrolle in Bärengestalt ist der Stopp des Druiden.",
	["Bash, on Hard control, is the bear's stop."] = "Hieb auf Harte Kontrolle ist der Stopp des Bären.",
	["Battlefield (zone) map"] = "Schlachtfeldkarte (Gebiet)",
	["Battleground"] = "Schlachtfeld",
	["Before an update changes a saved part, EldoUI keeps a copy of it. Restore puts a copy back and keeps what it replaces."] = "Bevor ein Update einen gespeicherten Teil ändert, bewahrt EldoUI eine Kopie davon auf. Wiederherstellen legt eine Kopie zurück und bewahrt auf, was sie ersetzt.",
	["Behavior"] = "Verhalten",
	["Below"] = "Unterhalb",
	["Below health"] = "Unter der Gesundheit",
	["Below power"] = "Unter der Ressource",
	["Beside the center"] = "Neben der Mitte",
	["Big group tiles with heals on the way, unit frames close to the center and the healer role with click-casting suggestions."] = "Große Gruppenkacheln mit eingehenden Heilungen, Einheitenrahmen nahe der Mitte und die Heilerrolle mit Vorschlägen für Klickzauber.",
	["Big heal"] = "Große Heilung",
	["Big numbers"] = "Große Zahlen",
	["BigWigs Bossmods"] = "BigWigs Bossmods",
	["BigWigs: if BigWigs switches profiles by specialization, a spec change can move it off the EldoUI profile. EldoUI leaves that setting alone; set the EldoUI profile for each spec in BigWigs' own Profiles page if you want it everywhere."] = "BigWigs: Wechselt BigWigs die Profile nach Spezialisierung, kann ein Wechsel der Spezialisierung es vom EldoUI-Profil wegbringen. EldoUI lässt diese Einstellung unverändert; setzt das EldoUI-Profil für jede Spezialisierung auf der Profilseite von BigWigs selbst, wenn Ihr es überall wollt.",
	["BigWigs: the EldoUI profile was not imported."] = "BigWigs: Das EldoUI-Profil wurde nicht importiert.",
	["Bind the spells checked below to clicks on party and raid frames. Nothing is bound unless this is checked."] = "Belegt die unten angehakten Zauber mit Klicks auf Gruppen- und Schlachtzugsrahmen. Ohne diesen Haken wird nichts belegt.",
	["Bl"] = "Bl",
	["Black"] = "Schwarz",
	["Black opaque panels with bright 2-pixel borders (the High contrast art style) and a thick outline on every EldoUI text. Off puts back the art style and outline you had."] = "Schwarze, deckende Panels mit hellen 2-Pixel-Rändern (der Grafikstil Hoher Kontrast) und eine dicke Kontur um jeden EldoUI-Text. Aus stellt den vorherigen Grafikstil und die Kontur wieder her.",
	["Black opaque panels with bright 2-pixel borders and a thick outline on every EldoUI text. It takes the place of the skin; turning it off in /eui puts that skin back."] = "Schwarze, deckende Panels mit hellen 2-Pixel-Rändern und eine dicke Kontur um jeden EldoUI-Text. Ersetzt den Skin; schaltet Ihr es in /eui aus, kehrt dieser Skin zurück.",
	["Black opaque panels with bright borders and a thick text outline."] = "Schwarze, deckende Panels mit hellen Rändern und dicker Textkontur.",
	["Black panels with bright 2-pixel borders and no transparency, for low vision (Accessibility page)."] = "Schwarze Panels mit hellen 2-Pixel-Rändern ohne Transparenz, für Sehschwäche (Seite Barrierefreiheit).",
	["Bleed"] = "Blutung",
	["Blessing and aura reminders and spells for your role"] = "Erinnerungen an Segen und Auren und Zauber für Eure Rolle",
	["Blessing and aura reminders you click to cast, Righteous Fury for tanks, symbol counters with a restock, and Judgement, your defensive spells and a spell for your role on empty action slots. The class bar shows your buffs, key cooldowns and reagents"] = "Erinnerungen an Segen und Auren, die Ihr zum Wirken anklickt, Zorn der Gerechtigkeit für Tanks, Zähler für Symbole mit Nachkauf sowie Richturteil, Eure Defensivzauber und ein Zauber für Eure Rolle auf leeren Aktionsplätzen. Die Klassenleiste zeigt Eure Stärkungszauber, wichtigen Abklingzeiten und Reagenzien",
	["Blessing of Freedom, on the Movement ability button, is the paladin's movement spell."] = "Segen der Freiheit auf der Taste Bewegungsfähigkeit ist der Bewegungszauber des Paladins.",
	["Blinding Powder"] = "Blendungspulver",
	["Blizzard"] = "Blizzard",
	["Blizzard Bottom Block"] = "Blizzard Bottom Block",
	["Blizzard Bottom Block (1440p)"] = "Blizzard Bottom Block (1440p)",
	["Blizzard Edit Mode"] = "Blizzard-Bearbeitungsmodus",
	["Blizzard Edit Mode layout"] = "Layout des Blizzard-Bearbeitungsmodus",
	["Blizzard Edit Mode layout with %d frames, added as a new Edit Mode layout."] = { one = "Layout des Blizzard-Bearbeitungsmodus mit %d Rahmen, als neues Layout im Bearbeitungsmodus hinzugefügt.", other = "Layout des Blizzard-Bearbeitungsmodus mit %d Rahmen, als neues Layout im Bearbeitungsmodus hinzugefügt." },
	["Blizzard Edit Mode layout: %d"] = "Layout des Blizzard-Bearbeitungsmodus: %d",
	["Blizzard UI"] = "Blizzard-UI",
	["Blizzard UI > Edit Mode integration needs \"Let EldoUI change this\" and Improve switched on (or use Copy for Edit Mode)"] = "Blizzard-UI > Einbindung des Bearbeitungsmodus braucht „EldoUI dies ändern lassen“ und eingeschaltetes Verbessern (oder nutzt Für Bearbeitungsmodus kopieren)",
	["Blizzard UI switches"] = "Schalter für die Blizzard-UI",
	["Blizzard UI: %s"] = "Blizzard-UI: %s",
	["Blizzard UI: keep"] = "Blizzard-UI: behalten",
	["Blizzard Windows"] = "Blizzard-Fenster",
	["Blizzard default colors"] = "Blizzard-Standardfarben",
	["Blizzard default for %s"] = "Blizzard-Standard für %s",
	["Blizzard default for %s."] = "Blizzard-Standard für %s.",
	["Blizzard default for everything"] = "Blizzard-Standard für alles",
	["Blizzard default for this tab"] = "Blizzard-Standard für diesen Reiter",
	["Blizzard proc: the game's own proc animation (buttons only). Pixel lines: lines running round the frame. Sparkle: dots circling the frame. Pulse: a border that fades in and out. None: no glow."] = "Blizzard-Proc: die eigene Proc-Animation des Spiels (nur Aktionstasten). Pixellinien: Linien, die um den Rahmen laufen. Funkeln: Punkte, die den Rahmen umkreisen. Puls: ein Rand, der ein- und ausblendet. Nichts: kein Leuchten.",
	["Blizzard windows"] = "Blizzard-Fenster",
	["Blizzard windows keep the look set on the Blizzard UI page."] = "Blizzard-Fenster behalten die Optik, die auf der Seite Blizzard-UI eingestellt ist.",
	["Blizzard windows: %s"] = "Blizzard-Fenster: %s",
	["Blizzard windows: Match skin, for the windows you let EldoUI change."] = "Blizzard-Fenster: An Skin anpassen, für die Fenster, die EldoUI ändern darf.",
	["Blizzard windows: Original. Taking a skin off needs a reload."] = "Blizzard-Fenster: Original. Einen Skin zu entfernen erfordert ein Neuladen.",
	["Blizzard windows: stay as set."] = "Blizzard-Fenster: bleiben wie eingestellt.",
	["Blizzard's Edit Mode doesn't accept this layout text on this client (it may come from a newer game version)"] = "Blizzards Bearbeitungsmodus akzeptiert diesen Layouttext in diesem Client nicht (er stammt womöglich aus einer neueren Spielversion)",
	["Blizzard's Edit Mode isn't loaded yet"] = "Blizzards Bearbeitungsmodus ist noch nicht geladen",
	["Blizzard's active Edit Mode layout as text, to share or keep."] = "Blizzards aktives Layout des Bearbeitungsmodus als Text, zum Teilen oder Aufbewahren.",
	["Blizzard's combat displays, which EldoUI may skin and place but never rebuild: Cooldown Manager, damage meter, swing timer and more."] = "Blizzards Kampfanzeigen, die EldoUI mit Skin versehen und platzieren, aber nie nachbauen darf: Abklingzeitenmanager, Schadensmesser, Schlagtimer und mehr.",
