	["Click casting"] = "Klickzauber",
	["Click-cast bindings are kept per class in the profile. A class that has none there yet gets the healer suggestions for its spells; another class's bindings stay as they are."] = "Klickzauber-Belegungen werden im Profil pro Klasse gespeichert. Eine Klasse, die dort noch keine hat, erhält die Heilervorschläge für ihre Zauber; die Belegungen anderer Klassen bleiben, wie sie sind.",
	["Click-casting"] = "Klickzauber",
	["Click-casting on party and raid frames"] = "Klickzauber auf Gruppen- und Schlachtzugsrahmen",
