	["Close Combat (1440p)"] = "Close Combat (1440p)",
	["Close Edit Mode first, then press Restore now again."] = "Schließt zuerst den Bearbeitungsmodus und drückt dann erneut Jetzt wiederherstellen.",
	["Close the setup for good: it doesn't open at login again. Closing the window instead pauses it, and /eui install goes on where you stopped."] = "Schließt die Einrichtung endgültig: Sie öffnet sich beim Einloggen nicht mehr. Schließt Ihr stattdessen das Fenster, wird sie pausiert, und /eui install macht dort weiter, wo Ihr aufgehört habt.",
	["Close-range damage. Frames stay where the layout puts them, party frames are a little more compact."] = "Nahkampfschaden. Rahmen bleiben, wo das Layout sie platziert, Gruppenrahmen sind etwas kompakter.",
	["Close: do it later"] = "Schließen: später erledigen",
	["Closes the setup and opens move mode, so you can drag the frames apart."] = "Schließt die Einrichtung und öffnet den Verschiebemodus, damit Ihr die Rahmen auseinanderziehen könnt.",
	["Coin icons"] = "Münzsymbole",
	["Collections"] = "Sammlungen",
	["Collections (mounts, pets, toys, heirlooms, appearances)"] = "Sammlungen (Reittiere, Begleiter, Spielzeuge, Erbstücke, Vorlagen)",
	["Collections and Progress"] = "Sammlungen und Fortschritt",
	["Color"] = "Farbe",
	["Color of countdown numbers about to end."] = "Farbe von Countdown-Zahlen kurz vor dem Ende.",
	["Color of countdown numbers of a minute or more."] = "Farbe von Countdown-Zahlen ab einer Minute.",
	["Color of countdown numbers under a minute."] = "Farbe von Countdown-Zahlen unter einer Minute.",
	["Color of the glow when Color is set to Custom color."] = "Farbe des Leuchtens, wenn Farbe auf Eigene Farbe steht.",
	["Color of the grid lines in move mode. The two center lines use the accent color (white when the grid itself is in the accent color)."] = "Farbe der Rasterlinien im Verschiebemodus. Die beiden Mittellinien verwenden die Akzentfarbe (weiß, wenn das Raster selbst in der Akzentfarbe ist).",
	["Color-blind safe"] = "Farbenblind-sicher",
	["Color-blind safe colors"] = "Farbenblind-sichere Farben",
	["Color-blind safe colors for reactions, threat, dispel types, unit states and status text. Follow the game uses them while the game's color-blind mode is on. Your own picked colors stay."] = "Farbenblind-sichere Farben für Reaktionen, Bedrohung, Banntypen, Einheitenzustände und Statustext. Dem Spiel folgen verwendet sie, solange der Farbenblindmodus des Spiels an ist. Eure selbst gewählten Farben bleiben.",
	["Colors"] = "Farben",
	["Colors EldoUI uses for classes, power, reactions, dispel types and threat. Everything starts as the game's own colors or EldoUI's defaults."] = "Farben, die EldoUI für Klassen, Ressourcen, Reaktionen, Banntypen und Bedrohung verwendet. Alles beginnt mit den eigenen Farben des Spiels oder den Standardwerten von EldoUI.",
	["Combat"] = "Kampf",
	["Combat HUD"] = "Kampf-HUD",
	["Combat Info"] = "Kampfinfo",
	["Combat mode"] = "Kampfmodus",
	["Combat mode shows the frames of your everyday fight screen: unit and group frames, bars, cooldowns, combat text, boss timers, alerts, minimap and chat. All frames adds windows, toasts and the rest; a group shows only that group. Find a frame, at the end of the list, shows the box of any frame, also one outside the screen."] = "Kampfmodus zeigt die Rahmen Eures alltäglichen Kampfbildschirms: Einheiten- und Gruppenrahmen, Leisten, Abklingzeiten, Kampftext, Bosstimer, Warnungen, Minikarte und Chat. Alle Rahmen ergänzt Fenster, Hinweise und den Rest; eine Gruppe zeigt nur diese Gruppe. Rahmen finden am Ende der Liste zeigt das Feld jedes Rahmens, auch eines außerhalb des Bildschirms.",
	["Combat only"] = "Nur im Kampf",
	["Combat while the unit is in combat (when the game shows it)."] = "Kampf, solange die Einheit im Kampf ist (wenn das Spiel es zeigt).",
	["Combo Points"] = "Kombopunkte",
	["Combo point height"] = "Höhe der Kombopunkte",
	["Combo points"] = "Kombopunkte",
	["Combo points on your target's nameplate, red when full, energy ticks on the power bar, a poison reminder for each weapon, Flash Powder and Blinding Powder counters with a Flash Powder restock, your escapes and Kick on empty action slots, and your openers on the stealth page. The class bar shows your buffs, key cooldowns and reagents"] = "Kombopunkte auf der Namensplakette Eures Ziels, rot, wenn voll, Energieticks auf der Ressourcenleiste, eine Gifterinnerung für jede Waffe, Zähler für Blitzstrahlpulver und Blendungspulver mit Nachkauf für Blitzstrahlpulver, Eure Fluchtfähigkeiten und Tritt auf leeren Aktionsplätzen und Eure Eröffner auf der Verstohlenheitsseite. Die Klassenleiste zeigt Eure Stärkungszauber, wichtigen Abklingzeiten und Reagenzien",
	["Combo points, energy ticks, poison reminders and openers"] = "Kombopunkte, Energieticks, Gifterinnerungen und Eröffner",
	["Comes with the profile: %d bindings for your class"] = { one = "Kommt mit dem Profil: %d Belegung für Eure Klasse", other = "Kommt mit dem Profil: %d Belegungen für Eure Klasse" },
	["Community settings"] = "Community-Einstellungen",
	["Compact HUD"] = "Compact HUD",
	["Compact HUD (1440p)"] = "Compact HUD (1440p)",
	["Compact center built around the cooldowns: unit frames level with the essential row, buff bars above the target."] = "Kompakte Mitte rund um die Abklingzeiten: Einheitenrahmen auf Höhe der Reihe für essenzielle Abklingzeiten, Stärkungsleisten über dem Ziel.",
	["Compact center: player and target close beside the resource bar, four slim bar rows under the character, party left of center."] = "Kompakte Mitte: Spieler und Ziel dicht neben der Ressourcenleiste, vier schmale Leistenreihen unter dem Charakter, Gruppe links der Mitte.",
