	["Dark"] = "Dunkel",
	["Dark and minimal: all cooldowns in the center, wide-set unit frames at swing timer height, a low bar block along the bottom."] = "Dunkel und minimal: alle Abklingzeiten in der Mitte, weit auseinanderstehende Einheitenrahmen auf Höhe des Schlagtimers, ein niedriger Leistenblock am unteren Rand.",
	["Dark and minimal: two bar rows, swing timers right under the character, unit frames beside the cooldowns."] = "Dunkel und minimal: zwei Leistenreihen, Schlagtimer direkt unter dem Charakter, Einheitenrahmen neben den Abklingzeiten.",
	["Dark oak panels in a leather binding with paper trims and stitched seams, leather book corners and medallion portraits. Brings the Bronze accent while yours is the default blue."] = "Dunkle Eichenpanels in Ledereinband mit Papierkanten und Ziernähten, Buchecken aus Leder und Medaillonporträts. Bringt den Akzent Bronze mit, solange Eurer das Standardblau ist.",
	["Dark oak panels in a leather binding with paper trims."] = "Dunkle Eichenpanels in Ledereinband mit Papierkanten.",
