	["Di"] = "Kr",
	["Digits after the point in shortened numbers (1.2k with 1, 1.23k with 2)."] = "Nachkommastellen in gekürzten Zahlen (1.2k mit 1, 1.23k mit 2).",
	["Dim after"] = "Abdunkeln nach",
