	["Discard"] = "Verwerfen",
	["Disease"] = "Krankheit",
	["Dispel Magic works on enemies too: healers have it on the Interrupt button."] = "Magiebannung wirkt auch auf Gegner: Heiler haben sie auf der Taste Unterbrechen.",
	["Dispel Magic works on enemies too: it is on the Cleanse button."] = "Magiebannung wirkt auch auf Gegner: Sie liegt auf der Taste „Reinigung“.",
	["Dispel magic"] = "Magiebannung",
	["Dispel types"] = "Banntypen",
	["Dispellable by you"] = "Von Euch bannbar",
	["Display"] = "Anzeige",
	["Distance between the grid lines in move mode. Frames snap to the grid when Snap is on."] = "Abstand zwischen den Rasterlinien im Verschiebemodus. Rahmen rasten am Raster ein, wenn Einrasten an ist.",
	["Distance from the anchor to the right (negative: to the left)."] = "Abstand vom Ankerpunkt nach rechts (negativ: nach links).",
	["Distance from the anchor upwards (negative: down)."] = "Abstand vom Ankerpunkt nach oben (negativ: nach unten).",
	["Divider line"] = "Trennlinie",
	["Don't ask again on this character"] = "Bei diesem Charakter nicht mehr fragen",
	["Don't care"] = "Egal",
	["Don't remind me"] = "Nicht erinnern",
	["Don't touch"] = "Nicht anfassen",
	["Done"] = "Fertig",
	["Drag"] = "Ziehen",
	["Drag Blizzard's windows where you want them and scale them with the mouse wheel. Uncheck a window to leave it to Blizzard."] = "Zieht Blizzards Fenster dorthin, wo Ihr sie haben wollt, und skaliert sie mit dem Mausrad. Wählt ein Fenster ab, um es Blizzard zu überlassen.",
	["Drag EldoUI's frames where you want them. Right-click a frame for its exact position."] = "Zieht die Rahmen von EldoUI dorthin, wo Ihr sie haben wollt. Ein Rechtsklick auf einen Rahmen zeigt seine genaue Position.",
	["Drag and let go to preview. 0.40 to 1.20."] = "Ziehen und loslassen für eine Vorschau. 0.40 bis 1.20.",
	["Drag any frame to a new place (/eui move)."] = "Zieht jeden Rahmen an einen neuen Platz (/eui move).",
	["Drag any frame to move it. Right-click a frame for its options. Done or Escape keeps your changes and leaves."] = "Zieht einen Rahmen, um ihn zu verschieben. Ein Rechtsklick auf einen Rahmen öffnet seine Optionen. Fertig oder Esc behält Eure Änderungen und beendet den Modus.",
	["Drag by"] = "Ziehen an",
	["Drag frames to move them. Ctrl+Z takes back the last change, Undo changes puts everything back."] = "Zieht Rahmen, um sie zu verschieben. Strg+Z nimmt die letzte Änderung zurück, „Änderungen rückgängig“ stellt alles wieder her.",
	["Drag to change the window's size."] = "Ziehen, um die Fenstergröße zu ändern.",
	["Drag to make the window bigger or smaller; the content follows. Ctrl+mouse wheel on the title bar zooms."] = "Ziehen macht das Fenster größer oder kleiner; der Inhalt passt sich an. Strg+Mausrad auf der Titelleiste zoomt.",
	["Drag to make this window wider, narrower, taller or shorter. Saved for your account; Reset size next to the scale puts it back."] = "Ziehen macht dieses Fenster breiter, schmaler, höher oder niedriger. Für Euren Account gespeichert; Größe zurücksetzen neben der Skalierung stellt sie wieder her.",
	["Drag to move (EldoUI)"] = "Ziehen zum Verschieben (EldoUI)",
	["Drag to move the window."] = "Ziehen, um das Fenster zu verschieben.",
	["Drag to move the window. Ctrl+mouse wheel zooms it."] = "Ziehen, um das Fenster zu verschieben. Strg+Mausrad zoomt es.",
	["Dragged frames snap to the grid, to the edges and centers of other frames and to the screen center. Hold Alt while dragging to place a frame freely."] = "Gezogene Rahmen rasten am Raster, an Kanten und Mitten anderer Rahmen und an der Bildschirmmitte ein. Haltet beim Ziehen Alt gedrückt, um einen Rahmen frei zu platzieren.",
	["Draws what your skin brings: every skin names its own graphics."] = "Zeichnet, was Euer Skin mitbringt: Jeder Skin benennt seine eigenen Grafiken.",
	["Dressing room"] = "Anprobe",
	["Druids have no interrupt: Prowl takes this key in Cat Form."] = "Druiden haben keine Unterbrechung: Schleichen liegt in Katzengestalt auf dieser Taste.",
	["Druids have no interrupt: healers get Remove Curse on this key."] = "Druiden haben keine Unterbrechung: Heiler bekommen Fluch aufheben auf diese Taste.",
	["Druids have no interrupt: the bear's taunt takes this key."] = "Druiden haben keine Unterbrechung: Der Spott des Bären liegt auf dieser Taste.",
	["Druids have no interrupt; Bash in Bear Form is a stun."] = "Druiden haben keine Unterbrechung; Hieb in Bärengestalt ist eine Betäubung.",
	["Druids have no offensive dispel."] = "Druiden haben keine offensive Bannung.",
	["Dungeon bosses in the Journal learn their drops from group and solo loot."] = "Dungeonbosse im Tagebuch lernen ihre Beute aus Gruppen- und Solobeute.",
	["Durability figure (armor man)"] = "Haltbarkeitsfigur (Rüstungsmännchen)",
	["E D move, S F strafe. Bar 1: R T G W 2 Q A V C X Z 4."] = "E D laufen, S F seitwärts. Leiste 1: R T G W 2 Q A V C X Z 4.",
	["E and D move forward and back, S and F strafe, and you turn with the mouse. W, A and Q become spell keys; 1, 3, 5 and 6 stay free for your own bars."] = "E und D laufen vor und zurück, S und F seitwärts, gedreht wird mit der Maus. W, A und Q werden Zaubertasten; 1, 3, 5 und 6 bleiben frei für Eure eigenen Leisten.",
	["Each bar has its own keys now. The key preview on the Keybinds page in /eui shows every one, and Undo last key set there puts your old keys back."] = "Jede Leiste hat jetzt eigene Tasten. Die Tastenvorschau auf der Seite „Tastenbelegungen“ in /eui zeigt jede einzelne, und „Letzten Tastensatz rückgängig“ stellt dort Eure alten Tasten wieder her.",
	["Each chat window keeps its own font size."] = "Jedes Chatfenster behält seine eigene Schriftgröße.",
	["Each key set binds bars 1 to 3 and three Consumable Bar keys. Other bars keep their keys. A preview shows every key first."] = "Jeder Tastensatz belegt die Leisten 1 bis 3 und drei Tasten der Verbrauchsgüterleiste. Andere Leisten behalten ihre Tasten. Eine Vorschau zeigt zuerst jede Taste.",
	["Each module's own font setting. Theme font or Default means the module follows the theme font."] = "Die eigene Schrifteinstellung jedes Moduls. Themenschrift oder Standard bedeutet, dass das Modul der Themenschrift folgt.",
	["Each part of Blizzard's own UI has one switch. Off leaves it as Blizzard made it. Skin, Move, Hide, Replace and Improve say what EldoUI may do with it."] = "Jeder Teil von Blizzards eigener Oberfläche hat einen Schalter. Aus lässt ihn, wie Blizzard ihn gemacht hat. Skin, Verschieben, Ausblenden, Ersetzen und Verbessern sagen, was EldoUI damit tun darf.",
	["Each spell goes on the button of its keybind category on bars 1 to 3, the same key on every class. Only empty buttons get a spell; a button with your own action is kept."] = "Jeder Zauber kommt auf die Aktionstaste seiner Tastenkategorie auf den Leisten 1 bis 3, bei jeder Klasse dieselbe Taste. Nur leere Aktionstasten erhalten einen Zauber; eine Aktionstaste mit Eurer eigenen Aktion bleibt erhalten.",
	["Each stat is worth what your scale says; the score is their sum."] = "Jeder Wert ist so viel wert, wie Eure Gewichtung sagt; die Wertung ist ihre Summe.",
	["Each switch works on its own and can be turned off any time in %s > General > Accessibility, which puts back what you had. That page also has sound cues, the text size and the kind of color blindness."] = "Jeder Schalter wirkt für sich und lässt sich jederzeit unter %s > Allgemein > Barrierefreiheit ausschalten, was Euren vorherigen Zustand wiederherstellt. Diese Seite bietet auch Tonsignale, die Textgröße und die Art der Farbenblindheit.",
	["Each tint on a sample panel in your skin. Click one to use it."] = "Jeder Farbton auf einem Musterpanel in Eurem Skin. Klickt einen an, um ihn zu verwenden.",
	["Each window keeps the look set on the Blizzard UI page."] = "Jedes Fenster behält die Optik, die auf der Seite Blizzard-UI eingestellt ist.",
	["Easy to read"] = "Gut lesbar",
	["Edit Mode already has %d account layouts, the most it allows; delete one in Edit Mode first"] = "Der Bearbeitungsmodus hat bereits %d Account-Layouts, mehr sind nicht erlaubt; löscht zuerst eins im Bearbeitungsmodus",
	["Edit Mode already has a layout named %q"] = "Der Bearbeitungsmodus hat bereits ein Layout namens %q",
	["Edit Mode couldn't write the layout"] = "Der Bearbeitungsmodus konnte das Layout nicht schreiben",
	["Edit Mode doesn't accept this layout text"] = "Der Bearbeitungsmodus akzeptiert diesen Layouttext nicht",
	["Edit Mode goes back to your layout when the fight ends."] = "Der Bearbeitungsmodus kehrt nach dem Kampf zu Eurem Layout zurück.",
	["Edit Mode integration"] = "Einbindung des Bearbeitungsmodus",
	["Edit Mode is open; close it first"] = "Der Bearbeitungsmodus ist offen; schließt ihn zuerst",
	["Edit Mode is switched off on this realm"] = "Der Bearbeitungsmodus ist auf diesem Realm abgeschaltet",
	["Edit Mode layout not added: %s."] = "Layout des Bearbeitungsmodus nicht hinzugefügt: %s.",
	["Edit Mode layout: %s"] = "Layout des Bearbeitungsmodus: %s",
	["Edit Mode layouts aren't loaded yet"] = "Layouts des Bearbeitungsmodus sind noch nicht geladen",
	["Edit Mode refused the layout"] = "Der Bearbeitungsmodus hat das Layout abgelehnt",
	["Edit group"] = "Gruppe bearbeiten",
	["Edit list"] = "Liste bearbeiten",
	["Edit settings anyway"] = "Einstellungen trotzdem bearbeiten",
	["Effects preset"] = "Effektvorlage",
	["Eight skins for the whole UI and the Appearance page, with skins for Blizzard's own windows."] = "Acht Skins für die gesamte Oberfläche und die Seite Aussehen, mit Skins für Blizzards eigene Fenster.",
	["Either way, a style that doesn't fit this layout changes. %s"] = "So oder so ändert sich ein Stil, der nicht zu diesem Layout passt. %s",
	["Eldo-Classic (1440p)"] = "Eldo-Classic (1440p)",
	["Eldo-Clean (1440p)"] = "Eldo-Clean (1440p)",
	["Eldo-Compact (1440p)"] = "Eldo-Compact (1440p)",
	["Eldo-Cookies (1440p)"] = "Eldo-Cookies (1440p)",
	["Eldo-Dark (1440p)"] = "Eldo-Dark (1440p)",
	["Eldo-Joe (1440p)"] = "Eldo-Joe (1440p)",
	["Eldo-Syntax (1440p)"] = "Eldo-Syntax (1440p)",
	["Eldo-Vanilla Compact (1440p)"] = "Eldo-Vanilla Compact (1440p)",
	["Eldo-Vanilla Focus (1440p)"] = "Eldo-Vanilla Focus (1440p)",
	["Eldo-Violet (1440p)"] = "Eldo-Violet (1440p)",
	["Eldo-Zerby (1440p)"] = "Eldo-Zerby (1440p)",
	["EldoUI"] = "EldoUI",
	["EldoUI Center"] = "EldoUI Center",
	["EldoUI Center (1440p)"] = "EldoUI Center (1440p)",
	["EldoUI Consumable Bar"] = "EldoUI-Verbrauchsgüterleiste",
	["EldoUI also builds on open-source work; its credits are in the file THIRD_PARTY_NOTICES.md in the EldoUI folder."] = "EldoUI baut außerdem auf Open-Source-Arbeit auf; die Danksagungen stehen in der Datei THIRD_PARTY_NOTICES.md im EldoUI-Ordner.",
	["EldoUI can't tell your role from the game. Pick the one you play most."] = "EldoUI kann Eure Rolle nicht aus dem Spiel ablesen. Wählt die, die Ihr am meisten spielt.",
	["EldoUI changes %d of %d Blizzard frames"] = "EldoUI ändert %d von %d Blizzard-Rahmen",
	["EldoUI changes no Blizzard element. Blizzard's frames stay as Blizzard made them, and EldoUI's own frames for the same parts step aside, so nothing shows twice. Hidden Blizzard frames come back after the reload."] = "EldoUI ändert kein Blizzard-Element. Blizzards Rahmen bleiben, wie Blizzard sie gemacht hat, und die eigenen Rahmen von EldoUI für dieselben Teile treten zurück, damit nichts doppelt erscheint. Ausgeblendete Blizzard-Rahmen kehren nach dem Neuladen zurück.",
	["EldoUI changes what its modules are made for: its own frames replace Blizzard's, the windows it skins get the EldoUI look, and every Blizzard window can be dragged and scaled. Other switches you set stay."] = "EldoUI ändert, wofür seine Module gemacht sind: Seine eigenen Rahmen ersetzen die von Blizzard, die Fenster, denen es einen Skin gibt, erhalten die EldoUI-Optik, und jedes Blizzard-Fenster lässt sich ziehen und skalieren. Andere Schalter, die Ihr gesetzt habt, bleiben.",
	["EldoUI chat tabs"] = "EldoUI-Chatreiter",
	["EldoUI commands"] = "EldoUI-Befehle",
	["EldoUI could not load these settings. Check that you are using the latest version of EldoUI."] = "EldoUI konnte diese Einstellungen nicht laden. Prüft, ob Ihr die neueste Version von EldoUI verwendet.",
	["EldoUI diagnostics"] = "EldoUI-Diagnose",
	["EldoUI does the jobs of %s now (some after a reload)."] = "EldoUI übernimmt jetzt die Aufgaben von %s (manche nach einem Neuladen).",
	["EldoUI doesn't recognize this string. It reads EldoUI (!EUI1!), EllesmereUI (!EUI_), ElvUI (!E1!, !E2!) and Blizzard Edit Mode layout strings."] = "EldoUI erkennt diesen String nicht. Es liest Strings von EldoUI (!EUI1!), EllesmereUI (!EUI_), ElvUI (!E1!, !E2!) und Layouts des Blizzard-Bearbeitungsmodus.",
	["EldoUI error log"] = "EldoUI-Fehlerprotokoll",
	["EldoUI font in Blizzard's parts"] = "EldoUI-Schrift in Blizzards Teilen",
	["EldoUI found addons that do the same job as parts of EldoUI. Pick which one you want for each. You can change this later on the Other addons page."] = "EldoUI hat Addons gefunden, die dieselbe Aufgabe wie Teile von EldoUI übernehmen. Wählt für jede, was Ihr wollt. Ihr könnt das später auf der Seite Andere Addons ändern.",
	["EldoUI handles this now."] = "EldoUI übernimmt das jetzt.",
	["EldoUI has a newer profile for %s. Update now? Changes you made inside that profile are replaced; your other profiles stay as they are."] = "EldoUI hat ein neueres Profil für %s. Jetzt aktualisieren? Änderungen, die Ihr in diesem Profil gemacht habt, werden ersetzt; Eure anderen Profile bleiben, wie sie sind.",
	["EldoUI has something new for the setup: %s. Your setup stays as it is unless you pick one."] = "EldoUI hat etwas Neues für die Einrichtung: %s. Eure Einrichtung bleibt, wie sie ist, außer Ihr wählt etwas davon.",
	["EldoUI import"] = "EldoUI-Import",
	["EldoUI is set up"] = "EldoUI ist eingerichtet",
	["EldoUI is set up. Reload the UI now to finish?"] = "EldoUI ist eingerichtet. Interface jetzt neu laden, um abzuschließen?",
	["EldoUI keeps Blizzard's quest and gossip frames; auto accept is a separate option."] = "EldoUI behält Blizzards Quest- und Gesprächsfenster; automatisches Annehmen ist eine eigene Option.",
	["EldoUI keeps its own UI scale (%s), so the game's UI scale setting has no effect. Change it with %s or in /eui > General."] = "EldoUI behält seine eigene UI-Skalierung (%s), daher hat die UI-Skalierung des Spiels keine Wirkung. Ändert sie mit %s oder unter /eui > Allgemein.",
	["EldoUI keeps its settings in profiles. \"The EldoUI profile\" starts a new one from EldoUI's defaults and leaves your current profile untouched, so you can switch back in /eui > Profiles. \"My current profile\" sets up the profile you use now.\n\nWhen another character already set up the EldoUI profile, \"Use the EldoUI profile as it is\" puts this character on it and changes nothing in it: the layout, scale, role and Blizzard UI steps start on keep, and only this character's chat tabs, addon profiles and click-casting are suggested. Starting it fresh asks twice and names the characters that use it.\n\nA preset pack is a whole UI: a layout, a skin, a style for each part of the UI, a role and the Blizzard UI and chat setup. Apply sets up every step with it; Customize goes through the steps with its picks filled in.\n\nEldoUI's chat and action bars show from your first login. For every other part, until the Blizzard UI step lets EldoUI replace a Blizzard frame, EldoUI's version of it steps aside, so nothing shows twice.\n\nBefore the first change EldoUI keeps a backup of the profile it writes into. \"Undo the last setup\" (or /eui install undo) puts it back, and \"Back up my setup\" keeps a named copy in your profiles."] = "EldoUI speichert seine Einstellungen in Profilen. \"Das EldoUI-Profil\" beginnt ein neues aus den Standardwerten von EldoUI und lässt Euer aktuelles Profil unberührt, sodass Ihr unter /eui > Profile zurückwechseln könnt. \"Mein aktuelles Profil\" richtet das Profil ein, das Ihr gerade verwendet.\n\nWenn ein anderer Charakter das EldoUI-Profil schon eingerichtet hat, ordnet \"EldoUI-Profil so verwenden, wie es ist\" diesen Charakter ihm zu und ändert nichts darin: Die Schritte Layout, Skalierung, Rolle und Blizzard-UI beginnen auf Behalten, und vorgeschlagen werden nur Chatreiter, Addon-Profile und Klickzauber dieses Charakters. Wollt Ihr es neu beginnen, wird zweimal nachgefragt, und die Charaktere, die es verwenden, werden genannt.\n\nEin Vorlagenpaket ist eine ganze Oberfläche: ein Layout, ein Skin, ein Stil für jeden Teil der Oberfläche, eine Rolle sowie die Einrichtung von Blizzard-UI und Chat. Übernehmen richtet jeden Schritt damit ein; Anpassen geht die Schritte mit seiner vorausgefüllten Auswahl durch.\n\nChat und Aktionsleisten von EldoUI erscheinen ab dem ersten Einloggen. Bei allen anderen Teilen tritt die Version von EldoUI zurück, bis der Schritt Blizzard-UI EldoUI erlaubt, einen Blizzard-Rahmen zu ersetzen, damit nichts doppelt erscheint.\n\nVor der ersten Änderung legt EldoUI eine Sicherung des Profils an, in das es schreibt. \"Letzte Einrichtung rückgängig machen\" (oder /eui install undo) stellt sie wieder her, und \"Meine Einrichtung sichern\" legt eine benannte Kopie in Euren Profilen ab.",
	["EldoUI keeps one click per skill, so there is no own trainer window with a train-all button."] = "EldoUI behält einen Klick pro Fertigkeit, daher gibt es kein eigenes Lehrerfenster mit einer Taste Alle lernen.",
	["EldoUI language"] = "EldoUI-Sprache",
	["EldoUI may change none of Blizzard's windows yet; the Blizzard UI page lets it."] = "EldoUI darf noch keines von Blizzards Fenstern ändern; die Seite Blizzard-UI erlaubt es.",
	["EldoUI never runs two addons on the same frames. When you give EldoUI a job another addon does, that addon is turned off for this character at Finish, after one reload; Finish names every one. A part both can run on turns nothing off: EldoUI's part runs next to the other addon. Settings > Other addons or /eui addons changes it later."] = "EldoUI lässt nie zwei Addons auf denselben Rahmen laufen. Gebt Ihr EldoUI eine Aufgabe, die ein anderes Addon übernimmt, wird dieses Addon beim Abschließen nach einem Neuladen für diesen Charakter ausgeschaltet; der Abschluss nennt jedes davon. Ein Teil, den beide betreiben können, schaltet nichts aus: Der Teil von EldoUI läuft neben dem anderen Addon. Einstellungen > Andere Addons oder /eui addons ändert das später.",
	["EldoUI never writes a key. Class spells on empty buttons, the preview and hover binding still work."] = "EldoUI belegt nie eine Taste. Klassenzauber auf leeren Aktionstasten, die Vorschau und das Belegen per Mauszeiger funktionieren weiterhin.",
	["EldoUI only"] = "Nur EldoUI",
	["EldoUI only hides the Blizzard frames its own frames replace and changes no other Blizzard window. Switches you set before stay."] = "EldoUI blendet nur die Blizzard-Rahmen aus, die seine eigenen Rahmen ersetzen, und ändert kein anderes Blizzard-Fenster. Schalter, die Ihr vorher gesetzt habt, bleiben.",
	["EldoUI places its frames for controller play while the game's gamepad interface is on. Your normal layout and dragged frames stay saved and come back when you turn the gamepad interface off."] = "EldoUI platziert seine Rahmen für das Spielen mit Controller, solange die Gamepad-Oberfläche des Spiels an ist. Euer normales Layout und gezogene Rahmen bleiben gespeichert und kehren zurück, wenn Ihr die Gamepad-Oberfläche ausschaltet.",
	["EldoUI profiles for other addons you use, imported with each addon's own import function."] = "EldoUI-Profile für andere Addons, die Ihr verwendet, importiert mit der eigenen Importfunktion jedes Addons.",
	["EldoUI rebuilds it as a WoW: Forever layout. Apply as a new layout: a NEW profile uses it and your current profile stays as it is. Change my current layout: your current profile takes it. Both can be undone."] = "EldoUI baut es als Layout für WoW: Forever nach. Als neues Layout anwenden: Ein NEUES Profil verwendet es, und Euer aktuelles Profil bleibt, wie es ist. Mein aktuelles Layout ändern: Euer aktuelles Profil übernimmt es. Beides lässt sich rückgängig machen.",
	["EldoUI safe area: %d wide"] = "EldoUI-Sicherheitsbereich: %d breit",
	["EldoUI set aside %d saved values it could not read. Nothing was deleted: type /eui data to see them."] = { one = "EldoUI hat %d gespeicherten Wert beiseitegelegt, den es nicht lesen konnte. Nichts wurde gelöscht: Gebt /eui data ein, um ihn zu sehen.", other = "EldoUI hat %d gespeicherte Werte beiseitegelegt, die es nicht lesen konnte. Nichts wurde gelöscht: Gebt /eui data ein, um sie zu sehen." },
	["EldoUI setup"] = "EldoUI-Einrichtung",
	["EldoUI setup is not finished. Type %s to get started."] = "Die EldoUI-Einrichtung ist nicht abgeschlossen. Gebt %s ein, um loszulegen.",
	["EldoUI setup is paused. Type %s to continue where you left off."] = "Die EldoUI-Einrichtung ist pausiert. Gebt %s ein, um dort weiterzumachen, wo Ihr aufgehört habt.",
	["EldoUI share string."] = "EldoUI-Teilen-String.",
	["EldoUI skins Blizzard's cooldown tracking instead of rebuilding it."] = "EldoUI gibt Blizzards Abklingzeitverfolgung einen Skin, statt sie nachzubauen.",
	["EldoUI stands back"] = "EldoUI hält sich zurück",
	["EldoUI stands back so the two never draw the same thing twice. Choose who handles each job."] = "EldoUI hält sich zurück, damit die beiden nie dasselbe doppelt zeichnen. Wählt, wer welche Aufgabe übernimmt.",
	["EldoUI stands back so they never draw the same thing twice. Choose who handles each job."] = "EldoUI hält sich zurück, damit sie nie dasselbe doppelt zeichnen. Wählt, wer welche Aufgabe übernimmt.",
	["EldoUI string (asks once more before it changes anything)."] = "EldoUI-String (fragt noch einmal nach, bevor er etwas ändert).",
	["EldoUI string:"] = "EldoUI-String:",
	["EldoUI switched to your profile %s because one of your profile rules asked for it. The rules pick a profile by talent group, or by solo, party, raid and battleground; Profile rules in /eui changes them."] = "EldoUI ist zu Eurem Profil %s gewechselt, weil eine Eurer Profilregeln das verlangt hat. Die Regeln wählen ein Profil nach Talentgruppe oder nach Solo, Gruppe, Schlachtzug und Schlachtfeld; Profilregeln in /eui ändert sie.",
	["EldoUI switches to %s after a reload."] = "EldoUI wechselt nach einem Neuladen zu %s.",
	["EldoUI then never writes a key. The preview, the game keys and keybind mode still work."] = "EldoUI belegt dann nie eine Taste. Die Vorschau, die Spieltasten und der Tastenbelegungsmodus funktionieren weiterhin.",
	["EldoUI version and memory"] = "EldoUI-Version und Speicher",
	["EldoUI was updated"] = "EldoUI wurde aktualisiert",
	["EldoUI writes its profile into %s and switches each to it. Your other profiles in those addons stay as they are."] = "EldoUI schreibt sein Profil in %s und stellt jedes davon darauf um. Eure anderen Profile in diesen Addons bleiben, wie sie sind.",
	["EldoUI's %s runs next to %s from now on. %s stays on."] = "%s von EldoUI läuft ab jetzt neben %s. %s bleibt an.",
	["EldoUI's %s; %s is turned off at Finish"] = "%s von EldoUI; %s wird beim Abschließen ausgeschaltet",
	["EldoUI's boxes ignore right-click, so nothing is hidden by accident. Unit and group frames always keep the game's own right-click menu."] = "Die Felder von EldoUI ignorieren Rechtsklicks, damit nichts versehentlich ausgeblendet wird. Einheiten- und Gruppenrahmen behalten immer das Rechtsklickmenü des Spiels.",
	["EldoUI's boxes ignore right-click, so nothing is hidden by accident. Unit and group frames always keep the game's own right-click menu. Boxes here in move mode keep their menu."] = "Die Felder von EldoUI ignorieren Rechtsklicks, damit nichts versehentlich ausgeblendet wird. Einheiten- und Gruppenrahmen behalten immer das Rechtsklickmenü des Spiels. Felder hier im Verschiebemodus behalten ihr Menü.",
	["EldoUI's flat frames: nothing drawn round them."] = "Die flachen Rahmen von EldoUI: Nichts wird um sie herum gezeichnet.",
	["EldoUI's look: fonts, 1 px borders, flat textures and the accent color."] = "Die Optik von EldoUI: Schriftarten, 1-px-Ränder, flache Texturen und die Akzentfarbe.",
	["EldoUI's normal look, sounds and motion. Safe colors follow the game's color-blind mode."] = "EldoUIs normale Optik, Töne und Bewegung. Sichere Farben folgen dem Farbenblindmodus des Spiels.",
	["EldoUI's own default: one calm center. Player and target sit level with the cooldown row, the resource and cast bars stay in the column between them, and the action bars form one block at the bottom with a narrow wing on each side."] = "Der eigene Standard von EldoUI: eine ruhige Mitte. Spieler und Ziel sitzen auf Höhe der Abklingzeitenreihe, Ressourcen- und Zauberleiste bleiben in der Spalte dazwischen, und die Aktionsleisten bilden unten einen Block mit einem schmalen Flügel auf jeder Seite.",
	["EldoUI's own frame has this spot"] = "Ein eigener Rahmen von EldoUI belegt diese Stelle",
	["EldoUI's own look for every part"] = "Die eigene Optik von EldoUI für jeden Teil",
	["EldoUI's own look: the layout picked for your screen, clean unit frames and the layout's own skin."] = "Die eigene Optik von EldoUI: das für Euren Bildschirm gewählte Layout, klare Einheitenrahmen und der eigene Skin des Layouts.",
	["EldoUI's own texts are now available in Danish, under General > EldoUI language."] = "Die eigenen Texte von EldoUI gibt es jetzt auf Dänisch, unter Allgemein > EldoUI-Sprache.",
	["EldoUI's part runs next to %s. Nothing is turned off."] = "Der Teil von EldoUI läuft neben %s. Nichts wird ausgeschaltet.",
	["EldoUI's suggestions"] = "Vorschläge von EldoUI",
	["EldoUI's suggestions are checked below."] = "Die Vorschläge von EldoUI sind unten angehakt.",
	["Eldostar, EldoUI's own leveling guide, brings over 200 community guides for WoW: Forever in a window on your layout, with a waypoint to the next goal."] = "Eldostar, der eigene Levelguide von EldoUI, bringt über 200 Community-Guides für WoW: Forever in einem Fenster auf Eurem Layout, mit einem Wegpunkt zum nächsten Ziel.",
	["Elite, Rare, Rare Elite or Boss; empty for normal units."] = "Elite, Rar, Rar-Elite oder Boss; leer bei normalen Einheiten.",
	["EllesmereUI"] = "EllesmereUI",
	["EllesmereUI string version %s; only versions 3 and 4 can be read"] = "EllesmereUI-String-Version %s; nur die Versionen 3 und 4 können gelesen werden",
	["ElvUI"] = "ElvUI",
	["ElvUI only exports frames you moved; every other EldoUI frame keeps its current layout position."] = "ElvUI exportiert nur Rahmen, die Ihr verschoben habt; jeder andere EldoUI-Rahmen behält seine aktuelle Layoutposition.",
	["Emerg"] = "Notf",
	["Empty the built-in lists"] = "Eingebaute Listen leeren",
	["Empty the error log. It can't be undone."] = "Leert das Fehlerprotokoll. Das lässt sich nicht rückgängig machen.",
	["En"] = "Wu",
	["Enable"] = "Aktivieren",
	["Encounter Bar"] = "Begegnungsleiste",
	["Encounter Timeline keeps the next-event icon with its bar and separates nearby timer icons."] = "Die Begegnungszeitleiste hält das Symbol für das nächste Ereignis bei seiner Leiste und trennt nahe beieinanderliegende Timersymbole.",
	["Encounter timeline"] = "Begegnungszeitleiste",
	["Ends a color tag. [|r] works too."] = "Beendet einen Farb-Tag. [|r] funktioniert auch.",
	["Ends the tour. /eui tour shows it again."] = "Beendet die Tour. /eui tour zeigt sie erneut.",
	["Energy"] = "Energie",
	["Enter a six-digit color, such as 3FA9F5."] = "Gebt einen sechsstelligen Farbcode ein, etwa 3FA9F5.",
	["Enter combat"] = "Kampfbeginn",
	["Enter six hexadecimal digits for this color."] = "Gebt sechs Hexadezimalziffern für diese Farbe ein.",
	["Error log"] = "Fehlerprotokoll",
	["Error log cleared."] = "Fehlerprotokoll geleert.",
	["Errors"] = "Fehler",
	["Esc closes the window too."] = "Esc schließt das Fenster ebenfalls.",
	["Essential"] = "Essenziell",
	["Essential cooldowns"] = "Essenzielle Abklingzeiten",
	["Essential plus EldoUI's helpers: counters, rare alerts, extra tooltip lines and group panels. A new profile starts here."] = "Essenziell plus die Helfer von EldoUI: Zähler, Warnungen zu raren Gegnern, zusätzliche Tooltipzeilen und Gruppenpanels. Ein neues Profil beginnt hier.",
	["Evasion is on this button outside Stealth."] = "Entrinnen liegt außerhalb der Verstohlenheit auf dieser Taste.",
	["Every %s setting goes back to its default. The on/off state and frame positions are kept.%s"] = "Jede Einstellung von %s kehrt zu ihrem Standard zurück. Der An/Aus-Zustand und die Rahmenpositionen bleiben erhalten.%s",
	["Every Blizzard element (player frame, minimap, bags, the spellbook and so on) has its own switch. Off means Blizzard's own version, untouched. On, an element can allow up to four things: replace (EldoUI's frame instead of Blizzard's), skin (the EldoUI look), move (drag and scale it) and improve (small extras).\n\nRecommended turns on what EldoUI's modules are made for. You can change every element later on the Blizzard UI page; some changes come fully back only after a reload."] = "Jedes Blizzard-Element (Spielerrahmen, Minikarte, Taschen, das Zauberbuch usw.) hat einen eigenen Schalter. Aus bedeutet Blizzards eigene Version, unverändert. Bei An kann ein Element bis zu vier Dinge erlauben: Ersetzen (der Rahmen von EldoUI statt dem von Blizzard), Skin (die EldoUI-Optik), Verschieben (ziehen und skalieren) und Verbessern (kleine Extras).\n\nEmpfohlen schaltet ein, wofür die Module von EldoUI gemacht sind. Ihr könnt jedes Element später auf der Seite Blizzard-UI ändern; manche Änderungen sind erst nach einem Neuladen vollständig zurück.",
	["Every Blizzard element an EldoUI module can change gets the EldoUI look, extra info and EldoUI movers, plus the recommended replacements. Switches you set before stay."] = "Jedes Blizzard-Element, das ein EldoUI-Modul ändern kann, erhält die EldoUI-Optik, zusätzliche Infos und EldoUI-Verschiebefelder, dazu die empfohlenen Ersetzungen. Schalter, die Ihr vorher gesetzt habt, bleiben.",
	["Every EldoUI bar, text and tag that shows \"%s\" (%s) uses this color. The Game colors preset puts the game's color back."] = "Jede Leiste, jeder Text und jeder Tag von EldoUI, der \"%s\" (%s) zeigt, verwendet diese Farbe. Die Vorlage Spielfarben stellt die Farbe des Spiels wieder her.",
	["Every EldoUI box you hid, with a switch to show it again."] = "Jedes Feld von EldoUI, das Ihr ausgeblendet habt, mit einem Schalter, um es wieder anzuzeigen.",
	["Every EldoUI frame stays shown. Pixel shift and idle dim off."] = "Jeder EldoUI-Rahmen bleibt sichtbar. Pixelverschiebung und Abdunkeln bei Untätigkeit aus.",
	["Every EldoUI frame, bar and name drawn in the %s class color uses this."] = "Jeder EldoUI-Rahmen, jede Leiste und jeder Name, der in der Klassenfarbe von %s gezeichnet wird, verwendet diese.",
	["Every EldoUI setting lives there, with a search over all of them."] = "Dort liegt jede EldoUI-Einstellung, mit einer Suche über alle.",
	["Every EldoUI text at 130 %."] = "Jeder EldoUI-Text bei 130 %.",
	["Every EldoUI text at 130 %. The size can be changed later, from 100 to 160 %."] = "Jeder EldoUI-Text bei 130 %. Die Größe lässt sich später von 100 bis 160 % ändern.",
	["Every EldoUI text grows by the scale below."] = "Jeder EldoUI-Text wächst um die Skalierung unten.",
	["Every account-wide list in one string."] = "Jede accountweite Liste in einem String.",
	["Every character uses the same keys for the same job, so an alt plays the same way."] = "Jeder Charakter verwendet dieselben Tasten für dieselbe Aufgabe, so spielt sich ein Twink genauso.",
	["Every chat window back to the game's defaults, custom tabs closed, then EldoUI's tabs."] = "Jedes Chatfenster zurück auf die Standardwerte des Spiels, eigene Reiter geschlossen, dann die Reiter von EldoUI.",
	["Every chat window uses size %d."] = "Jedes Chatfenster verwendet Größe %d.",
	["Every color back to the game's own."] = "Jede Farbe zurück auf die des Spiels.",
	["Every element (player frame, minimap, bags, ...) has its own switch on the Blizzard UI page, where you can change each one later. Off always means Blizzard's own version. Some changes come fully back only after a reload, which Finish offers."] = "Jedes Element (Spielerrahmen, Minikarte, Taschen, ...) hat auf der Seite Blizzard-UI einen eigenen Schalter, wo Ihr jedes später ändern könnt. Aus bedeutet immer Blizzards eigene Version. Manche Änderungen sind erst nach einem Neuladen vollständig zurück, das der Abschluss anbietet.",
	["Every entry the filters show, as text to copy."] = "Jeder Eintrag, den die Filter zeigen, als Text zum Kopieren.",
	["Every few minutes every EldoUI frame moves by one or two pixels in a small loop, so still bars don't burn into an OLED screen. Only out of combat and not in move mode."] = "Alle paar Minuten bewegt sich jeder EldoUI-Rahmen in einer kleinen Schleife um ein oder zwei Pixel, damit sich stehende Leisten nicht in einen OLED-Bildschirm einbrennen. Nur außerhalb des Kampfes und nicht im Verschiebemodus.",
	["Every frame back to where the current layout puts it. It asks first, and locked frames stay where they are."] = "Jeder Rahmen zurück an den Platz, den das aktuelle Layout vorgibt. Fragt vorher, und gesperrte Rahmen bleiben, wo sie sind.",
	["Every frame shows in combat only. Hover a frame or hold the Show HUD key to see it."] = "Jeder Rahmen erscheint nur im Kampf. Fahrt mit der Maus über einen Rahmen oder haltet die Taste HUD anzeigen, um ihn zu sehen.",
	["Every frame shows in combat or with a target and stays faint otherwise."] = "Jeder Rahmen erscheint im Kampf oder mit Ziel und bleibt sonst blass.",
	["Every frame shows while you fight, have a target, move, cast or loot, and fades a few seconds after."] = "Jeder Rahmen erscheint, solange Ihr kämpft, ein Ziel habt, Euch bewegt, zaubert oder plündert, und blendet sich ein paar Sekunden danach aus.",
	["Every game shortcut a set takes gets the same new key in every set: the same key with Alt, the Character pane on the comma, Sheath on the period."] = "Jedes Tastenkürzel des Spiels, das ein Schema belegt, erhält in jedem Schema dieselbe neue Taste: dieselbe Taste mit Alt, das Charakterfenster auf dem Komma, Waffe wegstecken auf dem Punkt.",
	["Every helper that acts for you, from repairs to quest helpers. Each stays off until you turn it on."] = "Jeder Helfer, der für Euch handelt, von Reparaturen bis zu Questhelfern. Jeder bleibt aus, bis Ihr ihn einschaltet.",
	["Every helper that acts for you, in one place. Each switch is the same setting as on its module's own page."] = "Jeder Helfer, der für Euch handelt, an einem Ort. Jeder Schalter ist dieselbe Einstellung wie auf der eigenen Seite seines Moduls.",
	["Every helper that acts for you, one line each. Repairs, selling gray items and faster auto loot start checked on a first setup; uncheck any you don't want. The others stay off until you check them."] = "Jeder Helfer, der für Euch handelt, je eine Zeile. Reparaturen, Verkauf grauer Gegenstände und schnelleres automatisches Plündern sind bei einer ersten Einrichtung angehakt; entfernt den Haken bei allem, was Ihr nicht wollt. Die anderen bleiben aus, bis Ihr sie anhakt.",
	["Every layout or pack change can be undone, from the alert after the change or with /eui layout undo."] = "Jede Änderung von Layout oder Paket lässt sich rückgängig machen, über den Hinweis nach der Änderung oder mit /eui layout undo.",
	["Every logged error, warning and blocked action is removed."] = "Alle protokollierten Fehler, Warnungen und blockierten Aktionen werden entfernt.",
	["Every module stays as it is."] = "Jedes Modul bleibt, wie es ist.",
	["Every part above follows the skin again."] = "Jeder Teil oben folgt wieder dem Skin.",
	["Every part follows the skin."] = "Jeder Teil folgt dem Skin.",
	["Every part of EldoUI is a module. Switch off the ones you don't want."] = "Jeder Teil von EldoUI ist ein Modul. Schaltet die aus, die Ihr nicht wollt.",
	["Every part of EldoUI is a module. Switch off the ones you don't want; Blizzard's own version comes fully back after a reload."] = "Jeder Teil von EldoUI ist ein Modul. Schaltet die aus, die Ihr nicht wollt; Blizzards eigene Version kehrt nach einem Neuladen vollständig zurück.",
	["Every part of EldoUI is a module. Uncheck the ones you don't want; they switch at Finish."] = "Jeder Teil von EldoUI ist ein Modul. Entfernt den Haken bei denen, die Ihr nicht wollt; sie werden beim Abschließen umgeschaltet.",
	["Every pick on this page goes back to Keep."] = "Jede Auswahl auf dieser Seite kehrt zu Behalten zurück.",
	["Every saved part read as expected."] = "Jeder gespeicherte Teil wurde wie erwartet gelesen.",
	["Every setting of this profile back to its default (asks first)."] = "Jede Einstellung dieses Profils zurück auf den Standard (fragt vorher).",
	["Every setting you changed in this window since the last reload, with Undo for each one or all of them."] = "Jede Einstellung, die Ihr in diesem Fenster seit dem letzten Neuladen geändert habt, mit Rückgängig für jede einzelne oder alle.",
	["Every spell ID on the list. Edit and press Enter to replace the list in one go."] = "Jede Zauber-ID auf der Liste. Bearbeitet sie und drückt die Eingabetaste, um die Liste auf einmal zu ersetzen.",
	["Every spell on your action bars uses the highest rank you know."] = "Jeder Zauber auf Euren Aktionsleisten verwendet den höchsten Rang, den Ihr kennt.",
	["Every text tag with what it shows, and a place to try tag strings."] = "Jeder Text-Tag mit dem, was er zeigt, und ein Ort zum Ausprobieren von Tag-Strings.",
	["Every tour help shows again, once, the next time its place comes up."] = "Jede Tour-Hilfe erscheint noch einmal, einmalig, wenn ihre Stelle das nächste Mal kommt.",
	["Every tour help shows once more, the next time its place comes up. /eui tour lists them."] = "Jede Tour-Hilfe erscheint noch einmal, wenn ihre Stelle das nächste Mal kommt. /eui tour listet sie auf.",
	["Every window back to its normal size."] = "Jedes Fenster zurück auf seine normale Größe.",
	["Every window goes back to Blizzard's place."] = "Jedes Fenster kehrt an Blizzards Platz zurück.",
	["Every window goes back to where Blizzard places it, side panels attached."] = "Jedes Fenster kehrt dorthin zurück, wo Blizzard es platziert, Seitenpanels angeheftet.",
	["Every window is back to its normal size."] = "Jedes Fenster hat wieder seine normale Größe.",
	["Everyone in your group or guild gets the offer; each one decides."] = "Jeder in Eurer Gruppe oder Gilde erhält das Angebot; jeder entscheidet selbst.",
	["Everything"] = "Alles",
	["Everything (whole profile)"] = "Alles (ganzes Profil)",
	["Everything can be changed later in %s. Run this setup again any time with %s, or one step with %s (for example %s)."] = "Alles lässt sich später unter %s ändern. Startet diese Einrichtung jederzeit erneut mit %s oder einen einzelnen Schritt mit %s (zum Beispiel %s).",
	["Everything is selected. Press Ctrl+C and share it. Others paste it under Import."] = "Alles ist markiert. Drückt Strg+C und teilt es. Andere fügen es unter Importieren ein.",
	["Everything is selected. Press Ctrl+C."] = "Alles ist markiert. Drückt Strg+C.",
	["Everything is selected. Press Ctrl+C. Good for bug reports and comparing setups; /eui import reads it back too."] = "Alles ist markiert. Drückt Strg+C. Gut für Fehlerberichte und zum Vergleichen von Einrichtungen; /eui import liest es auch wieder ein.",
	["Everything is selected. Press Ctrl+C. Names, realm, guild and chat text are left out, and EldoUI sends nothing by itself."] = "Alles ist markiert. Drückt Strg+C. Namen, Realm, Gilde und Chattext werden ausgelassen, und EldoUI sendet nichts von selbst.",
	["Exact positions for every EldoUI frame, measured from the anchor point. Move mode (drag with snapping) changes the same values."] = "Genaue Positionen für jeden EldoUI-Rahmen, gemessen vom Ankerpunkt. Der Verschiebemodus (Ziehen mit Einrasten) ändert dieselben Werte.",
	["Exact positions for every movable frame."] = "Genaue Positionen für jeden verschiebbaren Rahmen.",
