	["Fewer settings"] = "Weniger Einstellungen",
	["File ID or path"] = "Datei-ID oder Pfad",
	["Fill every frame with sample content at once: unit, boss, party and raid frames, cast bars, cooldown rows, timers, loot and alert toasts and the rest, so the whole layout can be judged. Frames with no sample of their own show a stand-in until they have something real to show. Windows that open on demand keep only their box. Everything goes away when you leave move mode or combat starts."] = "Füllt alle Rahmen auf einmal mit Beispielinhalten: Einheiten-, Boss-, Gruppen- und Schlachtzugsrahmen, Zauberleisten, Abklingzeitreihen, Timer, Beute- und Alarmhinweise und den Rest, damit sich das ganze Layout beurteilen lässt. Rahmen ohne eigenes Beispiel zeigen einen Platzhalter, bis sie etwas Echtes anzuzeigen haben. Fenster, die sich bei Bedarf öffnen, behalten nur ihr Feld. Alles verschwindet, wenn Ihr den Verschiebemodus verlasst oder ein Kampf beginnt.",
	["Filter commands"] = "Befehle filtern",
	["Find a frame"] = "Rahmen finden",
	["Finish"] = "Abschließen",
	["Finish applies the steps marked \"Applies at Finish\", and Change goes back to a step or Revert undoes one. Afterwards this page lists every change, each with Revert this."] = "„Abschließen“ übernimmt die Schritte mit der Markierung „Wird beim Abschließen übernommen“, „Ändern“ führt zurück zu einem Schritt und „Zurücknehmen“ macht einen rückgängig. Danach listet diese Seite jede Änderung auf, jeweils mit „Dies zurücknehmen“.",
	["Finish your EldoUI setup"] = "EldoUI-Einrichtung abschließen",
	["First %s, last %s, %d times"] = { one = "Erstmals %s, zuletzt %s, %d-mal", other = "Erstmals %s, zuletzt %s, %d-mal" },
	["First name"] = "Vorname",
	["First name and surname"] = "Vor- und Nachname",
	["First name and surname, whatever the Name format says."] = "Vor- und Nachname, unabhängig vom Namensformat.",
	["First name only, whatever the Name format says."] = "Nur Vorname, unabhängig vom Namensformat.",
	["First name, surname or both for every character name EldoUI draws, and each place below set to \"Use general setting\". Your own surname shows only while the game's surname setting is on."] = "Vorname, Nachname oder beides für jeden Charakternamen, den EldoUI anzeigt, und für jede Stelle unten, die auf „Allgemeine Einstellung verwenden“ steht. Euer eigener Nachname erscheint nur, solange die Nachnamen-Einstellung des Spiels an ist.",
	["Fit layouts to the screen height"] = "Layouts an Bildschirmhöhe anpassen",
	["Fit tall windows on screen"] = "Hohe Fenster an Bildschirm anpassen",
	["Fix it"] = "Beheben",
	["Fixed pixel spot"] = "Feste Pixelposition",
	["Fixed tooltip position"] = "Feste Tooltip-Position",
	["Flag respawn"] = "Flaggen-Respawn",
	["Flash Powder"] = "Blitzpulver",
	["Flash time"] = "Blinkdauer",
	["Flat charcoal panels with one fine hairline and square corners, the quietest skin. Window titles use Inter."] = "Flache anthrazitfarbene Panels mit einer feinen Haarlinie und rechtwinkligen Ecken, der ruhigste Skin. Fenstertitel nutzen Inter.",
	["Flat charcoal panels with one fine hairline."] = "Flache anthrazitfarbene Panels mit einer feinen Haarlinie.",
	["Flat dark panels with a 1-pixel border and an accent line."] = "Flache dunkle Panels mit 1-Pixel-Rand und einer Akzentlinie.",
	["Flight Games is on by default and the Games box appears on your next flight path."] = "Die Flugspiele sind standardmäßig an, und das Spielefeld erscheint auf Eurer nächsten Flugroute.",
	["Flight map"] = "Flugkarte",
	["Flight map and taxi window"] = "Flugkarte und Flugmeisterfenster",
	["Floating combat text"] = "Schwebender Kampftext",
	["Focus"] = "Fokus",
	["Focus Frame"] = "Fokusrahmen",
	["Focus Target Frame"] = "Fokuszielrahmen",
	["Focus next tracked quest"] = "Nächste verfolgte Quest fokussieren",
	["Focus previous tracked quest"] = "Vorherige verfolgte Quest fokussieren",
	["Fold or unfold this section. It stays that way."] = "Diesen Abschnitt ein- oder ausklappen. Er bleibt so.",
	["Fold this group."] = "Diese Gruppe einklappen.",
	["Follow layout"] = "Layout folgen",
	["Follow skin"] = "Skin folgen",
	["Follow skin (now: %s)"] = "Skin folgen (jetzt: %s)",
	["Follow the game"] = "Wie im Spiel",
	["Following a new audio device"] = "Wechsel auf neues Audiogerät",
	["Follows %s"] = "Folgt %s",
	["Font"] = "Schriftart",
	["Font of the countdown numbers on action bars, bag slots, aura icons and every other cooldown swipe that uses EldoUI's cooldown text. Theme font follows the Font above."] = "Schriftart der Countdown-Zahlen auf Aktionsleisten, Taschenplätzen, Aurensymbolen und jeder anderen Abklingzeitanzeige, die EldoUIs Abklingzeittext nutzt. Die Theme-Schriftart folgt der Schriftart oben.",
	["Font of the game's floating damage and healing numbers. The game reads it when the world loads: log out and back in to see it."] = "Schriftart der schwebenden Schadens- und Heilungszahlen des Spiels. Das Spiel liest sie beim Laden der Welt: Meldet Euch ab und wieder an, um sie zu sehen.",
	["Font of the names above characters. The game reads it when the world loads: log out and back in to see it."] = "Schriftart der Namen über Charakteren. Das Spiel liest sie beim Laden der Welt: Meldet Euch ab und wieder an, um sie zu sehen.",
	["Font size"] = "Schriftgröße",
	["Fonts and text"] = "Schriften und Text",
	["For a mouse with 12 side buttons that send 1 to =. Bar 1: the side buttons, bar 2: Shift + the side buttons, bar 3: Q E R F T, Mouse 4, G Z X C V, Mouse 5. W and S move, A and D strafe."] = "Für eine Maus mit 12 Seitentasten, die 1 bis = senden. Leiste 1: die Seitentasten, Leiste 2: Umschalt + Seitentasten, Leiste 3: Q E R F T, Maustaste 4, G Z X C V, Maustaste 5. W und S zum Laufen, A und D zum Seitwärtsgehen.",
	["For your class: %s."] = "Für Eure Klasse: %s.",
	["Forced combat restrictions are %s (%s): the client acts as if you were in combat. %s switches it off; it stays on after a reload until you do."] = "Erzwungene Kampfbeschränkungen sind %s (%s): Der Client verhält sich, als wärt Ihr im Kampf. %s schaltet sie aus; bis dahin bleiben sie auch nach einem Neuladen an.",
	["Forced combat restrictions are off again (%s)."] = "Erzwungene Kampfbeschränkungen sind wieder aus (%s).",
	["Forged Metal"] = "Forged Metal",
	["Forgets your own keys for this key set and shows the preview, where Apply puts them back."] = "Vergisst Eure eigenen Tasten für diesen Tastensatz und zeigt die Vorschau, in der „Übernehmen“ sie zurückholt.",
	["Fortitude, Inner Fire and Divine Spirit reminders you click to cast, the five-second rule on your mana bar, a candle counter and restock, and Power Word: Shield, Fade and spells for your role on empty action slots. The class bar shows your buffs, key cooldowns and reagents"] = "Erinnerungen an Seelenstärke, Inneres Feuer und Göttlichen Willen, die Ihr per Klick wirkt, die Fünf-Sekunden-Regel auf Eurer Manaleiste, ein Kerzenzähler mit Nachkauf sowie Machtwort: Schild, Verblassen und Zauber für Eure Rolle auf leeren Aktionsplätzen. Die Klassenleiste zeigt Eure Stärkungszauber, wichtigen Abklingzeiten und Reagenzien",
	["Four roles in the setup and on the Role page: Melee, Ranged, Healer and Tank."] = "Vier Rollen in der Einrichtung und auf der Seite „Rolle“: Nahkampf, Distanz, Heiler und Tank.",
	["Frame across (percent of the screen)"] = "Rahmen waagerecht (Prozent des Bildschirms)",
	["Frame anchor"] = "Rahmenanker",
	["Frame edge, bottom"] = "Rahmenkante, unten",
	["Frame edge, top"] = "Rahmenkante, oben",
	["Frame positions"] = "Rahmenpositionen",
	["Frame shadows"] = "Rahmenschatten",
	["Frame shadows belong to the flat skins, Modern and Minimal Modern. Other skins draw a frame of their own."] = "Rahmenschatten gehören zu den flachen Skins Modern und Minimal Modern. Andere Skins zeichnen einen eigenen Rahmen.",
	["Frame up and down (percent of the screen)"] = "Rahmen senkrecht (Prozent des Bildschirms)",
	["Frames"] = "Rahmen",
	["Frames can't be moved in combat."] = "Rahmen lassen sich im Kampf nicht verschieben.",
	["Frames shown"] = "Angezeigte Rahmen",
	["Frames snap to the grid, to each other's edges and centers, and to the screen center. Hold Alt while dragging to place freely."] = "Rahmen rasten am Raster, an den Kanten und Mitten anderer Rahmen und an der Bildschirmmitte ein. Haltet beim Ziehen Alt gedrückt, um sie frei zu platzieren.",
	["Frames stay put; the mana bar shows the five-second rule."] = "Rahmen bleiben, wo sie sind; die Manaleiste zeigt die Fünf-Sekunden-Regel.",
	["Frames stay where the layout puts them."] = "Rahmen bleiben, wo das Layout sie hinsetzt.",
	["Frames update when combat ends."] = "Rahmen werden nach dem Kampf aktualisiert.",
	["Frames with a box: %d. Outside this view: %d. Hidden: %d. Off: %d."] = "Rahmen mit Feld: %d. Außerhalb dieser Ansicht: %d. Ausgeblendet: %d. Aus: %d.",
	["Frames you dragged go back to the layout's spots."] = "Verschobene Rahmen kehren an ihre Plätze im Layout zurück.",
	["Free text"] = "Freier Text",
	["Frees an ally (or you) from movement effects."] = "Befreit einen Verbündeten (oder Euch) von bewegungseinschränkenden Effekten.",
	["Freezing Trap: the enemy that steps on it freezes."] = "Eiskältefalle: Der Feind, der hineintritt, friert ein.",
	["French"] = "Französisch",
	["French keyboard (AZERTY): A, Z, Q, W and M sit in other places."] = "Französische Tastatur (AZERTY): A, Z, Q, W und M liegen an anderen Stellen.",
	["Frenzied Regeneration is on the Short defensive button."] = "Rasende Regeneration liegt auf der Taste „Kurze Defensive“.",
