	["Friends, Who and Raid tab"] = "Reiter Freunde, Wer und Schlachtzug",
	["Friends/Who/Raid, guild and communities, calendar, the Vanilla-style Group Finder and PvP scoreboard."] = "Freunde/Wer/Schlachtzug, Gilde und Communitys, Kalender, die Gruppensuche im Vanilla-Stil und die PvP-Punktetafel.",
	["From %s"] = "Von %s",
