	["Fwd"] = "Vor",
	["Gaining threat"] = "Bedrohung steigt",
	["Game buttons that EldoUI doesn't style show the seconds left on a cooldown. EldoUI's own buttons have their own cooldown numbers."] = "Tasten des Spiels, die EldoUI nicht gestaltet, zeigen die restlichen Sekunden einer Abklingzeit. EldoUIs eigene Tasten haben eigene Abklingzeitzahlen.",
	["Game colors"] = "Spielfarben",
	["Game error window"] = "Fehlerfenster des Spiels",
	["Game flag"] = "Spielkategorie",
	["Game font scale"] = "Schriftskalierung des Spiels",
	["Game fonts"] = "Spielschriften",
	["Game keys"] = "Spieltasten",
	["Game keys, and where %s moves them:"] = "Spieltasten und wohin %s sie verlegt:",
	["Game keys:"] = "Spieltasten:",
	["Game menu"] = "Spielmenü",
	["Game menu (Esc)"] = "Spielmenü (Esc)",
	["Game menu, Settings, AddOn list, keybinds, macros, Edit Mode integration, pop-up dialogs and Blizzard service windows."] = "Spielmenü, Einstellungen, AddOn-Liste, Tastenbelegungen, Makros, Anbindung an den Bearbeitungsmodus, Dialogfenster und Blizzard-Dienstfenster.",
	["Game setting"] = "Spieleinstellung",
	["Game settings"] = "Spieleinstellungen",
	["Game settings are kept per character: the ones checked here are set the way the setup's Game settings step does it."] = "Spieleinstellungen gelten pro Charakter: Die hier angekreuzten werden so gesetzt, wie es der Einrichtungsschritt „Spieleinstellungen“ tut.",
	["Game settings: %s"] = "Spieleinstellungen: %s",
	["Game settings: keep"] = "Spieleinstellungen: behalten",
	["Game shortcut, moved from %s"] = "Spielkürzel, verlegt von %s",
	["Game shortcut, moved with the pet bar"] = "Spielkürzel, mit der Begleiterleiste verlegt",
	["Gamepad Mode UI"] = "Gamepad-Modus-UI",
	["Gamepad Mode UI is on. It starts when you turn on the game's gamepad interface in the game's Controller settings."] = "Gamepad-Modus-UI ist an. Sie startet, wenn Ihr die Gamepad-Oberfläche des Spiels in dessen Controller-Einstellungen einschaltet.",
	["Gamepad Mode UI offers a controller layout, with your usual frame positions kept for switching back to mouse and keyboard."] = "Gamepad-Modus-UI bietet ein Controller-Layout und behält Eure gewohnten Rahmenpositionen für den Wechsel zurück zu Maus und Tastatur.",
	["Gamepad action bar and controller HUD"] = "Gamepad-Aktionsleiste und Controller-HUD",
	["Gamepad: The Classic movement key set puts bars 1 to 3 on 1-5 R F G V X Z C, with Shift for bar 2 and Ctrl for bar 3, so T is free and V is used."] = "Gamepad: Der Tastensatz „Classic-Bewegung“ legt die Leisten 1 bis 3 auf 1-5 R F G V X Z C, mit Umschalt für Leiste 2 und Strg für Leiste 3, sodass T frei bleibt und V belegt wird.",
	["Gear at or below this durability shows as low (red) everywhere EldoUI shows durability."] = "Ausrüstung mit dieser Haltbarkeit oder weniger gilt überall, wo EldoUI Haltbarkeit anzeigt, als niedrig (rot).",
	["Gear at or below this durability shows as worn (yellow) everywhere EldoUI shows durability: the Info Bar, the character window, the ready report and the reminders."] = "Ausrüstung mit dieser Haltbarkeit oder weniger gilt überall, wo EldoUI Haltbarkeit anzeigt, als abgenutzt (gelb): in der Infoleiste, im Charakterfenster, im Bereitschaftsbericht und in den Erinnerungen.",
	["General"] = "Allgemein",
	["General (theme, fonts, scale)"] = "Allgemein (Theme, Schriften, Skalierung)",
	["General setting"] = "Allgemeine Einstellung",
	["General, Trade, LookingForGroup and the other numbered channels also get their own tab. The main window keeps them too."] = "Allgemein, Handel, SucheNachGruppe und die anderen nummerierten Kanäle bekommen ebenfalls einen eigenen Reiter. Das Hauptfenster behält sie auch.",
	["General: Entering a battleground no longer shows an error from the character overview's calendar check."] = "Allgemein: Beim Betreten eines Schlachtfelds erscheint kein Fehler mehr aus der Kalenderprüfung der Charakterübersicht.",
	["General: Every EldoUI version can be downloaded as a zip from its release page."] = "Allgemein: Jede EldoUI-Version lässt sich als ZIP von ihrer Release-Seite herunterladen.",
	["General: Gnome Dash has calm scenery on every course, and coins and opponents show as round pictures without boxes, so it is easy to see what you can stand on."] = "Allgemein: Gnomensprint hat auf jeder Strecke eine ruhige Kulisse, und Münzen und Gegner erscheinen als runde Bilder ohne Kästen, sodass leicht zu sehen ist, worauf Ihr stehen könnt.",
	["General: In Gnome Dash you steer an animated gnome and, after a mushroom, a dwarf that runs, jumps and faces the way it moves, instead of a portrait picture."] = "Allgemein: In Gnomensprint steuert Ihr statt eines Porträtbilds einen animierten Gnom und nach einem Pilz einen Zwerg, der läuft, springt und in seine Laufrichtung schaut.",
	["General: In Gnome Dash, the gnome and the dwarf face the way they run instead of running backwards."] = "Allgemein: In Gnomensprint schauen Gnom und Zwerg in ihre Laufrichtung, statt rückwärts zu laufen.",
	["General: In Gnome Dash, the gnome and the dwarf wear their own clothes and colors instead of showing plain white."] = "Allgemein: In Gnomensprint tragen Gnom und Zwerg ihre eigene Kleidung und Farben, statt einfach weiß zu erscheinen.",
	["General: Names in Cyrillic, Korean and Chinese show their letters on nameplates, unit frames and every other place EldoUI shows a name, where they were empty boxes before."] = "Allgemein: Namen in kyrillischer, koreanischer und chinesischer Schrift zeigen ihre Zeichen auf Namensplaketten, Einheitenrahmen und überall sonst, wo EldoUI einen Namen zeigt; vorher waren es leere Kästchen.",
	["General: The bug report form and the support pages name the error window's Report button, as the game shows it."] = "Allgemein: Das Fehlerberichtsformular und die Support-Seiten nennen die Melden-Schaltfläche des Fehlerfensters so, wie das Spiel sie anzeigt.",
	["General: The install guide and the release notes name the WoW: Forever game folder, _forever_; the guide tells beta players to install EldoUI there again."] = "Allgemein: Die Installationsanleitung und die Versionshinweise nennen den Spielordner von WoW: Forever, _forever_; die Anleitung bittet Beta-Spieler, EldoUI dort erneut zu installieren.",
	["General: The note after an update has a \"Never show again, even after updates\" check box; the switch on the What's new page turns the note back on."] = "Allgemein: Der Hinweis nach einem Update hat ein Kästchen „Nie wieder anzeigen, auch nicht nach Updates“; der Schalter auf der Seite „Neuigkeiten“ schaltet den Hinweis wieder ein.",
	["German"] = "Deutsch",
	["German keyboard (QWERTZ): Z and Y swap places."] = "Deutsche Tastatur (QWERTZ): Z und Y tauschen die Plätze.",
	["Gets you somewhere fast: a charge, blink or sprint."] = "Bringt Euch schnell irgendwohin: ein Sturmangriff, Blinzeln oder Sprinten.",
	["Ghost"] = "Geist",
	["Ghost Wolf, on the Movement ability button, is the shaman's movement spell."] = "Geisterwolf auf der Taste „Bewegungsfähigkeit“ ist der Bewegungszauber des Schamanen.",
	["Give a module name. See %s."] = "Gebt einen Modulnamen an. Siehe %s.",
	["Give one part its own skin. Follow skin keeps it with the rest."] = "Gebt einem Teil einen eigenen Skin. „Skin folgen“ hält ihn beim Rest.",
	["Give this frame the width or height of another frame. It is saved in this frame's own size setting."] = "Gebt diesem Rahmen die Breite oder Höhe eines anderen Rahmens. Sie wird in der eigenen Größeneinstellung dieses Rahmens gespeichert.",
	["Give this key to the key set. The manual bar loses it."] = "Diese Taste an den Tastensatz übergeben. Die manuelle Leiste verliert sie.",
	["Give to this character"] = "Diesem Charakter geben",
	["Global settings"] = "Globale Einstellungen",
	["Glow"] = "Leuchten",
	["Glow preview (click to close)"] = "Leuchtvorschau (Klicken zum Schließen)",
	["Glows"] = "Leuchteffekte",
	["Glows round a cast bar on unit frames and nameplates while the spell is one the game marks as important."] = "Leuchtet um eine Zauberleiste an Einheitenrahmen und Namensplaketten, solange das Spiel den Zauber als wichtig markiert.",
	["Glows, pulses and sliding windows hold still; highlights stay as a steady border in their color. For players who get dizzy or distracted by moving parts. Same switch as General > Animations."] = "Leuchten, Pulsieren und gleitende Fenster bleiben still; Hervorhebungen bleiben als ruhiger Rand in ihrer Farbe. Für Spieler, denen bewegte Teile Schwindel bereiten oder die sie ablenken. Derselbe Schalter wie Allgemein > Animationen.",
	["Go back to your profile %s and remove the imported profile."] = "Zurück zu Eurem Profil %s und das importierte Profil entfernen.",
	["Go straight to the review page with this layout and the picks of the other steps as they are. Finish applies them; Change goes back to any step."] = "Direkt zur Übersichtsseite mit diesem Layout und der Auswahl der anderen Schritte, wie sie ist. „Abschließen“ übernimmt sie; „Ändern“ führt zu einem beliebigen Schritt zurück.",
	["Goes back to %s."] = "Geht zurück zu %s.",
	["Goes on to the first step."] = "Weiter zum ersten Schritt.",
	["Goes on to the next step."] = "Weiter zum nächsten Schritt.",
	["Goes through every step of the setup on its own, from the Welcome step, as on a first character."] = "Geht jeden Schritt der Einrichtung einzeln durch, ab dem Schritt „Willkommen“, wie bei einem ersten Charakter.",
	["Goes through the steps with the picked pack filled in; change anything on the way."] = "Geht die Schritte mit dem gewählten Paket ausgefüllt durch; unterwegs lässt sich alles ändern.",
	["Good"] = "Gut",
	["Gossip"] = "Gespräch",
	["Grid"] = "Raster",
	["Grid color"] = "Rasterfarbe",
	["Grid line width"] = "Rasterlinienbreite",
	["Grid opacity"] = "Rasterdeckkraft",
	["Grid size"] = "Rastergröße",
	["Group"] = "Gruppe",
	["Group %d"] = "Gruppe %d",
	["Group Finder (LFG) window"] = "Fenster der Gruppensuche (LFG)",
	["Group and Instances"] = "Gruppe und Instanzen",
	["Group defensive"] = "Gruppendefensive",
	["Group finder"] = "Gruppensuche",
	["Group frame on the layout's party or raid spot"] = "Gruppenrahmen am Gruppen- oder Schlachtzugsplatz des Layouts",
	["Group frames"] = "Gruppenrahmen",
	["Group frames: With the raid manager side panel skinned, the ready check, role poll, countdown and option buttons show their icons again."] = "Gruppenrahmen: Mit gestaltetem Seitenpanel des Schlachtzugsmanagers zeigen die Schaltflächen für Bereitschaftscheck, Rollenabfrage, Countdown und Optionen wieder ihre Symbole.",
	["Group loot rolls and loot history"] = "Gruppen-Beutewürfe und Beuteverlauf",
	["Group members out of range fade. The game answers the range; the frame's alpha comes straight from it."] = "Gruppenmitglieder außer Reichweite verblassen. Die Reichweite liefert das Spiel; die Deckkraft des Rahmens folgt direkt daraus.",
	["Group on"] = "Gruppe an",
	["Growl is on the Interrupt button of Bear Form; your own pick."] = "Knurren liegt auf der Taste „Unterbrechen“ der Bärengestalt; Eure eigene Wahl.",
	["Growl is the tank's, on the Interrupt button of Bear Form; your own pick."] = "Knurren gehört dem Tank, auf der Taste „Unterbrechen“ der Bärengestalt; Eure eigene Wahl.",
	["Grp"] = "Grp",
	["Guess from the game language (%s)"] = "Aus der Spielsprache ableiten (%s)",
	["Guild and communities"] = "Gilde und Communitys",
	["Guild bank first"] = "Zuerst Gildenbank",
	["Guild control"] = "Gildenverwaltung",
	["Guild info editor"] = "Gildeninfo-Editor",
	["Guild invitation"] = "Gildeneinladung",
	["Guild log"] = "Gildenprotokoll",
	["Guild news filters"] = "Gildennachrichten-Filter",
	["Guild recruitment"] = "Gildenrekrutierung",
	["Guild registrar"] = "Gildenregistrierung",
	["Guild rename"] = "Gilde umbenennen",
	["HUD presets"] = "HUD-Vorlagen",
	["Hammer of Justice is on the Interrupt button, where melee stop casts."] = "Hammer der Gerechtigkeit liegt auf der Taste „Unterbrechen“, mit der Nahkämpfer Zauber stoppen.",
	["Hammer of Justice is on the Interrupt button, where tanks stop casts."] = "Hammer der Gerechtigkeit liegt auf der Taste „Unterbrechen“, mit der Tanks Zauber stoppen.",
	["Hammer of Justice is the paladin stop: on the Interrupt button for tanks and melee, on Hard control for healers."] = "Hammer der Gerechtigkeit ist der Stopp des Paladins: auf „Unterbrechen“ für Tanks und Nahkämpfer, auf „Harte Kontrolle“ für Heiler.",
	["Hammer of Justice: a stun."] = "Hammer der Gerechtigkeit: eine Betäubung.",
	["Hammered iron with clipped steel rims, riveted corner plates and octagon portrait frames. Brass marks only what is selected. Brings the Sand accent while yours is the default blue."] = "Gehämmertes Eisen mit abgeschrägten Stahlrändern, genieteten Eckplatten und achteckigen Porträtrahmen. Messing markiert nur, was ausgewählt ist. Bringt den Akzent „Sand“ mit, solange Eurer das Standardblau ist.",
	["Hammered iron with clipped steel rims."] = "Gehämmertes Eisen mit abgeschrägten Stahlrändern.",
	["Handled by %s."] = "Wird von %s übernommen.",
	["Hang this frame below, above or beside another frame, so it follows when that frame moves. Dragging it or typing X or Y detaches it again."] = "Hängt diesen Rahmen unter, über oder neben einen anderen Rahmen, damit er ihm folgt, wenn jener sich bewegt. Ziehen oder Eingeben von X oder Y löst ihn wieder.",
	["Hard control"] = "Harte Kontrolle",
	["Hated"] = "Hasserfüllt",
	["Heal absorb"] = "Heilabsorption",
	["Heal absorbs on the unit (healing that is eaten first)."] = "Heilabsorptionen auf der Einheit (Heilung, die zuerst aufgezehrt wird).",
	["Heal over time"] = "Heilung über Zeit",
	["Heal prediction"] = "Heilvorhersage",
	["Healer"] = "Heiler",
	["Healer group frames"] = "Heiler-Gruppenrahmen",
	["Healers can bind heals and dispels to modifier clicks on group frames. The setup suggests spells; check the ones you want."] = "Heiler können Heilungen und Bannungen auf Klicks mit Zusatztasten an Gruppenrahmen legen. Die Einrichtung schlägt Zauber vor; kreuzt die gewünschten an.",
	["Healers get Dispel Magic on this key: it cleanses allies and purges enemies."] = "Heiler bekommen Magiebannung auf diese Taste: Sie reinigt Verbündete und bannt Effekte von Feinden.",
	["Healers get a click-cast setup here. Your role can be changed any time in %s > Role, or with %s."] = "Heiler bekommen hier eine Klickzauber-Einrichtung. Eure Rolle lässt sich jederzeit unter %s > Rolle oder mit %s ändern.",
	["Healers have Cleanse on the Interrupt button: paladins have no interrupt."] = "Heiler haben Reinigung des Glaubens auf der Taste „Unterbrechen“: Paladine haben keine Unterbrechung.",
	["Healers have Dispel Magic on the Interrupt button: it cleanses allies and purges enemies."] = "Heiler haben Magiebannung auf der Taste „Unterbrechen“: Sie reinigt Verbündete und bannt Effekte von Feinden.",
	["Healers have Remove Curse on the Interrupt button of the caster page: druids have no interrupt."] = "Heiler haben Fluch aufheben auf der Taste „Unterbrechen“ der Seite in Normalgestalt: Druiden haben keine Unterbrechung.",
	["Heals on the way to the unit, from the game's heal prediction."] = "Heilungen auf dem Weg zur Einheit, aus der Heilvorhersage des Spiels.",
	["Heals your demon."] = "Heilt Euren Dämon.",
	["Heals your pet."] = "Heilt Euer Tier.",
	["Health"] = "Gesundheit",
	["Health %"] = "Gesundheit %",
	["Health bar"] = "Gesundheitsleiste",
	["Health bar height"] = "Höhe der Gesundheitsleiste",
	["Health current"] = "Gesundheit aktuell",
	["Health current / max"] = "Gesundheit aktuell / max.",
	["Health current | %"] = "Gesundheit aktuell | %",
	["Health gradient: empty"] = "Gesundheitsverlauf: leer",
	["Health gradient: full"] = "Gesundheitsverlauf: voll",
	["Health gradient: half"] = "Gesundheitsverlauf: halb",
	["Health in percent with the % sign (75%)."] = "Gesundheit in Prozent mit dem %-Zeichen (75%).",
	["Health in percent without the % sign (75)."] = "Gesundheit in Prozent ohne das %-Zeichen (75).",
	["Health tint"] = "Gesundheitstönung",
	["Height of"] = "Höhe von",
	["Help"] = "Hilfe",
	["Help on the title bar"] = "Hilfe in der Titelleiste",
	["Helps an ally or your pet."] = "Hilft einem Verbündeten oder Eurem Begleiter.",
	["Here is what the setup changed. Revert this puts one part back as it was before."] = "Das hat die Einrichtung geändert. „Dies zurücknehmen“ setzt einen Teil wieder auf den vorherigen Stand.",
	["Hidden"] = "Ausgeblendet",
	["Hidden boxes"] = "Ausgeblendete Felder",
	["Hidden while you control a vehicle or have an override bar."] = "Ausgeblendet, solange Ihr ein Fahrzeug steuert oder eine Ersatzleiste habt.",
	["Hidden while you rest in an inn or a city."] = "Ausgeblendet, solange Ihr in einem Gasthaus oder einer Stadt rastet.",
	["Hidden while you rest in an inn or a city. If you start or stop resting during a fight, the frame follows once combat ends."] = "Ausgeblendet, solange Ihr in einem Gasthaus oder einer Stadt rastet. Beginnt oder endet Eure Rast während eines Kampfes, folgt der Rahmen nach dem Kampf.",
	["Hidden while you ride a mount, whatever the rule says."] = "Ausgeblendet, solange Ihr reitet, unabhängig von der Regel.",
	["Hidden. Show it again on the Hidden boxes page under Modules in /eui, or in move mode under Hidden."] = "Ausgeblendet. Zeigt es wieder auf der Seite „Ausgeblendete Felder“ unter Module in /eui an oder im Verschiebemodus unter „Ausgeblendet“.",
	["Hide"] = "Ausblenden",
	["Hide %s"] = "%s ausblenden",
	["Hide auras that last longer than this in total. Also hides auras without a duration."] = "Auren ausblenden, die insgesamt länger dauern. Blendet auch Auren ohne Dauer aus.",
	["Hide boxes"] = "Felder ausblenden",
	["Hide every box, name, the grid and this panel to see the real UI with its test frames. A small bar brings them back."] = "Alle Felder, Namen, das Raster und dieses Panel ausblenden, um die echte Oberfläche mit ihren Testrahmen zu sehen. Eine kleine Leiste holt sie zurück.",
	["Hide in a vehicle"] = "In Fahrzeugen ausblenden",
	["Hide the interface"] = "Interface ausblenden",
	["Hide this box"] = "Dieses Feld ausblenden",
	["Hide this frame. It stays hidden, also after a reload, until you show it again under Hidden in this menu's view list or on the Hidden boxes page."] = "Diesen Rahmen ausblenden. Er bleibt ausgeblendet, auch nach einem Neuladen, bis Ihr ihn unter „Ausgeblendet“ in der Ansichtsliste dieses Menüs oder auf der Seite „Ausgeblendete Felder“ wieder anzeigt.",
	["Hide while mounted"] = "Beim Reiten ausblenden",
	["Hide while resting"] = "Beim Rasten ausblenden",
	["Hides Blizzard's version completely. EldoUI's own frame for it, if there is one, stays."] = "Blendet Blizzards Version vollständig aus. EldoUIs eigener Rahmen dafür bleibt, falls es einen gibt.",
	["Hiding dialogs would mean answering them for you, and EldoUI never confirms anything on its own."] = "Dialoge auszublenden hieße, sie für Euch zu beantworten, und EldoUI bestätigt nie etwas von selbst.",
	["Hiding it would break the other addon's options."] = "Das Ausblenden würde die Optionen des anderen Addons beschädigen.",
	["Hiding menus would leave you without their choices."] = "Ohne die Menüs fehlten Euch ihre Auswahlmöglichkeiten.",
	["Hiding these would stop you from accepting queues and ready checks."] = "Ohne sie könntet Ihr keine Warteschlangen und Bereitschaftschecks mehr annehmen.",
	["High contrast"] = "Hoher Kontrast",
	["High contrast is on (Accessibility). Your skin shows again once it is off."] = "Hoher Kontrast ist an (Barrierefreiheit). Euer Skin erscheint wieder, sobald er aus ist.",
	["High contrast, large text, color-blind safe colors, sound cues and reduced motion."] = "Hoher Kontrast, große Schrift, farbenblind-sichere Farben, Tonsignale und reduzierte Bewegung.",
	["High contrast, large text, safe colors, sound cues and reduced motion together."] = "Hoher Kontrast, große Schrift, sichere Farben, Tonsignale und reduzierte Bewegung zusammen.",
	["High threat"] = "Hohe Bedrohung",
	["Highest rank reached"] = "Höchster erreichter Rang",
	["Highest rank this season"] = "Höchster Rang dieser Saison",
	["Hit an error"] = "Fehler aufgetreten",
	["Hold Shift for bar 2 (group help, cleanse, second spells) and Ctrl for bar 3 (utility, travel, resurrection, class buff)."] = "Haltet Umschalt für Leiste 2 (Gruppenhilfe, Reinigung, Zweitzauber) und Strg für Leiste 3 (Nützliches, Reisen, Wiederbelebung, Klassen-Stärkungszauber).",
	["Hold it and drag a side panel (calendar events, raid info, macro icons, ...) to place it on its own; with a right-click it goes back."] = "Haltet sie gedrückt und zieht ein Seitenpanel (Kalenderereignisse, Schlachtzugsinfo, Makrosymbole, ...) heraus, um es einzeln zu platzieren; mit Rechtsklick kehrt es zurück.",
	["Hold it and right-click the title bar to put the window back where Blizzard places it."] = "Haltet sie gedrückt und rechtsklickt auf die Titelleiste, um das Fenster dorthin zurückzusetzen, wo Blizzard es platziert.",
	["Hold it and turn the mouse wheel over the title bar to scale the window; with a right-click it sets the normal size again."] = "Haltet sie gedrückt und dreht das Mausrad über der Titelleiste, um das Fenster zu skalieren; ein Rechtsklick stellt wieder die normale Größe her.",
	["Hold the mouse button (or hold Ctrl) to see the real UI for as long as you hold it."] = "Haltet die Maustaste (oder Strg) gedrückt, um die echte Oberfläche zu sehen, solange Ihr sie haltet.",
	["Hold this key (or both keys) to drag a window, so a slipped click, on a quest's Accept button for example, never moves it. No key: a plain drag moves it. Move mode needs no key."] = "Haltet diese Taste (oder beide Tasten), um ein Fenster zu ziehen, damit ein verrutschter Klick, etwa auf die Annehmen-Schaltfläche einer Quest, es nie verschiebt. Keine Taste: Einfaches Ziehen verschiebt es. Der Verschiebemodus braucht keine Taste.",
	["Hold to show the HUD"] = "Halten, um das HUD anzuzeigen",
	["Holy Candle"] = "Heilige Kerze",
	["Holy and Sacred Candles"] = "Heilige und Geweihte Kerzen",
	["Honorable kills today"] = "Ehrenhafte Siege heute",
	["Honorable kills, lifetime"] = "Ehrenhafte Siege insgesamt",
	["Honored"] = "Wohlwollend",
	["Horde"] = "Horde",
	["Horizontal"] = "Horizontal",
	["Hornbeam Seed"] = "Hainbuchensamen",
	["Hostile"] = "Feindselig",
	["Hover a button and press a key, mouse button or wheel. Escape clears."] = "Zeigt auf eine Schaltfläche und drückt eine Taste, eine Maustaste oder das Mausrad. Esc löscht.",
	["Hover any EldoUI button (action, pet, stance, extra, vehicle exit) and press a key to bind it."] = "Zeigt auf eine beliebige EldoUI-Schaltfläche (Aktion, Begleiter, Haltung, Extra, Fahrzeug verlassen) und drückt eine Taste, um sie zu belegen.",
	["Hover any EldoUI button and press a key to bind it. Out of combat only."] = "Zeigt auf eine beliebige EldoUI-Schaltfläche und drückt eine Taste, um sie zu belegen. Nur außerhalb des Kampfes.",
	["How Blizzard's own windows look. Only windows EldoUI may change are touched; this never lets EldoUI change more."] = "Wie Blizzards eigene Fenster aussehen. Nur Fenster, die EldoUI ändern darf, werden angepasst; dies erlaubt EldoUI nie, mehr zu ändern.",
	["How Blizzard's own windows look. Only windows you let EldoUI change are touched."] = "Wie Blizzards eigene Fenster aussehen. Nur Fenster, die Ihr EldoUI ändern lasst, werden angepasst.",
	["How Blizzard's own windows look. Only windows you let EldoUI change on the Blizzard UI page are touched. Original needs a reload."] = "Wie Blizzards eigene Fenster aussehen. Nur Fenster, die Ihr EldoUI auf der Seite „Blizzard-UI“ ändern lasst, werden angepasst. „Original“ erfordert ein Neuladen.",
	["How an aura that is about to run out shows."] = "Wie eine bald ablaufende Aura angezeigt wird.",
	["How big the whole UI is. EldoUI is made for 1440p; Auto keeps that size on every screen."] = "Wie groß die gesamte Oberfläche ist. EldoUI ist für 1440p gemacht; „Auto“ behält diese Größe auf jedem Bildschirm bei.",
	["How dark the frame shadows are."] = "Wie dunkel die Rahmenschatten sind.",
	["How every EldoUI clock writes the time: the Info Bar, the minimap clock, journals and logs. Game setting follows the game's own 24-hour clock option."] = "Wie jede EldoUI-Uhr die Zeit schreibt: Infoleiste, Minikartenuhr, Tagebücher und Protokolle. „Spieleinstellung“ folgt der 24-Stunden-Option des Spiels.",
	["How far a frame moves from its point at most, in screen pixels."] = "Wie weit sich ein Rahmen höchstens von seinem Punkt entfernt, in Bildschirmpixeln.",
	["How far the frame shadows reach beyond the edge of a window or panel."] = "Wie weit die Rahmenschatten über den Rand eines Fensters oder Panels hinausreichen.",
	["How gold is written in every EldoUI window, bar and tooltip. Bags, Auction House, Merchant and Trade can keep their own choice."] = "Wie Gold in jedem EldoUI-Fenster, jeder Leiste und jedem Tooltip geschrieben wird. Taschen, Auktionshaus, Händler und Handel können eine eigene Wahl behalten.",
	["How many lines (Pixel lines) or dots (Sparkle) run round the frame."] = "Wie viele Linien (Pixellinien) oder Punkte (Funkeln) um den Rahmen laufen.",
	["How much EldoUI shows. Keep as set leaves every module as it is."] = "Wie viel EldoUI anzeigt. „Wie eingestellt“ lässt jedes Modul, wie es ist.",
	["How much EldoUI shows: Essential, Moderate or Full. It only switches modules on or off."] = "Wie viel EldoUI anzeigt: Grundlegend, Mittel oder Voll. Es schaltet nur Module an oder aus.",
	["How much bigger EldoUI's text gets with Large text on, from 100 to 160 %."] = "Wie viel größer EldoUIs Text mit „Große Schrift“ wird, von 100 bis 160 %.",
	["How much one notch of the mouse wheel changes the scale."] = "Wie stark eine Raste des Mausrads die Skalierung ändert.",
	["How solid EldoUI's panels on the screen are, such as chat, tooltips and meters. Windows are always solid. See-through panels never drop below 80%, so their text stays readable."] = "Wie deckend EldoUIs Panels auf dem Bildschirm sind, etwa Chat, Tooltips und Meter. Fenster sind immer deckend. Durchsichtige Panels fallen nie unter 80%, damit ihr Text lesbar bleibt.",
	["How strongly the grid lines show in move mode."] = "Wie deutlich die Rasterlinien im Verschiebemodus erscheinen.",
	["How tags, datatexts and tooltips shorten big numbers. Secret values in combat use the game's own style."] = "Wie Tags, Datentexte und Tooltips große Zahlen kürzen. Geheime Werte im Kampf nutzen den Stil des Spiels.",
	["How the execute range shows on the health bar."] = "Wie der Hinrichtungsbereich auf der Gesundheitsleiste angezeigt wird.",
	["How the warning shows on the frame."] = "Wie die Warnung auf dem Rahmen angezeigt wird.",
	["How to play"] = "Spielweise",
	["How visible a frame stays while you are idle, for the modules you tick below."] = "Wie sichtbar ein Rahmen bleibt, während Ihr untätig seid, für die unten angekreuzten Module.",
	["How visible the frame stays while the rule says hide."] = "Wie sichtbar der Rahmen bleibt, solange die Regel „ausblenden“ sagt.",
	["Hunter: The Training window's Pet abilities tab shows your pet's happiness with the damage it gives, whether loyalty is rising, its next loyalty rank, its experience and what its family eats."] = "Jäger: Der Reiter „Tierfähigkeiten“ im Trainingsfenster zeigt die Zufriedenheit Eures Tiers und den Schaden, den es dadurch verursacht, ob die Loyalität steigt, seine nächste Loyalitätsstufe, seine Erfahrung und was seine Familie frisst.",
	["Hunters have no interrupt: Hunter's Mark takes this key."] = "Jäger haben keine Unterbrechung: Mal des Jägers liegt auf dieser Taste.",
	["I manage my own keys"] = "Ich verwalte meine Tasten selbst",
