	["Import and export"] = "Import und Export",
	["Import any string (EldoUI, EllesmereUI, ElvUI, Edit Mode) with a preview, or share your setup as one."] = "Beliebige Strings (EldoUI, EllesmereUI, ElvUI, Bearbeitungsmodus) mit Vorschau importieren oder Eure Einstellungen als String teilen.",
	["Import aura filter list"] = "Aurenfilterliste importieren",
