	["Import frame positions into the imported layout."] = "Rahmenpositionen in das importierte Layout übernehmen.",
	["Import frame sizes, action bar shapes, which bars and frames show and when, fonts and the accent color."] = "Rahmengrößen, Aktionsleistenformen, welche Leisten und Rahmen wann erscheinen, Schriften und die Akzentfarbe importieren.",
	["Import it? Nothing changes until you accept."] = "Importieren? Nichts ändert sich, bis Ihr annehmt.",
