	["Imported %s into the new profile %s: %d positions, %d settings. Your profile %s is unchanged."] = "%s in das neue Profil %s importiert: %d Positionen, %d Einstellungen. Euer Profil %s bleibt unverändert.",
	["Imported %s."] = "%s importiert.",
	["Imported %s. Some parts take full effect after a reload."] = "%s importiert. Manche Teile wirken erst nach einem Neuladen vollständig.",
	["Imported aura filter list %s."] = "Aurenfilterliste %s importiert.",
	["Imported from %s on %s. Frames the string didn't place keep the %s positions."] = "Importiert aus %s am %s. Rahmen, die der String nicht platziert hat, behalten die %s-Positionen.",
	["Imported layout."] = "Importiertes Layout.",
	["Imported layouts"] = "Importierte Layouts",
	["Imported pack"] = "Importiertes Paket",
	["Importing sets this look on your current profile. Frames you dragged stay where you put them, and Undo puts back what it changed."] = "Der Import setzt diese Optik in Eurem aktuellen Profil. Verschobene Rahmen bleiben, wo Ihr sie hingesetzt habt, und „Rückgängig“ stellt wieder her, was er geändert hat.",
	["Imports frame and bar sizes, which bars and frames show and when, chat, minimap and resource bar sizes, the font and the accent color, where EldoUI has the same setting."] = "Importiert Rahmen- und Leistengrößen, welche Leisten und Rahmen wann erscheinen, Größen von Chat, Minikarte und Ressourcenleiste, die Schriftart und die Akzentfarbe, wo EldoUI dieselbe Einstellung hat.",
	["Imports wait until you leave combat. Nothing was changed."] = "Importe warten, bis Ihr den Kampf verlasst. Es wurde nichts geändert.",
	["Improve"] = "Verbessern",
	["Improve (extra info)"] = "Verbessern (Zusatzinfos)",
	["In %s. Same as outside: the rule above applies. Always shown: stays shown there."] = "In %s. Wie außerhalb: Es gilt die Regel oben. Immer angezeigt: Bleibt dort angezeigt.",
	["In %s. Same as outside: the rule above applies. Always shown: stays shown. Fade: fades until hovered. Hide: hidden there. Only there: hidden elsewhere."] = "In %s. Wie außerhalb: Es gilt die Regel oben. Immer angezeigt: Bleibt angezeigt. Verblassen: Verblasst, bis die Maus darüber ist. Ausblenden: Dort ausgeblendet. Nur dort: Anderswo ausgeblendet.",
	["In Bear Form: a short stun."] = "In Bärengestalt: eine kurze Betäubung.",
	["In Cat Form."] = "In Katzengestalt.",
	["In combat"] = "Im Kampf",
	["In combat or with a target"] = "Im Kampf oder mit Ziel",
	["In combat: Apply waits until combat ends."] = "Im Kampf: „Übernehmen“ wartet bis zum Kampfende.",
	["In combat: changes wait until combat ends."] = "Im Kampf: Änderungen warten bis zum Kampfende.",
	["In combat: this character is attached when combat ends."] = "Im Kampf: Dieser Charakter wird nach dem Kampf zugeordnet.",
	["In instances"] = "In Instanzen",
	["In the last seconds of an aura its icon pulses or its time turns red."] = "In den letzten Sekunden einer Aura pulsiert ihr Symbol oder ihre Zeit wird rot.",
	["In use now: %s."] = "Derzeit verwendet: %s.",
	["In use now: Gamepad Mode UI is on."] = "Derzeit verwendet: Gamepad-Modus-UI ist an.",
	["In use now: Gamepad Mode UI starts when you turn on the game's gamepad interface."] = "Derzeit verwendet: Gamepad-Modus-UI startet, wenn Ihr die Gamepad-Oberfläche des Spiels einschaltet.",
	["In use now: your normal layout, also with a controller."] = "Derzeit verwendet: Euer normales Layout, auch mit Controller.",
	["In-game checks:"] = "Prüfungen im Spiel:",
	["Include frame positions"] = "Rahmenpositionen einschließen",
	["Infernal Stone"] = "Infernal Stone",
	["Info Bar"] = "Infoleiste",
	["Info Bar: A new PvP rank block, and an optional PvP rank bar with the Status Bars, show your season rank and the Rank Points to the next one, or that you reached this week's cap."] = "Infoleiste: Ein neuer Block PvP-Rang und eine wählbare PvP-Rangleiste bei den Erfahrungs- und Rufleisten zeigen Euren Saisonrang und die Rangpunkte bis zum nächsten oder dass Ihr die Obergrenze dieser Woche erreicht habt.",
	["Info Bar: The Hit and Spell hit blocks count the hit rating on your gear, so they match the character sheet."] = "Infoleiste: Die Blöcke Treffer und Zaubertreffer zählen die Trefferwertung Eurer Ausrüstung mit, sodass sie zum Charakterbogen passen.",
	["Info bar at the bottom, stacked bar rows, guide and quests on the right."] = "Infoleiste unten, gestapelte Leistenreihen, Guide und Quests rechts.",
