	["It becomes a new profile with this name (or choose parts for your current profile):"] = "Es wird ein neues Profil mit diesem Namen (oder wählt Teile für Euer aktuelles Profil):",
	["It is already set up."] = "Es ist bereits eingerichtet.",
	["It is set up and used by %s."] = "Es ist eingerichtet und wird von %s genutzt.",
	["It may not exist on every Forever build."] = "Es gibt es vielleicht nicht in jedem Forever-Build.",
	["It moves out of combat only."] = "Es lässt sich nur außerhalb des Kampfes verschieben.",
	["It would break the window."] = "Das würde das Fenster beschädigen.",
	["Item counts on tooltips"] = "Gegenstandsanzahl in Tooltips",
