	["Layouts"] = "Layouts",
	["Layouts and styles"] = "Layouts und Stile",
	["Layouts are made for a 1440 px tall screen. On scales their positions to your screen height; off uses them as they are. Frames you dragged are never scaled."] = "Layouts sind für einen 1440 px hohen Bildschirm gemacht. An skaliert ihre Positionen auf Eure Bildschirmhöhe; Aus verwendet sie unverändert. Verschobene Rahmen werden nie skaliert.",
	["Layouts can't be changed in combat."] = "Layouts lassen sich im Kampf nicht ändern.",
	["Layouts imported from other UIs show up under Layouts like the built-in ones, named after the profile they were imported into."] = "Aus anderen UIs importierte Layouts erscheinen wie die eingebauten unter Layouts, benannt nach dem Profil, in das sie importiert wurden.",
