	["Macro %s: added"] = "Makro %s: hinzugefügt",
	["Macro %s: carry the item first, then run the class setup again"] = "Makro %s: Tragt zuerst den Gegenstand bei Euch, dann führt die Klasseneinrichtung erneut aus",
	["Macro %s: no room for another character macro"] = "Makro %s: kein Platz für ein weiteres Charaktermakro",
