	["Macros"] = "Makros",
	["Macros and click-casting setup"] = "Makros und Klickzauber-Einrichtung",
	["Made for wide screens: one long bar row along the bottom, unit frames well apart at cast bar height, pet beside the player, panels at the screen edges."] = "Für breite Bildschirme gemacht: eine lange Leistenreihe am unteren Rand, Einheitenrahmen weit auseinander auf Höhe der Zauberleiste, Begleiter neben dem Spieler, Panels an den Bildschirmrändern.",
	["Magic"] = "Magie",
	["Mailbox"] = "Briefkasten",
	["Main Bar"] = "Hauptleiste",
	["Main action bar (bar 1) and end caps"] = "Hauptaktionsleiste (Leiste 1) und Endkappen",
	["Main action block"] = "Hauptaktionsblock",
	["Main cooldown"] = "Hauptabklingzeit",
	["Make EldoUI easier to read, to hear and to follow. Each switch works on its own; Undo puts back what you had before the last change."] = "Macht EldoUI leichter lesbar, hörbar und verständlich. Jeder Schalter wirkt für sich; „Rückgängig“ stellt wieder her, was Ihr vor der letzten Änderung hattet.",
	["Make a copy for %s"] = "Kopie für %s anlegen",
	["Make a layout added to Edit Mode the active Edit Mode layout."] = "Ein zum Bearbeitungsmodus hinzugefügtes Layout zum aktiven Layout des Bearbeitungsmodus machen.",
	["Mana"] = "Mana",
	["Mana while the unit shows another power, e.g. a druid in bear or cat form. Empty otherwise."] = "Mana, während die Einheit eine andere Ressource zeigt, z. B. ein Druide in Bären- oder Katzengestalt. Sonst leer.",
	["Manage"] = "Verwalten",
	["Managed by EldoUI"] = "Von EldoUI verwaltet",
	["Map and minimap: Buttons on the minimap's side rail keep the rail's order, whichever one you put there first."] = "Karte und Minikarte: Schaltflächen auf der Seitenleiste der Minikarte behalten deren Reihenfolge, egal welche Ihr zuerst dort platziert habt.",
	["Map and minimap: Gathering knows WoW: Forever's Heavy Thorium vein in Mount Hyjal once you mine it: its pins and tooltip show the Mining 300 requirement, and the skill filter treats it like every other vein."] = "Karte und Minikarte: Sammeln kennt die Ader Heavy Thorium von WoW: Forever am Berg Hyjal, sobald Ihr sie abbaut: Ihre Markierungen und ihr Tooltip zeigen die Voraussetzung Bergbau 300, und der Fertigkeitsfilter behandelt sie wie jede andere Ader.",
	["Map and minimap: Layer hop asks the players in your zone directly and also works with players who use the most common layer addon, so many more players can invite you to another layer."] = "Karte und Minikarte: Der Layerwechsel fragt die Spieler in Eurem Gebiet direkt und funktioniert auch mit Spielern, die das verbreitetste Layer-Addon nutzen, sodass Euch viel mehr Spieler auf einen anderen Layer einladen können.",
	["Map and minimap: Layer hop has two new options, Leave the group by itself and Invite without a card, both off until you turn them on."] = "Karte und Minikarte: Der Layerwechsel hat zwei neue Optionen, „Gruppe von selbst verlassen“ und „Ohne Karte einladen“, beide aus, bis Ihr sie einschaltet.",
	["Map and minimap: Logging in no longer shows a blocked-action error from the minimap, and the minimap now shows the name of the player who pings it."] = "Karte und Minikarte: Beim Einloggen zeigt die Minikarte keinen Fehler wegen einer blockierten Aktion mehr, und sie zeigt jetzt den Namen des Spielers, der sie anpingt.",
	["Map and minimap: Opening the world map with its key in a battleground no longer reports a blocked action, after the Info Bar, the flight view or the experience bar opened the map earlier."] = "Karte und Minikarte: Das Öffnen der Weltkarte mit ihrer Taste auf einem Schlachtfeld meldet keine blockierte Aktion mehr, nachdem die Infoleiste, die Flugansicht oder die Erfahrungsleiste die Karte zuvor geöffnet hatte.",
	["Map and minimap: The layer chip reads your layer the way the live realms keep it, so it shows the same layer as other players near you."] = "Karte und Minikarte: Die Layer-Anzeige liest Euren Layer so, wie die Live-Realms ihn führen, und zeigt daher denselben Layer wie andere Spieler in Eurer Nähe.",
	["Map and minimap: The minimap starts without an error again after you log in."] = "Karte und Minikarte: Die Minikarte startet nach dem Einloggen wieder ohne Fehler.",
	["Map and minimap: Zone Info knows WoW: Forever's new zones (Riverglades, Shen'dralas, Mount Hyjal and Zephras Isle) and shows their level range and territory when the game gives none."] = "Karte und Minikarte: Zone Info kennt die neuen Gebiete von WoW: Forever (Riverglades, Shen'dralas, Berg Hyjal und Zephras Isle) und zeigt ihren Stufenbereich und ihre Zugehörigkeit, wenn das Spiel keine angibt.",
	["Map, minimap and objectives"] = "Karte, Minikarte und Ziele",
	["Maple Seed"] = "Ahornsamen",
