	["Nameplates show spell, interrupt, and quest text in more alphabets."] = "Namensplaketten zeigen Zauber-, Unterbrechungs- und Questtexte in mehr Alphabeten.",
	["Nameplates, bags, cooldown displays and many other parts do much less work, and background work pauses in combat."] = "Namensplaketten, Taschen, Abklingzeitanzeigen und viele andere Teile arbeiten deutlich sparsamer, und Hintergrundarbeit pausiert im Kampf.",
	["Nameplates: Changing your target with an ability or key no longer shows an error from the target's nameplate."] = "Namensplaketten: Wechselt Ihr Euer Ziel mit einer Fähigkeit oder Taste, zeigt die Namensplakette des Ziels keinen Fehler mehr.",
	["Nameplates: The Game settings tab of the nameplate options has a Plate distance slider."] = "Namensplaketten: Der Reiter „Spieleinstellungen“ der Namensplakettenoptionen hat einen Regler für die Plakettenentfernung.",
	["Names"] = "Namen",
	["Names in say, party, raid, guild, whispers and channels show in their class color."] = "Namen in Sagen, Gruppe, Schlachtzug, Gilde, Flüstern und Kanälen erscheinen in ihrer Klassenfarbe.",
	["Names over heads"] = "Namen über Köpfen",
	["Needed"] = "Benötigt",
	["Needed for %s"] = "Benötigt für %s",
	["Needs EldoUI %s or newer."] = "Benötigt EldoUI %s oder neuer.",
	["Needs a reload to bring Blizzard's look fully back."] = "Braucht ein Neuladen, um Blizzards Optik vollständig zurückzubringen.",
	["Neutral"] = "Neutral",
	["Never"] = "Nie",
	["Never on this character"] = "Nie auf diesem Charakter",
	["Never show again, even after updates"] = "Nie wieder anzeigen, auch nicht nach Updates",
	["Never spells on"] = "Nie Zauber auf",
	["New %s characters start with profile %s."] = "Neue %s-Charaktere starten mit dem Profil %s.",
	["New %s characters start with the Default profile."] = "Neue %s-Charaktere starten mit dem Standardprofil.",
	["New buffs and debuffs pop in. The game plays the animation."] = "Neue Stärkungs- und Schwächungszauber ploppen auf. Das Spiel spielt die Animation ab.",
	["New character: using the %s class profile %s (/eui > Profile rules)."] = "Neuer Charakter: nutzt das %s-Klassenprofil %s (/eui > Profilregeln).",
	["New characters"] = "Neue Charaktere",
	["New class reminders for warlocks, rogues, priests, warriors and druids, and a Pet abilities tab for hunters."] = "Neue Klassenerinnerungen für Hexenmeister, Schurken, Priester, Krieger und Druiden sowie ein Reiter „Tierfähigkeiten“ für Jäger.",
	["New in this version"] = "Neu in dieser Version",
	["New list"] = "Neue Liste",
	["New profile"] = "Neues Profil",
	["New spells"] = "Neue Zauber",
	["New spells have a button waiting: %s."] = "Für neue Zauber wartet ein Platz: %s.",
	["New spells placed: %s. /eui spells undo takes them off again."] = "Neue Zauber platziert: %s. /eui spells undo nimmt sie wieder herunter.",
	["New whispers show in your chat (and its Whispers tab) instead of opening a window of their own."] = "Neues Flüstern erscheint in Eurem Chat (und dessen Reiter „Flüstern“), statt ein eigenes Fenster zu öffnen.",
	["Newer addon profiles"] = "Neuere Addon-Profile",
	["Newer profile ready"] = "Neueres Profil bereit",
	["Next"] = "Weiter",
	["Next reward"] = "Nächste Belohnung",
	["No"] = "Nein",
	["No %s: %s"] = "Kein %s: %s",
	["No Blizzard category %q. Use one of: %s."] = "Keine Blizzard-Kategorie %q. Verwendet eine von: %s.",
	["No Blizzard element %q. Type /eui blizz for the list."] = "Kein Blizzard-Element %q. Gebt /eui blizz für die Liste ein.",
	["No EldoUI frame for: %s"] = "Kein EldoUI-Rahmen für: %s",
	["No EldoUI module changes this element yet."] = "Noch kein EldoUI-Modul ändert dieses Element.",
	["No EldoUI profile yet"] = "Noch kein EldoUI-Profil",
	["No EldoUI skin yet, so they keep Blizzard's look: %d."] = "Noch kein EldoUI-Skin, daher behalten sie Blizzards Optik: %d.",
	["No addon can restyle these protected frames."] = "Kein Addon kann diese geschützten Rahmen umgestalten.",
	["No addon named %s does an EldoUI job. Type %s for the list."] = "Kein Addon namens %s übernimmt eine EldoUI-Aufgabe. Gebt %s für die Liste ein.",
	["No addon named %s is placed by the layouts. Type %s for the list."] = "Kein Addon namens %s wird von den Layouts platziert. Gebt %s für die Liste ein.",
	["No bar on the top edge"] = "Keine Leiste am oberen Rand",
	["No big defensive: Nature's Swiftness and a heal are the emergency."] = "Keine große Defensive: Schnelligkeit der Natur und eine Heilung sind der Notfallknopf.",
	["No box is hidden. Right-click a box on screen, or in move mode, and choose Hide to hide it."] = "Kein Feld ist ausgeblendet. Rechtsklickt auf ein Feld auf dem Bildschirm oder im Verschiebemodus und wählt „Ausblenden“.",
	["No change"] = "Keine Änderung",
	["No changes yet"] = "Noch keine Änderungen",
	["No class spell goes here: the button is yours to fill."] = "Hier kommt kein Klassenzauber hin: Den Platz füllt Ihr selbst.",
	["No command %q. Type %s for the full list."] = "Kein Befehl %q. Gebt %s für die vollständige Liste ein.",
	["No command matches the filter."] = "Kein Befehl passt zum Filter.",
	["No copies yet. EldoUI keeps one the first time an update changes your saved data."] = "Noch keine Kopien. EldoUI legt eine an, wenn ein Update zum ersten Mal Eure gespeicherten Daten ändert.",
	["No copy of that. Type %s to see the copies."] = "Davon gibt es keine Kopie. Gebt %s ein, um die Kopien zu sehen.",
	["No dragging, scaling or resetting until you unlock them. Saved places still apply. Also /eui windows lock."] = "Kein Ziehen, Skalieren oder Zurücksetzen, bis Ihr sie entsperrt. Gespeicherte Positionen gelten weiterhin. Auch /eui windows lock.",
	["No errors logged"] = "Keine Fehler protokolliert",
	["No frame was dragged: every frame is where the layout puts it."] = "Kein Rahmen wurde verschoben: Jeder Rahmen ist dort, wo das Layout ihn hinsetzt.",
	["No free chat window left for the %s tab."] = "Kein freies Chatfenster mehr für den Reiter %s.",
	["No healing or dispel spells of your class were found in your spellbook yet. Bind spells yourself any time in /eui > Click Casting."] = "In Eurem Zauberbuch wurden noch keine Heil- oder Bannzauber Eurer Klasse gefunden. Belegt Zauber jederzeit selbst unter /eui > Klickzauber.",
	["No key"] = "Keine Taste",
	["No key here can be bound alone on this keyboard."] = "Keine Taste hier lässt sich auf dieser Tastatur allein belegen.",
	["No key set %q. Use %s, %s, or %s alone for keybind mode."] = "Kein Tastensatz %q. Verwendet %s, %s oder nur %s für den Tastenbelegungsmodus.",
	["No key set chosen yet. The Keybinds page and the setup's Keys and spells step offer them."] = "Noch kein Tastensatz gewählt. Die Seite „Tastenbelegungen“ und der Einrichtungsschritt „Tasten und Zauber“ bieten sie an.",
	["No layout named %q."] = "Kein Layout namens %q.",
	["No main cooldown before talents; healers have Divine Favor on Second rotation 3."] = "Keine Hauptabklingzeit vor den Talenten; Heiler haben Göttliche Gunst auf „Zweite Rotation 3“.",
	["No missing translations recorded so far."] = "Bisher keine fehlenden Übersetzungen erfasst.",
	["No module named %q."] = "Kein Modul namens %q.",
	["No module offers style presets."] = "Kein Modul bietet Stilvorlagen an.",
	["No module that glows is switched on."] = "Kein Modul mit Leuchteffekten ist eingeschaltet.",
	["No module with a fading frame is on."] = "Kein Modul mit ausblendendem Rahmen ist an.",
	["No modules"] = "Keine Module",
	["No more offers about keys on this character. The Keybinds page still applies a key set."] = "Keine weiteren Tastenangebote auf diesem Charakter. Die Seite „Tastenbelegungen“ wendet weiterhin einen Tastensatz an.",
	["No more reminders on this profile, and the setup no longer opens by itself. %s still opens it."] = "Keine Erinnerungen mehr für dieses Profil, und die Einrichtung öffnet sich nicht mehr von selbst. %s öffnet sie weiterhin.",
	["No movement spell in Defensive Stance: Taunt takes this key."] = "Kein Bewegungszauber in Verteidigungshaltung: Spott liegt auf dieser Taste.",
	["No other addon does the same job as part of EldoUI right now."] = "Derzeit erledigt kein anderes Addon dieselbe Aufgabe wie ein Teil von EldoUI.",
	["No other profile yet"] = "Noch kein anderes Profil",
	["No placed controller spells to take back on this character."] = "Keine platzierten Controller-Zauber zum Zurücknehmen auf diesem Charakter.",
	["No placed spells to take back on this character."] = "Keine platzierten Zauber zum Zurücknehmen auf diesem Charakter.",
	["No plugin named %s."] = "Kein Plugin namens %s.",
	["No plugins are installed."] = "Keine Plugins installiert.",
	["No plugins are installed. EldoUI works fully without them."] = "Keine Plugins installiert. EldoUI funktioniert auch ohne sie vollständig.",
	["No profile named %q."] = "Kein Profil namens %q.",
	["No profile named %q. %s shows them; %s makes a new one."] = "Kein Profil namens %q. %s zeigt sie an; %s legt ein neues an.",
	["No rank yet"] = "Noch kein Rang",
	["No reminder again until your next login."] = "Keine Erinnerung mehr bis zum nächsten Einloggen.",
