	["No setup pages to show."] = "Keine Einrichtungsseiten vorhanden.",
	["No setup step %q. Steps: %s."] = "Kein Einrichtungsschritt %q. Schritte: %s.",
	["No spell found for %q. Use a spell ID, the exact name or a chat link."] = "Kein Zauber für %q gefunden. Verwendet eine Zauber-ID, den genauen Namen oder einen Chatlink.",
	["No tutorial pop-ups"] = "Keine Tutorial-Einblendungen",
	["None"] = "Nichts",
	["None of the addons EldoUI has profiles for is loaded."] = "Keines der Addons, für die EldoUI Profile hat, ist geladen.",
	["None of the addons the layouts can place is loaded."] = "Keines der Addons, die die Layouts platzieren können, ist geladen.",
	["None of these lists exist in your EldoUI."] = "Keine dieser Listen gibt es in Eurem EldoUI.",
	["None."] = "Keine.",
	["None. Nothing older is left in your saved files."] = "Keine. In Euren gespeicherten Dateien ist nichts Älteres übrig.",
	["None. When you restore a copy, what it replaces is kept here."] = "Keine. Wenn Ihr eine Kopie wiederherstellt, wird hier aufbewahrt, was sie ersetzt.",
	["Nordic"] = "Nordisch",
	["Not available for %s yet"] = "Noch nicht für %s verfügbar",
