	["Quest item"] = "Questgegenstand",
	["Quest tracker"] = "Questverfolgung",
	["Quest when the unit is part of one of your quests (outside instances)."] = "Quest, wenn die Einheit Teil einer Eurer Quests ist (außerhalb von Instanzen).",
	["Quest, gossip and NPC dialogs"] = "Quest-, Gesprächs- und NPC-Dialoge",
