	["Race2"] = "Volk2",
	["Racial ability"] = "Volksfähigkeit",
	["Racial defensive"] = "Volksdefensive",
	["Rage"] = "Wut",
	["Rage ticks on the power bar, the Battle Shout reminder, and your key spells on the bar of each stance (Defensive Stance spells and Taunt for tanks). The class bar shows your buffs, key cooldowns and reagents"] = "Wut-Markierungen auf der Ressourcenleiste, die Erinnerung an Schlachtruf und Eure wichtigen Zauber auf der Leiste jeder Haltung (Zauber der Verteidigungshaltung und Spott für Tanks). Die Klassenleiste zeigt Eure Stärkungszauber, wichtigen Abklingzeiten und Reagenzien",
	["Rage ticks, the Battle Shout reminder and spells per stance"] = "Wut-Markierungen, Schlachtruf-Erinnerung und Zauber pro Haltung",
	["Raid"] = "Schlachtzug",
	["Raid Frames"] = "Schlachtzugsrahmen",
	["Raid cooldowns"] = "Schlachtzugsabklingzeiten",
