	["Ranged weapon DPS"] = "DPS der Distanzwaffe",
	["Rank Points"] = "Rangpunkte",
	["Rare Alerts adds a session history, sharing and quiet-zone controls for rare, treasure and event cards."] = "Rar-Alarme fügt einen Sitzungsverlauf, Teilen und Ruhezonen-Steuerung für Karten zu raren Gegnern, Schätzen und Ereignissen hinzu.",
	["Rare alerts"] = "Rar-Alarme",
	["Rare button on the layout's rare card"] = "Rar-Schaltfläche auf der Rar-Karte des Layouts",
	["Rare card"] = "Rar-Karte",
	["Rare popups on the layout's rare card"] = "Rar-Popups auf der Rar-Karte des Layouts",
	["Reach this step with Next first."] = "Erreicht diesen Schritt zuerst über „Weiter“.",
	["Reaction"] = "Reaktion",
	["Readable export"] = "Lesbarer Export",
	["Readable export: %s"] = "Lesbarer Export: %s",
	["Reading"] = "Lesen",
	["Ready"] = "Bereit",
	["Ready check"] = "Bereitschaftscheck",
	["Ready check, role poll, queue pop-ups and pings"] = "Bereitschaftscheck, Rollenabfrage, Warteschlangen-Popups und Pings",
	["Ready-made layouts that move every EldoUI frame into place."] = "Fertige Layouts, die jeden EldoUI-Rahmen an seinen Platz setzen.",
	["Ready-made looks for each part of the UI. Mix and match."] = "Fertige Optiken für jeden Teil der Oberfläche. Frei kombinierbar.",
	["Ready: it starts when you turn on the game's gamepad interface in the game's Controller settings."] = "Bereit: Es startet, wenn Ihr die Gamepad-Oberfläche des Spiels in dessen Controller-Einstellungen einschaltet.",
	["Really start %s fresh? It goes back to EldoUI's defaults for %s. A backup is kept, and the Welcome step can undo it on this character."] = "%s wirklich neu beginnen? Es kehrt zu EldoUIs Standardwerten für %s zurück. Eine Sicherung wird angelegt, und der Schritt „Willkommen“ kann es auf diesem Charakter rückgängig machen.",
	["Rebirth seeds"] = "Samen für Wiedergeburt",
