	["Show %s again. It is hidden until you turn this on."] = "%s wieder anzeigen. Es bleibt ausgeblendet, bis Ihr dies einschaltet.",
	["Show HUD key"] = "Taste zum Anzeigen des HUD",
	["Show a short note after an update"] = "Nach einem Update einen kurzen Hinweis zeigen",
	["Show all"] = "Alle anzeigen",
