	["Show boxes"] = "Felder anzeigen",
	["Show controller spells"] = "Controller-Zauber anzeigen",
	["Show every hidden box again."] = "Alle ausgeblendeten Felder wieder anzeigen.",
	["Show every key"] = "Alle Tasten anzeigen",
	["Show every setup page of your plugins and modules again. Nothing changes until you click Apply on a page."] = "Zeigt alle Einrichtungsseiten Eurer Plugins und Module erneut. Nichts ändert sich, bis Ihr auf einer Seite auf Übernehmen klickt.",
	["Show hidden"] = "Ausgeblendete zeigen",
	["Show me"] = "Zeigen",
	["Show mouse-over bars together"] = "Mouseover-Leisten gemeinsam einblenden",
	["Show only the frames whose name contains this text."] = "Nur Rahmen anzeigen, deren Name diesen Text enthält.",
	["Show or hide all map notes"] = "Alle Kartennotizen ein-/ausblenden",
	["Show or hide the damage meter"] = "Schadensmesser ein-/ausblenden",
	["Show or hide the journal tracker"] = "Tagebuchverfolgung ein-/ausblenden",
	["Show test frames"] = "Testrahmen anzeigen",
	["Show the HUD (hold)"] = "HUD anzeigen (halten)",
	["Show the area"] = "Bereich anzeigen",
	["Show the clock"] = "Uhr anzeigen",
	["Show the game keys"] = "Spieltasten anzeigen",
	["Show the keys on bars 1 to 3"] = "Tasten auf Leisten 1 bis 3 anzeigen",
	["Show the setup pages of %s again. Nothing changes until you click Apply on a page."] = "Zeigt die Einrichtungsseiten von %s erneut. Nichts ändert sich, bis Ihr auf einer Seite auf Übernehmen klickt.",
	["Show the update note"] = "Update-Hinweis anzeigen",
	["Show the welcome message at login"] = "Willkommensnachricht beim Einloggen zeigen",
	["Show this frame again."] = "Diesen Rahmen wieder anzeigen.",
	["Show this group."] = "Diese Gruppe anzeigen.",
	["Show tour helps again"] = "Tour-Hilfen wieder anzeigen",
	["Show zone name"] = "Gebietsnamen anzeigen",
	["Showing now: Apply or Finish keeps it"] = "Wird gerade angezeigt: Übernehmen oder Abschließen behält es",
	["Shown on every nameplate"] = "Auf allen Namensplaketten angezeigt",
	["Shown on the personal nameplate"] = "Auf der persönlichen Namensplakette angezeigt",
	["Shown only in this kind of group, whatever the rule says. A party is a group that is not a raid."] = "Nur in dieser Art von Gruppe angezeigt, egal was die Regel sagt. Als Gruppe zählt jede Gruppe, die kein Schlachtzug ist.",
	["Shown only while this talent group (dual specialization) is active."] = "Nur angezeigt, solange diese Talentgruppe (duale Talentspezialisierung) aktiv ist.",
	["Shown only while you have a focus target, or only while you have none."] = "Nur angezeigt, solange Ihr ein Fokusziel habt, oder nur, solange Ihr keins habt.",
	["Shows"] = "Zeigt",
	["Shows %s on screen. Right-clicking it and choosing Hide turns this off; the Hidden boxes page under Modules lists every hidden box."] = "Zeigt %s auf dem Bildschirm. Ein Rechtsklick darauf und „Ausblenden“ schaltet dies aus; die Seite „Ausgeblendete Felder“ unter Module listet alle ausgeblendeten Felder auf.",
	["Shows every glow below on a sample icon for a few seconds. Changes show at once."] = "Zeigt jedes Leuchten unten für ein paar Sekunden auf einem Beispielsymbol. Änderungen erscheinen sofort.",
	["Shows every key first; nothing changes until you press Apply there."] = "Zeigt zuerst alle Tasten; nichts ändert sich, bis Ihr dort auf Übernehmen drückt.",
	["Shows its box, selects it and flashes it."] = "Zeigt sein Feld, wählt es aus und lässt es aufblinken.",
	["Shows the %s box in move mode. Turned off, the box is gone from move mode and the addon's own window stays as that addon shows it; the Hidden boxes page under Modules lists every hidden box."] = "Zeigt das Feld von %s im Verschiebemodus. Ausgeschaltet verschwindet das Feld aus dem Verschiebemodus und das Fenster des Addons bleibt so, wie das Addon es anzeigt; die Seite „Ausgeblendete Felder“ unter Module listet alle ausgeblendeten Felder auf.",
	["Shows the errors EldoUI caught, with what happened."] = "Zeigt die Fehler, die EldoUI abgefangen hat, samt dem, was passiert ist.",
	["Shows the keys on bars 1 to 3 even when the action bar text style hides them. Off, those bars follow Action Bars > Show keybind like the others."] = "Zeigt die Tasten auf den Leisten 1 bis 3, auch wenn der Textstil der Aktionsleisten sie ausblendet. Aus: Diese Leisten folgen wie die anderen der Einstellung Aktionsleisten > Tastenbelegung anzeigen.",
	["Shows the outline of the area until you click again. Move mode (/eui move) shows it too."] = "Zeigt den Umriss des Bereichs, bis Ihr erneut klickt. Der Verschiebemodus (/eui move) zeigt ihn ebenfalls.",
	["Shows who interrupted a cast, like the game's own cast bar."] = "Zeigt, wer einen Zauber unterbrochen hat, wie die eigene Zauberleiste des Spiels.",
	["Shows your setup in full (version, layout, skin, role, UI amount, screen and text size, and which frames have no box right now) to copy into a bug report."] = "Zeigt Eure Einrichtung vollständig (Version, Layout, Skin, Rolle, UI-Umfang, Bildschirm- und Textgröße und welche Rahmen gerade kein Feld haben), um sie in einen Fehlerbericht zu kopieren.",
	["Side margin"] = "Seitenrand",
	["Side-button mouse"] = "Maus mit Seitentasten",
	["Silences every sound EldoUI plays through its media library. The game's own sounds are not affected."] = "Schaltet alle Sounds stumm, die EldoUI über seine Medienbibliothek abspielt. Die Sounds des Spiels sind nicht betroffen.",
	["Silencing emotes while resting"] = "Emotes beim Ausruhen stummschalten",
	["Sit or stand"] = "Hinsetzen/Aufstehen",
	["Size"] = "Größe",
	["Size of this window. The mouse wheel on its title bar changes it too."] = "Größe dieses Fensters. Das Mausrad auf der Titelleiste ändert sie ebenfalls.",
	["Size set by the %s role"] = "Größe durch die Rolle %s festgelegt",
	["Sizes and fonts"] = "Größen und Schriften",
