	["Skyriding bar"] = "Himmelsreiten-Leiste",
	["Small helps that explain something new once, the first time you meet it. Off: no tour help shows anywhere in EldoUI; /eui tour still shows one when you ask."] = "Kleine Hilfen, die etwas Neues einmal erklären, wenn Ihr zum ersten Mal darauf stoßt. Aus: Nirgends in EldoUI erscheint eine Tour-Hilfe; /eui tour zeigt trotzdem eine, wenn Ihr danach fragt.",
	["Smallest scale"] = "Kleinste Skalierung",
	["Smallest text on this screen: %.1f px. Large text at %d %% brings it to 9 px, without moving any frame."] = "Kleinster Text auf diesem Bildschirm: %.1f px. „Große Schrift“ bei %d %% bringt ihn auf 9 px, ohne einen Rahmen zu verschieben.",
	["Smooth bars"] = "Flüssige Leisten",
	["Snap"] = "Einrasten",
	["Snap frames"] = "Rahmen einrasten",
	["Snap to screen edges"] = "An Bildschirmrändern einrasten",
	["Social"] = "Soziales",
	["Social and group windows"] = "Kontakt- und Gruppenfenster",
	["Social window"] = "Kontaktfenster",
	["Soft"] = "Sanft",
	["Solid under the mouse"] = "Deckend unter der Maus",
	["Solo"] = "Solo",
	["Solo and leveling: low unit frames beside the top bar row, pet above the player, target of target above the target."] = "Solo und Leveln: tiefe Einheitenrahmen neben der oberen Leistenreihe, Begleiter über dem Spieler, Ziel des Ziels über dem Ziel.",
	["Some EldoUI settings could not be updated this time. They are kept as they were, and the update runs again at your next login."] = "Einige EldoUI-Einstellungen konnten diesmal nicht aktualisiert werden. Sie bleiben, wie sie waren, und die Aktualisierung läuft beim nächsten Einloggen erneut.",
	["Some addons ask once more in their own window before they import. A profile you made yourself can be saved with %s and is then used here."] = "Manche Addons fragen vor dem Import noch einmal in ihrem eigenen Fenster nach. Ein selbst erstelltes Profil lässt sich mit %s speichern und wird dann hier verwendet.",
	["Some changes (profile, Blizzard frames, modules) take full effect after a reload. Everything can be changed later in %s, and %s runs this setup again."] = "Manche Änderungen (Profil, Blizzard-Rahmen, Module) wirken erst nach einem Neuladen vollständig. Alles lässt sich später unter %s ändern, und %s startet diese Einrichtung erneut.",
	["Some changes take full effect after a reload."] = "Manche Änderungen wirken erst nach einem Neuladen vollständig.",
	["Some frames cover each other now:"] = "Einige Rahmen überdecken sich jetzt:",
	["Some keyboards have an accent key there that types nothing on its own. The key sets then leave that place without a key."] = "Manche Tastaturen haben dort eine Akzenttaste, die allein nichts tippt. Die Tastensätze lassen diesen Platz dann unbelegt.",
	["Someone whispers you."] = "Jemand flüstert Euch an.",
