	["Spell cues"] = "Zauberhinweise",
	["Spell cues flash the buttons of a spell the game lights up, with an optional sound."] = "Zauberhinweise lassen die Tasten eines Zaubers aufblinken, den das Spiel hervorhebt, auf Wunsch mit Sound.",
	["Spell lists for EldoUI's aura displays, for all your characters. A block list leaves spells out; an allow list shows only its spells."] = "Zauberlisten für EldoUIs Aurenanzeigen, für alle Eure Charaktere. Eine Sperrliste lässt Zauber weg; eine Erlaubnisliste zeigt nur ihre Zauber.",
	["Spell lists that decide which auras EldoUI shows, for all your characters."] = "Zauberlisten, die festlegen, welche Auren EldoUI zeigt, für alle Eure Charaktere.",
