	["Stronger colors for quick reading in busy fights."] = "Kräftigere Farben, die sich in hektischen Kämpfen schnell erfassen lassen.",
	["Structured"] = "Strukturiert",
	["Style"] = "Stil",
	["Style and color of every glow: procs, highlights, reminders."] = "Stil und Farbe jedes Leuchtens: Procs, Hervorhebungen, Erinnerungen.",
	["Style presets"] = "Stilvorlagen",
	["Styles"] = "Stile",
