	["Sunday"] = "Sonntag",
	["Support"] = "Unterstützung",
	["Supported addons can follow your layout's reserved spots, with per-addon opt-outs and Undo."] = "Unterstützte Addons können den reservierten Plätzen Eures Layouts folgen, mit Abwahl pro Addon und Rückgängig.",
	["Supported: the layouts keep their room and the text gets smaller."] = "Unterstützt: Die Layouts behalten ihren Platz, und der Text wird kleiner.",
	["Supporters"] = "Unterstützer",
	["Surname (first name if none)"] = "Nachname (sonst Vorname)",
	["Sust"] = "Erhalt",
	["Swing timer (main hand, off hand, ranged)"] = "Schlagtimer (Waffenhand, Schildhand, Distanz)",
	["Switch %s on or off."] = "%s ein- oder ausschalten.",
	["Switch back in each addon's profiles"] = "In den Profilen des jeweiligen Addons zurückschalten",
	["Switch every part of %s on or off. Blizzard's own version comes fully back after a reload."] = "Alle Teile von %s ein- oder ausschalten. Blizzards eigene Version kehrt nach einem Neuladen vollständig zurück.",
	["Switch profile by talent group or by kind of content. A content rule wins over a talent group rule. Switching waits until you leave combat."] = "Wechselt das Profil nach Talentgruppe oder Art des Inhalts. Eine Inhaltsregel hat Vorrang vor einer Talentgruppenregel. Der Wechsel wartet, bis Ihr den Kampf verlasst.",
	["Switch profiles automatically"] = "Profile automatisch wechseln",
	["Switch profiles automatically by talent group or content."] = "Profile automatisch nach Talentgruppe oder Inhalt wechseln.",
	["Switch the test restrictions on out of combat."] = "Schaltet die Testeinschränkungen außerhalb des Kampfes ein.",
	["Switch, create, copy or reset the profile this character uses."] = "Das Profil dieses Charakters wechseln, erstellen, kopieren oder zurücksetzen.",
	["Switched off: %s. Blizzard's own versions come fully back after a reload."] = "Ausgeschaltet: %s. Blizzards eigene Versionen kehren nach einem Neuladen vollständig zurück.",
	["Switches Edit Mode back to the layout you used before the game set it to Modern, out of combat."] = "Stellt den Bearbeitungsmodus außerhalb des Kampfes auf das Layout zurück, das Ihr verwendet habt, bevor das Spiel ihn auf Modern gesetzt hat.",
	["Switches Edit Mode back to the layout you used before, out of combat."] = "Stellt den Bearbeitungsmodus außerhalb des Kampfes auf das zuvor verwendete Layout zurück.",
	["Switches back what the last UI amount changed. A module you switched yourself since stays as you set it."] = "Macht rückgängig, was der letzte UI-Umfang geändert hat. Ein Modul, das Ihr seitdem selbst umgeschaltet habt, bleibt, wie Ihr es eingestellt habt.",
	["Switches off: %s."] = "Schaltet aus: %s.",
	["Switches on: %s."] = "Schaltet ein: %s.",
	["Switches the modules listed above. Your frames, skin, key bindings and other addons stay as they are."] = "Schaltet die oben aufgeführten Module um. Eure Rahmen, Euer Skin, Eure Tastenbelegungen und andere Addons bleiben, wie sie sind.",
	["Switching style presets keeps your layout tidy, and a damaged saved settings file no longer stops EldoUI from loading."] = "Beim Wechsel von Stilvorlagen bleibt Euer Layout aufgeräumt, und eine beschädigte Einstellungsdatei hindert EldoUI nicht mehr am Laden.",
	["Symbol of Divinity"] = "Symbol der Göttlichkeit",
	["Symbol of Kings"] = "Symbol der Könige",
	["System"] = "System",
	["System %s"] = "System %s",
	["System and settings windows"] = "System- und Einstellungsfenster",
	["Tabard designer"] = "Wappenrockgestaltung",
	["Tabs that already exist with these names are reused. You can rename, move or close them later from the tab's right-click menu, like any chat tab."] = "Bereits vorhandene Reiter mit diesen Namen werden wiederverwendet. Ihr könnt sie später über das Rechtsklickmenü des Reiters umbenennen, verschieben oder schließen, wie jeden Chatreiter.",
	["Take back spells"] = "Zauber zurücknehmen",
	["Take back your last change: a drag, a nudge, a typed position, an attach or a reset. Each click goes one step further back. Ctrl+Z does the same."] = "Eure letzte Änderung zurücknehmen: Ziehen, pixelweises Verschieben, eine eingetippte Position, ein Anheften oder ein Zurücksetzen. Jeder Klick geht einen Schritt weiter zurück. Strg+Z bewirkt dasselbe.",
	["Take the class spells this window placed off your bars again. A button you changed since keeps your action."] = "Nimmt die Klassenzauber, die dieses Fenster platziert hat, wieder von Euren Leisten. Eine Taste, die Ihr seitdem geändert habt, behält Eure Aktion.",
	["Taken from your execute spell."] = "Von Eurem Hinrichtungszauber übernommen.",
	["Takes an enemy out for a while: a stun, fear or polymorph."] = "Schaltet einen Gegner eine Weile aus: Betäubung, Furcht oder Verwandlung.",
	["Takes every spell off Never show and Watch list. Your own lists stay."] = "Entfernt alle Zauber aus „Nie anzeigen“ und „Beobachtungsliste“. Eure eigenen Listen bleiben.",
	["Takes full effect after a reload."] = "Wirkt erst nach einem Neuladen vollständig.",
	["Takes one harmful spell aimed at the group."] = "Fängt einen schädlichen Zauber ab, der auf die Gruppe zielt.",
	["Talent group"] = "Talentgruppe",
	["Talent group %d"] = "Talentgruppe %d",
	["Talent group 1 only"] = "Nur Talentgruppe 1",
	["Talent group 2 only"] = "Nur Talentgruppe 2",
	["Talent groups"] = "Talentgruppen",
	["Talent planner"] = "Talentplaner",
	["Talents"] = "Talente",
	["Talking head"] = "Sprechender Kopf",
	["Tank"] = "Tank",
	["Tank and DPS: your target's details on its nameplate, the player frame inside the center column."] = "Tank und DPS: die Details Eures Ziels auf seiner Namensplakette, der Spielerrahmen in der Mittelspalte.",
	["Tanking"] = "Tanken",
	["Tanks have Sunder Armor on Rotation 3 of Defensive Stance; your own pick."] = "Tanks haben Rüstung zerreißen auf Rotation 3 der Verteidigungshaltung; Eure eigene Wahl.",
	["Tanks only: a calm color (Colors page) for mobs another tank in your group holds. Only when the game shows that tank's threat."] = "Nur für Tanks: eine ruhige Farbe (Seite Farben) für Gegner, die ein anderer Tank Eurer Gruppe hält. Nur wenn das Spiel die Bedrohung dieses Tanks anzeigt.",
	["Tanks rarely fight in Berserker Stance; your own pick."] = "Tanks kämpfen selten in Berserkerhaltung; Eure eigene Wahl.",
	["Tapped by someone else"] = "Von jemand anderem beansprucht",
	["Target Frame"] = "Zielrahmen",
	["Target change flash"] = "Aufblitzen bei Zielwechsel",
	["Target nearest enemy"] = "Nächsten Feind anvisieren",
	["Target of Target Frame"] = "Ziel-des-Ziels-Rahmen",
	["Target, target-of-target and focus frames"] = "Ziel-, Ziel-des-Ziels- und Fokusrahmen",
	["Taunt is the tank's, on the Movement ability button of Defensive Stance; your own pick."] = "Spott gehört dem Tank, auf der Taste Bewegungsfähigkeit der Verteidigungshaltung; Eure eigene Wahl.",
	["Taxi map"] = "Flugkarte",
	["Tells guild and group members who run EldoUI your version in a hidden addon message, never in chat. One chat line when someone has a newer one. Never sent in combat, boss fights or PvP matches."] = "Teilt Gilden- und Gruppenmitgliedern, die EldoUI nutzen, Eure Version in einer versteckten Addon-Nachricht mit, nie im Chat. Eine Chatzeile, wenn jemand eine neuere hat. Wird nie im Kampf, in Bosskämpfen oder PvP-Partien gesendet.",
	["Ten built-in layouts with clearer names, and EldoUI Center as the new default for new profiles."] = "Zehn eingebaute Layouts mit klareren Namen und EldoUI Center als neuer Standard für neue Profile.",
	["Tenths below"] = "Zehntel unter",
	["Test frame"] = "Testrahmen",
	["Test switch %s is on"] = "Testschalter %s ist an",
	["Text"] = "Text",
	["Text after it colored by health: green full, yellow half, red low. Works best as the first tag."] = "Text danach nach Gesundheit gefärbt: grün voll, gelb halb, rot niedrig. Wirkt am besten als erster Tag.",
	["Text after it in gold for elites, silver for rares, red for bosses."] = "Text danach in Gold für Elite, Silber für rare Gegner, Rot für Bosse.",
	["Text after it in the color of the unit's power (mana blue, rage red ...)."] = "Text danach in der Farbe der Ressource der Einheit (Mana blau, Wut rot ...).",
	["Text after it in the level difficulty color (gray, green, yellow, orange, red)."] = "Text danach in der Farbe der Stufenschwierigkeit (grau, grün, gelb, orange, rot).",
	["Text after it in the player's class color."] = "Text danach in der Klassenfarbe des Spielers.",
	["Text after it in the reaction color: red hostile, yellow neutral, green friendly."] = "Text danach in der Reaktionsfarbe: rot feindselig, gelb neutral, grün freundlich.",
	["Text after it in your threat color on this unit: yellow, orange or red."] = "Text danach in Eurer Bedrohungsfarbe bei dieser Einheit: gelb, orange oder rot.",
	["Text in the world"] = "Text in der Spielwelt",
	["Text scale"] = "Textskalierung",
	["Text shadow"] = "Textschatten",
	["Text size"] = "Textgröße",
	["Text tags"] = "Text-Tags",
	["Text tags decide what a unit frame, group frame or nameplate text shows. Mix them with your own text: \"[name:short] [health:percent]\"."] = "Text-Tags legen fest, was ein Text auf Einheitenrahmen, Gruppenrahmen oder Namensplaketten zeigt. Mischt sie mit eigenem Text: „[name:short] [health:percent]“.",
	["Texts shown without a translation, one per line, ready for a translation file."] = "Ohne Übersetzung angezeigte Texte, einer pro Zeile, bereit für eine Übersetzungsdatei.",
	["Texture check"] = "Texturprüfung",
	["Texture check: %d found, %d missing. The full list is in the copy box."] = "Texturprüfung: %d gefunden, %d fehlen. Die vollständige Liste steht im Kopierfeld.",
	["Texture of every EldoUI bar that has no texture of its own. Follow skin uses your skin's bar texture. Textures from SharedMedia packs you have installed are listed under their addon."] = "Textur jeder EldoUI-Leiste ohne eigene Textur. „Skin folgen“ verwendet die Leistentextur Eures Skins. Texturen aus installierten SharedMedia-Paketen stehen unter ihrem Addon.",
	["Textures"] = "Texturen",
	["Thank you for standing behind EldoUI."] = "Danke, dass Ihr hinter EldoUI steht.",
	["Thank you for the code, research and testing that went into EldoUI."] = "Danke für den Code, die Recherche und die Tests, die in EldoUI eingeflossen sind.",
	["Thanks"] = "Danksagung",
	["That is not a filter list string."] = "Das ist kein Filterlisten-String.",
	["That is not a sound file ID or an addon .ogg/.mp3 path."] = "Das ist keine Sounddatei-ID und kein .ogg/.mp3-Pfad eines Addons.",
	["That is not an EldoUI filter list string."] = "Das ist kein EldoUI-Filterlisten-String.",
	["That is the profile you use now; pick another one to copy from."] = "Das ist Euer aktuelles Profil; wählt ein anderes, aus dem kopiert werden soll.",
	["That journal is gone."] = "Dieses Tagebuch gibt es nicht mehr.",
	["That page opens after combat."] = "Diese Seite öffnet sich nach dem Kampf.",
	["That value is no longer set aside."] = "Dieser Wert ist nicht mehr beiseitegelegt.",
	["The %s layout with the frames you dragged on profile %s, saved when it became a legacy layout."] = "Das Layout %s mit den Rahmen, die Ihr im Profil %s verschoben habt, gespeichert, als es zu einem veralteten Layout wurde.",
	["The %s setup is written to disk with the next reload."] = "Die Einrichtung von %s wird beim nächsten Neuladen gespeichert.",
	["The 1440p canvas the layouts are made for, on any screen. Follows your screen if it changes."] = "Die 1440p-Fläche, für die die Layouts gemacht sind, auf jedem Bildschirm. Passt sich an, wenn sich Euer Bildschirm ändert.",
	["The Alerts tab keeps its lines between sessions and follows your EldoUI language."] = "Der Chatreiter „Hinweise“ behält seine Zeilen zwischen Sitzungen und folgt Eurer EldoUI-Sprache.",
	["The Battleground Timers module shows its own battle start bar next to Blizzard's."] = "Das Modul Schlachtfeld-Timer zeigt neben Blizzards Leiste seine eigene Leiste für den Kampfbeginn.",
	["The Consumable Bar is off, so this key stays free."] = "Die Verbrauchsgüterleiste ist aus, daher bleibt diese Taste frei.",
	["The Edit Mode layout %s no longer exists, so Edit Mode stays on Modern."] = "Das Bearbeitungsmodus-Layout %s gibt es nicht mehr, daher bleibt der Bearbeitungsmodus auf Modern.",
	["The EldoUI font for every EldoUI text that has no font of its own. Languages these fonts lack keep the game font."] = "Die EldoUI-Schrift für jeden EldoUI-Text ohne eigene Schrift. Sprachen, die diese Schriften nicht abdecken, behalten die Spielschrift.",
	["The EldoUI font, text size, outline and shadow, number styles and the fonts of each module."] = "Die EldoUI-Schrift, Textgröße, Kontur und Schatten, Zahlenformate und die Schriften der einzelnen Module.",
	["The EldoUI profile"] = "Das EldoUI-Profil",
	["The Forever surname, empty when the character has none (or it is your own and the game hides it)."] = "Der Forever-Nachname, leer, wenn der Charakter keinen hat (oder wenn es Euer eigener ist und das Spiel ihn ausblendet).",
	["The HUD fades while nothing happens and comes back when you act. This page sets every module's Visibility at once."] = "Das HUD blendet aus, solange nichts passiert, und kehrt zurück, sobald Ihr handelt. Diese Seite stellt die Sichtbarkeit aller Module auf einmal ein.",
	["The Info Bar adds session gold and XP rates, a group roll tracker and mail information across your characters."] = "Die Infoleiste bietet Gold- und EP-Raten der Sitzung, eine Übersicht der Gruppenwürfe und Postinfos über alle Eure Charaktere.",
	["The Journal can group a boss's loot by kind and shows a branching dungeon quest chain as a flowchart."] = "Das Tagebuch kann die Beute eines Bosses nach Art gruppieren und zeigt eine verzweigte Dungeon-Questreihe als Flussdiagramm.",
	["The Loot Guide isn't installed."] = "Der Loot Guide ist nicht installiert.",
	["The Talent Planner with Import build, Training, and lower spell ranks lit on your bars."] = "Der Talentplaner mit Build-Import, Training und hervorgehobenen niedrigeren Zauberrängen auf Euren Leisten.",
	["The Tour helps switch and the tour helps already shown."] = "Der Schalter für Tour-Hilfen und die bereits gezeigten Tour-Hilfen.",
	["The UI scale choice shows which scales the layouts are made for, with Auto recommended."] = "Die Auswahl der UI-Skalierung zeigt, für welche Skalierungen die Layouts gemacht sind, mit Auto als Empfehlung.",
	["The accent when Accent color is set to Custom color."] = "Die Akzentfarbe, wenn „Akzentfarbe“ auf „Eigene Farbe“ steht.",
	["The addon that owns the window places it."] = "Das Addon, dem das Fenster gehört, platziert es.",
	["The addons the setup turned off are turned on again: %s."] = "Die Addons, die die Einrichtung ausgeschaltet hat, werden wieder eingeschaltet: %s.",
	["The bar page keys (%s) are taken off, so bar 1 never swaps its spells in a fight."] = "Die Tasten zum Leistenblättern (%s) werden entfernt, damit Leiste 1 im Kampf nie ihre Zauber tauscht.",
	["The bar shows all the time. Action Bars > Visibility changes it again."] = "Die Leiste wird ständig angezeigt. Aktionsleisten > Sichtbarkeit ändert das wieder.",
	["The bar stays out of sight, also when you point at it. Its keys still work. Action Bars brings it back."] = "Die Leiste bleibt unsichtbar, auch wenn Ihr darauf zeigt. Ihre Tasten funktionieren weiterhin. Unter Aktionsleisten holt Ihr sie zurück.",
	["The bar texture, smooth bars and the textures of each module."] = "Die Leistentextur, flüssige Leisten und die Texturen der einzelnen Module.",
	["The big defensive or emergency button."] = "Die große Verteidigungs- oder Notfalltaste.",
	["The character's realm when it differs from yours."] = "Der Realm des Charakters, wenn er sich von Eurem unterscheidet.",
	["The class of a player; empty for NPCs."] = "Die Klasse eines Spielers; leer bei NPCs.",
	["The classic look tidied up: satin graphite, a fine bronze double edge and softened corners, with thin portrait rings. Brings the Sand accent while yours is the default blue."] = "Die klassische Optik, aufgeräumt: seidenmattes Graphit, ein feiner bronzener Doppelrand und weichere Ecken, mit dünnen Porträtringen. Bringt den Akzent Sand mit, solange Eurer das Standardblau ist.",
	["The copies needed for this restore exceed the backup size limit. Nothing changed."] = "Die für diese Wiederherstellung nötigen Kopien überschreiten die Größengrenze für Sicherungen. Nichts wurde geändert.",
	["The copy is merged into your journal. Your journal as it was a moment ago is kept as a backup in My Adventure."] = "Die Kopie ist mit Eurem Tagebuch zusammengeführt. Euer Tagebuch, wie es eben noch war, wird als Sicherung in Mein Abenteuer aufbewahrt.",
	["The data bars go to it."] = "Die Datenleisten landen dort.",
	["The dungeon map shows the game's minimap large in Live, and WoW: Forever's own dungeons open it with their boss list."] = "Die Dungeonkarte zeigt in Live die Minikarte des Spiels groß, und die eigenen Dungeons von WoW: Forever öffnen sie mit ihrer Bossliste.",
	["The error log (/eui errors) with a Report button that leaves out your character's name, realm, guild and chat text."] = "Das Fehlerprotokoll (/eui errors) mit einer Schaltfläche „Melden“, die Namen, Realm, Gilde und Chattext Eures Charakters weglässt.",
	["The error log: what went wrong in EldoUI, with a copy button for a report."] = "Das Fehlerprotokoll: was in EldoUI schiefgelaufen ist, mit einer Kopierschaltfläche für einen Bericht.",
	["The familiar original layout: portraits in the corners, a round minimap, one bar row along the bottom and Blizzard's own windows."] = "Das vertraute Originallayout: Porträts in den Ecken, eine runde Minikarte, eine Leistenreihe am unteren Rand und Blizzards eigene Fenster.",
	["The familiar original layout: portraits in the top left corner, a round minimap top right, the action bars along the bottom with the chat beside them, and the world kept clear."] = "Das vertraute Originallayout: Porträts oben links, eine runde Minikarte oben rechts, die Aktionsleisten am unteren Rand mit dem Chat daneben, und die Spielwelt bleibt frei.",
	["The figure only repeats the game's repair alert, so a replacement would add nothing."] = "Die Figur wiederholt nur den Reparaturhinweis des Spiels, ein Ersatz brächte also nichts.",
	["The food types your hunter pet eats."] = "Die Futterarten, die Euer Tier frisst.",
	["The frame art around player, target, pet and the other unit frames: portrait ring or box, bar frame and fill. It never changes positions, sizes, bars or what the portrait shows."] = "Die Rahmengrafik um Spieler, Ziel, Begleiter und die anderen Einheitenrahmen: Porträtring oder -kasten, Leistenrahmen und Füllung. Sie ändert nie Positionen, Größen, Leisten oder was das Porträt zeigt.",
	["The frame art of party and raid frames: the skin's material and a fine edge. They stay compact, so a full raid keeps its room."] = "Die Rahmengrafik der Gruppen- und Schlachtzugsrahmen: das Material des Skins und ein feiner Rand. Sie bleiben kompakt, damit ein voller Schlachtzug seinen Platz behält.",
	["The frame drawn around EldoUI's action buttons. The buttons, their keys and what they cast never change."] = "Der Rahmen um EldoUIs Aktionstasten. Die Tasten, ihre Tastenbelegungen und was sie wirken, ändern sich nie.",
	["The frame fades in when it appears, for example a new target, focus or boss. Follows General > Animations."] = "Der Rahmen blendet sich ein, wenn er erscheint, etwa bei einem neuen Ziel, Fokus oder Boss. Folgt Allgemein > Animationen.",
	["The frame of this options window. Follow skin frames it like every other EldoUI window."] = "Der Rahmen dieses Optionsfensters. „Skin folgen“ rahmt es wie jedes andere EldoUI-Fenster.",
	["The frame takes the color."] = "Der Rahmen nimmt die Farbe an.",
	["The full list is in chat."] = "Die vollständige Liste steht im Chat.",
	["The game did not have the memory to load EldoUI's saved settings, so this session uses the defaults and the setup stays closed. Turn off some other addons, then reload."] = "Dem Spiel fehlte der Speicher, um EldoUIs gespeicherte Einstellungen zu laden, daher nutzt diese Sitzung die Standardwerte und die Einrichtung bleibt geschlossen. Schaltet einige andere Addons aus und ladet dann neu.",
	["The game doesn't allow chat messages right now."] = "Das Spiel lässt gerade keine Chatnachrichten zu.",
	["The game has not sent your PvP rank yet."] = "Das Spiel hat Euren PvP-Rang noch nicht gesendet.",
	["The game keeps these four buttons for its own actions."] = "Das Spiel behält diese vier Tasten für eigene Aktionen.",
	["The game set Edit Mode to Modern when its gamepad interface turned off. Restore now switches back to %s."] = "Das Spiel hat den Bearbeitungsmodus auf Modern gesetzt, als seine Gamepad-Oberfläche ausgeschaltet wurde. „Jetzt wiederherstellen“ wechselt zurück zu %s.",
	["The game's controller bars aren't available right now."] = "Die Controller-Leisten des Spiels sind gerade nicht verfügbar.",
	["The game's controller bars: your class spells in the same order, for play with a controller."] = "Die Controller-Leisten des Spiels: Eure Klassenzauber in derselben Reihenfolge, zum Spielen mit Controller.",
	["The game's gamepad interface is off. You can turn it on in the game's Controller settings."] = "Die Gamepad-Oberfläche des Spiels ist aus. Ihr könnt sie in den Controller-Einstellungen des Spiels einschalten.",
	["The game's own Lua error window, which pops up on every error until you close it. Hide keeps it closed; EldoUI still logs every error in /eui errors. Don't touch leaves the game's setting as it is."] = "Das eigene Lua-Fehlerfenster des Spiels, das bei jedem Fehler aufspringt, bis Ihr es schließt. „Ausblenden“ hält es geschlossen; EldoUI protokolliert trotzdem jeden Fehler in /eui errors. „Nicht anfassen“ lässt die Spieleinstellung, wie sie ist.",
	["The game's own buttons"] = "Tasten des Spiels",
	["The game's own classic frames round the bars: portrait circle, name area and the elite dragon. Made for the Classic frames style (thin bars at the classic proportions beside a portrait box as wide as the plate's portrait side); other frames, and party and raid frames, get the Vanilla look."] = "Die klassischen Rahmen des Spiels um die Leisten: Porträtkreis, Namensfeld und der Elitedrache. Gemacht für den Stil „Klassische Rahmen“ (dünne Leisten in den klassischen Proportionen neben einem Porträtkasten, so breit wie die Porträtseite der Platte); andere Rahmen sowie Gruppen- und Schlachtzugsrahmen erhalten die Vanilla-Optik.",
	["The game's own health, power and experience bars show the value and the percent."] = "Die Gesundheits-, Ressourcen- und Erfahrungsleisten des Spiels zeigen Wert und Prozent.",
	["The game's own original frames: the classic player and target plates with the elite dragon (with the Classic frames unit style), the gryphon-capped action bar and the round minimap border. Windows get carved gray stone, a warm brass double line and stone clasps on their corners. Brings the Gold accent while yours is the default blue."] = "Die Originalrahmen des Spiels: die klassischen Spieler- und Zielplatten mit dem Elitedrachen (mit dem Einheitenstil „Klassische Rahmen“), die von Greifen gekrönte Aktionsleiste und der runde Minikartenrand. Fenster erhalten gemeißelten grauen Stein, eine warme Doppellinie aus Messing und steinerne Spangen an den Ecken. Bringt den Akzent Gold mit, solange Eurer das Standardblau ist.",
	["The game's proc art on buttons, pixel lines everywhere else. Gold for procs."] = "Die Proc-Grafik des Spiels auf Tasten, sonst überall Pixellinien. Gold für Procs.",
	["The game's style for your language"] = "Stil des Spiels für Eure Sprache",
	["The game's tutorial hints stay away. Turn them back on in the game's Interface settings."] = "Die Tutorial-Hinweise des Spiels bleiben weg. In den Interface-Einstellungen des Spiels schaltet Ihr sie wieder ein.",
	["The gamepad UI is on, so the key sets stand down: your controller keeps its own buttons."] = "Die Gamepad-Oberfläche ist an, daher halten sich die Tastensätze zurück: Euer Controller behält seine eigenen Tasten.",
	["The glow also pulses slowly. Static with animations off."] = "Das Leuchten pulsiert zusätzlich langsam. Statisch bei ausgeschalteten Animationen.",
	["The glow of the execute shade on the Effects page (Glow style)."] = "Das Leuchten der Schattierung im Hinrichtungsbereich auf der Seite Effekte (Stil Leuchten).",
	["The glow of the low health warning on the Effects page (Glow style)."] = "Das Leuchten der Warnung bei wenig Gesundheit auf der Seite Effekte (Stil Leuchten).",
	["The grid frames snap to, in steps of 4 from 4 to 128. Press Enter to apply."] = "Das Raster, an dem Rahmen einrasten, in Schritten von 4 von 4 bis 128. Drückt die Eingabetaste zum Übernehmen.",
	["The highest rank of the season."] = "Der höchste Rang der Saison.",
	["The icon breathes and the time turns red."] = "Das Symbol atmet, und die Zeit wird rot.",
	["The icon breathes."] = "Das Symbol atmet.",
	["The journal kept under %s is removed. It leaves your saved file at your next logout or /reload."] = "Das unter %s aufbewahrte Tagebuch ist entfernt. Beim nächsten Ausloggen oder /reload verschwindet es aus Eurer gespeicherten Datei.",
	["The journal of %s is back. It is on disk after your next logout or /reload."] = "Das Tagebuch von %s ist zurück. Nach dem nächsten Ausloggen oder /reload ist es gespeichert.",
	["The journal of %s is removed. It leaves your saved file at your next logout or /reload."] = "Das Tagebuch von %s ist entfernt. Beim nächsten Ausloggen oder /reload verschwindet es aus Eurer gespeicherten Datei.",
	["The key sets use the keys in the same places on every keyboard. Pick yours, or let EldoUI guess from the game language."] = "Die Tastensätze verwenden auf jeder Tastatur die Tasten an denselben Stellen. Wählt Eure aus oder lasst EldoUI sie anhand der Spielsprache erraten.",
	["The keys with Alt held: where the game shortcuts a set takes go."] = "Die Tasten mit gedrückter Alt-Taste: Hier landen die Spielkürzel, die ein Satz übernimmt.",
	["The keys with Ctrl held."] = "Die Tasten mit gedrückter Strg-Taste.",
	["The keys with Shift held."] = "Die Tasten mit gedrückter Umschalttaste.",
	["The keys without a modifier."] = "Die Tasten ohne Zusatztaste.",
	["The layout placed %s on its %s spot. Undo leaves it where the addon puts it."] = "Das Layout hat %s auf seinen Platz (%s) gesetzt. Rückgängig lässt es dort, wo das Addon es hinsetzt.",
	["The layout spots for other addons are off."] = "Die Layoutplätze für andere Addons sind aus.",
	["The layout that places your frames: applied as when you pick it on the Layouts page, with its frame sizes."] = "Das Layout, das Eure Rahmen platziert: angewendet wie bei der Wahl auf der Seite „Layouts“, mit seinen Rahmengrößen.",
	["The list in that string has no usable name."] = "Die Liste in diesem String hat keinen brauchbaren Namen.",
	["The list the rows below edit."] = "Die Liste, die die Zeilen darunter bearbeiten.",
	["The look from the Glows page (Danger: execute range)."] = "Die Optik von der Seite „Leuchteffekte“ (Gefahr: Hinrichtungsbereich).",
	["The look from the Glows page (Danger: low health)."] = "Die Optik von der Seite „Leuchteffekte“ (Gefahr: niedrige Gesundheit).",
	["The lower range comes from your own spell: 20 % with Execute or Hammer of Wrath. Without such a spell, no shade shows."] = "Der untere Bereich kommt von Eurem eigenen Zauber: 20 % mit Hinrichten oder Hammer des Zorns. Ohne einen solchen Zauber erscheint keine Schattierung.",
	["The materials of a skin that comes in a look per faction. Auto follows your character's faction."] = "Die Materialien eines Skins mit eigener Optik pro Fraktion. Auto folgt der Fraktion Eures Charakters.",
	["The memory EldoUI uses right now. It is measured when this window opens and each time you point at this line."] = "Der Speicher, den EldoUI gerade belegt. Er wird gemessen, wenn sich dieses Fenster öffnet, und jedes Mal, wenn Ihr auf diese Zeile zeigt.",
	["The mouse wheel stops at this size."] = "Das Mausrad stoppt bei dieser Größe.",
	["The one switch for every window below. Off: EldoUI leaves every Blizzard window where Blizzard places it, at its own size. Your ticks stay for when you turn it on again."] = "Der eine Schalter für alle Fenster darunter. Aus: EldoUI lässt jedes Blizzard-Fenster dort, wo Blizzard es platziert, in seiner eigenen Größe. Eure Häkchen bleiben erhalten, bis Ihr ihn wieder einschaltet.",
	["The options open after combat."] = "Die Optionen öffnen sich nach dem Kampf.",
	["The original corners in less space: a smaller minimap and chat, smaller bar buttons and no side bars, made for 1080p screens."] = "Die Originalecken auf weniger Raum: kleinere Minikarte und kleinerer Chat, kleinere Leistentasten und keine Seitenleisten, gemacht für 1080p-Bildschirme.",
	["The pack is empty."] = "Das Paket ist leer.",
	["The party as one row and a raid of up to ten as two rows, under the center column above your bars. A larger raid moves beside the center."] = "Die Gruppe als eine Reihe und ein Schlachtzug mit bis zu zehn Spielern als zwei Reihen, unter der Mittelspalte über Euren Leisten. Ein größerer Schlachtzug rückt neben die Mitte.",
	["The people who made EldoUI possible."] = "Die Menschen, die EldoUI möglich gemacht haben.",
	["The pet bar moves from Ctrl + the number row to Alt + the number row."] = "Die Begleiterleiste wechselt von Strg + Zahlenreihe zu Alt + Zahlenreihe.",
	["The place this value came from holds something else now. Nothing was changed."] = "An der Stelle, von der dieser Wert stammt, steht jetzt etwas anderes. Nichts wurde geändert.",
	["The plain dark panels."] = "Die schlichten dunklen Panels.",
	["The point of the screen %s is measured from."] = "Der Punkt des Bildschirms, von dem aus %s gemessen wird.",
	["The power bar turns the low power color (Colors page) when it drops below the value you set. Handy for keeping an eye on a healer's mana."] = "Die Ressourcenleiste nimmt die Farbe für wenig Ressource an (Seite Farben), wenn sie unter den eingestellten Wert fällt. Praktisch, um das Mana eines Heilers im Blick zu behalten.",
	["The preview changes the UI at once. Back or closing this window puts your old scale back. You can change it later in /eui > General or with /eui scale."] = "Die Vorschau ändert die UI sofort. Zurück oder das Schließen dieses Fensters stellt Eure alte Skalierung wieder her. Ihr könnt sie später unter /eui > Allgemein oder mit /eui scale ändern.",
	["The profile %s exists. %s Starting it fresh resets its layout, styles and settings for every character that uses it."] = "Das Profil %s existiert bereits. %s Ein Neubeginn setzt Layout, Stile und Einstellungen für jeden Charakter zurück, der es nutzt.",
	["The profile %s was deleted."] = "Das Profil %s wurde gelöscht.",
	["The profile a new character of each class starts with on its first login with EldoUI. Characters that already have a profile keep it."] = "Das Profil, mit dem ein neuer Charakter jeder Klasse beim ersten Einloggen mit EldoUI beginnt. Charaktere, die schon ein Profil haben, behalten es.",
	["The profile changes after combat."] = "Das Profil wechselt nach dem Kampf.",
	["The profile this character uses. Every character can use any profile."] = "Das Profil dieses Charakters. Jeder Charakter kann jedes Profil nutzen.",
	["The profile you last picked"] = "Das zuletzt gewählte Profil",
	["The quest icon pops in when a unit becomes part of one of your quests."] = "Das Questsymbol springt auf, wenn eine Einheit Teil einer Eurer Quests wird.",
	["The quest log is part of the world map, so hiding it on its own makes no sense."] = "Das Questlog ist Teil der Weltkarte, es allein auszublenden ergibt daher keinen Sinn.",
	["The range is tinted."] = "Der Bereich wird getönt.",
	["The red time text starts at this many seconds left."] = "Der rote Zeittext beginnt bei so vielen verbleibenden Sekunden.",
	["The ring or border around the minimap. A minimap without a border keeps none."] = "Der Ring oder Rand um die Minikarte. Eine Minikarte ohne Rand bleibt ohne.",
	["The role layer in use. No role leaves the layout as it is. Switching role puts back what the previous role changed, unless you changed it yourself since."] = "Die verwendete Rollenebene. Keine Rolle lässt das Layout, wie es ist. Ein Rollenwechsel stellt zurück, was die vorige Rolle geändert hat, es sei denn, Ihr habt es seitdem selbst geändert.",
	["The role picked in the group: Tank, Healer or Damage."] = "Die in der Gruppe gewählte Rolle: Tank, Heiler oder Schaden.",
	["The safe area is off, or this screen is not wider than it."] = "Der sichere Bereich ist aus, oder dieser Bildschirm ist nicht breiter als er.",
	["The settings from %s stopped arriving and were dropped."] = "Die Einstellungen von %s kamen nicht mehr an und wurden verworfen.",
	["The setup again: scale, layout, look, role and chat. It asks before it changes anything."] = "Die Einrichtung noch einmal: Skalierung, Layout, Optik, Rolle und Chat. Sie fragt, bevor sie etwas ändert.",
	["The setup change waits for the end of combat."] = "Die Einrichtungsänderung wartet bis zum Ende des Kampfes.",
	["The setup is done. Closes this page and asks for a reload only if a change needs one."] = "Die Einrichtung ist abgeschlossen. Schließt diese Seite und fragt nur dann nach einem Neuladen, wenn eine Änderung es braucht.",
	["The setup opens after combat."] = "Die Einrichtung öffnet sich nach dem Kampf.",
	["The setup opens again after the reset."] = "Die Einrichtung öffnet sich nach dem Zurücksetzen erneut.",
	["The setup's Role step lists them for your class."] = "Der Einrichtungsschritt „Rolle“ listet sie für Eure Klasse auf.",
	["The shade starts once health is under this percent."] = "Die Schattierung beginnt, sobald die Gesundheit unter diesem Prozentwert liegt.",
	["The shop and secure transfers are protected, so they stay Blizzard's."] = "Der Shop und sichere Übertragungen sind geschützt und bleiben daher bei Blizzard.",
	["The shown entry as a bug report to copy, with a link to the bug form. Nothing is sent by itself."] = "Der angezeigte Eintrag als Fehlerbericht zum Kopieren, mit einem Link zum Fehlerformular. Nichts wird von selbst gesendet.",
	["The side buttons hold bar 1 and Shift + the side buttons bar 2. Bar 3 sits on the keys around your movement hand."] = "Die Seitentasten tragen Leiste 1 und Umschalt + Seitentasten Leiste 2. Leiste 3 liegt auf den Tasten rund um Eure Bewegungshand.",
	["The skin of your whole UI and of each part. A skin never moves frames or turns modules on or off."] = "Der Skin Eurer gesamten UI und jedes Teils. Ein Skin verschiebt nie Rahmen und schaltet nie Module ein oder aus.",
	["The skin's material behind the bars, its border round the frame and a round portrait ring."] = "Das Material des Skins hinter den Leisten, sein Rand um den Rahmen und ein runder Porträtring.",
	["The sound to play. General > Sounds has the volume channel."] = "Der abzuspielende Sound. Allgemein > Sounds enthält den Lautstärkekanal.",
	["The status icon breathes while a resurrection or summon is on its way."] = "Das Statussymbol atmet, solange eine Wiederbelebung oder Beschwörung unterwegs ist.",
	["The string is too long."] = "Der String ist zu lang.",
	["The threat glow on unit frames and nameplates (Effects, Threat border with the Glow style). The game's threat state turns it on."] = "Das Bedrohungsleuchten auf Einheitenrahmen und Namensplaketten (Effekte, Bedrohungsrand mit dem Stil Leuchten). Der Bedrohungszustand des Spiels schaltet es ein.",
	["The time turns red."] = "Die Zeit wird rot.",
	["The tint shows while power is under this percent."] = "Die Tönung erscheint, solange die Ressource unter diesem Prozentwert liegt.",
	["The title bar"] = "Titelleiste",
	["The totem bar with a loadout for your role, the cooldown bar, shield and imbue reminders, totem squares on party frames for healers, and an Ankh counter and restock"] = "Die Totemleiste mit einer Zusammenstellung für Eure Rolle, die Abklingzeitleiste, Erinnerungen an Schild und Waffenverzauberung, Totemquadrate auf Gruppenrahmen für Heiler sowie ein Ankh-Zähler mit Nachkauf",
	["The undo runs when combat ends."] = "Das Rückgängigmachen erfolgt, sobald der Kampf endet.",
	["The unit's absorb shield over the health bar. Color on the Colors page."] = "Der Absorptionsschild der Einheit über der Gesundheitsleiste. Farbe auf der Seite Farben.",
	["The unit's level; ?? when the game hides it."] = "Die Stufe der Einheit; ??, wenn das Spiel sie verbirgt.",
	["The unit's name in the Name format (General page, or this module's own choice there). [name:short] / [name:medium] / [name:long] cut it to 10 / 15 / 20 letters, [name:N] to N letters (counted after the format; accents and other alphabets are kept whole), [name:abbrev] shortens all but the last word (\"C. K. Seaclaw\")."] = "Der Name der Einheit im Namensformat (Seite Allgemein oder die eigene Wahl dieses Moduls dort). [name:short] / [name:medium] / [name:long] kürzen ihn auf 10 / 15 / 20 Buchstaben, [name:N] auf N Buchstaben (gezählt nach dem Format; Akzente und andere Alphabete bleiben ganz), [name:abbrev] kürzt alle Wörter bis auf das letzte („C. K. Seaclaw“).",
	["The unit's raid group number (1-8); empty outside raids."] = "Die Schlachtzugsgruppennummer der Einheit (1-8); außerhalb von Schlachtzügen leer.",
	["The versions from 0.5.0 to 0.6.6005 in short: what they brought that is still in EldoUI."] = "Die Versionen 0.5.0 bis 0.6.6005 in Kürze: was sie gebracht haben und noch in EldoUI steckt.",
	["The warning pulses slowly. Static with animations off."] = "Die Warnung pulsiert langsam. Statisch bei ausgeschalteten Animationen.",
	["The warning shows while the unit's health is under this percent."] = "Die Warnung erscheint, solange die Gesundheit der Einheit unter diesem Prozentwert liegt.",
	["The whole module"] = "Das ganze Modul",
	["The whole profile as a readable Lua table, for bug reports and comparing setups."] = "Das ganze Profil als lesbare Lua-Tabelle, für Fehlerberichte und zum Vergleichen von Einrichtungen.",
	["The whole profile as one string."] = "Das ganze Profil als ein String.",
	["The whole profile or one part of it."] = "Das ganze Profil oder ein Teil davon.",
	["Theme font"] = "Themenschrift",
	["Theme font, number format, the game's own fonts and every module's font in one place."] = "Themenschrift, Zahlenformat, die Schriften des Spiels und die Schrift jedes Moduls an einem Ort.",
	["There are no new spells to take off your bars."] = "Es gibt keine neuen Zauber, die von Euren Leisten genommen werden könnten.",
	["There are no spells from the last fill to take off."] = "Es gibt keine Zauber aus der letzten Befüllung, die entfernt werden könnten.",
	["There is no keybind backup for this character."] = "Für diesen Charakter gibt es keine Sicherung der Tastenbelegung.",
	["There is no profile %q. /eui profile list shows them."] = "Es gibt kein Profil %q. /eui profile list zeigt sie an.",
	["There is no setup change to undo on this profile."] = "In diesem Profil gibt es keine Einrichtungsänderung zum Rückgängigmachen.",
	["There is no setup to undo on this character."] = "Bei diesem Charakter gibt es keine Einrichtung zum Rückgängigmachen.",
	["There is nothing to check yet: choose a key set first."] = "Noch gibt es nichts zu prüfen: Wählt zuerst einen Tastensatz.",
	["There is nothing to put back on this character."] = "Bei diesem Charakter gibt es nichts zurückzustellen.",
	["These addons run next to EldoUI without drawing the same thing twice, so nothing stands back. EldoUI does their job too, in full or in part."] = "Diese Addons laufen neben EldoUI, ohne dasselbe doppelt zu zeichnen, daher tritt nichts zurück. EldoUI erledigt ihre Aufgabe ebenfalls, ganz oder teilweise.",
	["These are developer tools you open on purpose."] = "Das sind Entwicklerwerkzeuge, die Ihr bewusst öffnet.",
	["These are settings from the game's own options window (Esc > Options). They only change how things look or read: nothing here plays for you.\n\nA setting the game already uses shows as set and is not written again. EldoUI remembers your value before it changes one, so Blizzard default in /eui puts it back.\n\nA second run starts with nothing checked, so clicking through changes nothing."] = "Das sind Einstellungen aus dem Optionsfenster des Spiels (Esc > Optionen). Sie ändern nur, wie etwas aussieht oder sich liest: Nichts hier spielt für Euch.\n\nEine Einstellung, die das Spiel bereits nutzt, erscheint als gesetzt und wird nicht erneut geschrieben. EldoUI merkt sich Euren Wert, bevor es einen ändert, sodass „Blizzard-Standard“ in /eui ihn zurückholt.\n\nEin zweiter Durchlauf beginnt ohne Häkchen, sodass Durchklicken nichts ändert.",
	["Thick"] = "Dick",
	["Thickness"] = "Dicke",
	["Thin"] = "Dünn",
	["Thin lines that run round the frame in the accent color."] = "Dünne Linien in der Akzentfarbe, die um den Rahmen laufen.",
	["This EldoUI (%s) is older than the plugin needs. Update EldoUI."] = "Dieses EldoUI (%s) ist älter, als das Plugin es braucht. Aktualisiert EldoUI.",
	["This can't be undone."] = "Das lässt sich nicht rückgängig machen.",
	["This character"] = "Dieser Charakter",
	["This character gets"] = "Dieser Charakter erhält",
	["This character goes back to profile %s, as before the alt setup of %s, and its chat tabs, game settings, click-casting and class spells go back too. Profile %s stays as it is, and other addons' profiles stay as they are."] = "Dieser Charakter kehrt zu Profil %s zurück, wie vor der Twink-Einrichtung vom %s, und auch seine Chatreiter, Spieleinstellungen, Klickzauber und Klassenzauber werden zurückgesetzt. Profil %s bleibt, wie es ist, und die Profile anderer Addons bleiben unverändert.",
	["This character goes back to profile %s, as before the alt setup of %s, and its chat tabs, game settings, click-casting and class spells go back too. The copy %s made for it is deleted, and other addons' profiles stay as they are."] = "Dieser Charakter kehrt zu Profil %s zurück, wie vor der Twink-Einrichtung vom %s, und auch seine Chatreiter, Spieleinstellungen, Klickzauber und Klassenzauber werden zurückgesetzt. Die für ihn angelegte Kopie %s wird gelöscht, und die Profile anderer Addons bleiben unverändert.",
	["This character uses %s with its %s role layer, like the other characters on it."] = "Dieser Charakter nutzt %s mit der Rollenebene %s, wie die anderen Charaktere darauf.",
	["This character uses profile %s again, as before the alt setup. Reload to finish?"] = "Dieser Charakter nutzt wieder Profil %s, wie vor der Twink-Einrichtung. Zum Abschließen neu laden?",
	["This character uses profile %s now."] = "Dieser Charakter nutzt jetzt Profil %s.",
	["This character's EldoUI data is saved under %s. Bring over its settings, profile, Journal, bags and history from there? What EldoUI saved here since the move is replaced. The change shows after a reload."] = "Die EldoUI-Daten dieses Charakters sind unter %s gespeichert. Seine Einstellungen, sein Profil, Tagebuch, seine Taschen und seinen Verlauf von dort übernehmen? Was EldoUI hier seit dem Umzug gespeichert hat, wird ersetzt. Die Änderung zeigt sich nach einem Neuladen.",
	["This character's keys match your key set."] = "Die Tasten dieses Charakters entsprechen Eurem Tastensatz.",
	["This character's own chat windows: the tabs are made and filled the way the setup's Chat step does it."] = "Die eigenen Chatfenster dieses Charakters: Die Reiter werden so angelegt und gefüllt wie im Einrichtungsschritt „Chat“.",
	["This client has no test switch for combat restrictions."] = "Dieser Client hat keinen Testschalter für Kampfeinschränkungen.",
	["This error as a bug report to copy, with a link to the bug form. Nothing is sent by itself."] = "Dieser Fehler als Fehlerbericht zum Kopieren, mit einem Link zum Fehlerformular. Nichts wird von selbst gesendet.",
	["This is ElvUI's \"Table\" export, which is Lua code. EldoUI never runs pasted code: export the profile again in ElvUI with the normal (compressed) format."] = "Das ist ElvUIs „Table“-Export, also Lua-Code. EldoUI führt nie eingefügten Code aus: Exportiert das Profil in ElvUI erneut im normalen (komprimierten) Format.",
	["This is a talent build (a talent calculator link or a talent loadout string). The Talent Planner reads it: paste it in the planner's Import box, or type /eui talents import followed by it."] = "Das ist ein Talentbuild (ein Link aus einem Talentrechner oder ein Talent-String). Der Talentplaner liest es: Fügt es in das Importfeld des Planers ein oder gebt /eui talents import gefolgt davon ein.",
	["This key set"] = "Dieser Tastensatz",
	["This key set is not there any more."] = "Diesen Tastensatz gibt es nicht mehr.",
	["This key types nothing"] = "Diese Taste tippt nichts",
	["This layout keeps bar %d out of sight. Point at it out of combat to use it; its keys work any time."] = "Dieses Layout hält Leiste %d verborgen. Zeigt außerhalb des Kampfes darauf, um sie zu benutzen; ihre Tasten funktionieren jederzeit.",
	["This layout keeps the healer group frames beside the center."] = "Dieses Layout hält die Heiler-Gruppenrahmen neben der Mitte.",
	["This login"] = "Dieser Login",
	["This look uses your layout."] = "Diese Optik verwendet Euer Layout.",
	["This module is not loaded."] = "Dieses Modul ist nicht geladen.",
	["This module is off."] = "Dieses Modul ist aus.",
	["This module's setting; the module's own page shows the same value."] = "Einstellung dieses Moduls; die eigene Seite des Moduls zeigt denselben Wert.",
	["This plan was made for another character. Look at the preview again."] = "Dieser Plan wurde für einen anderen Charakter erstellt. Seht Euch die Vorschau noch einmal an.",
	["This point-linked layout cannot be imported: %s. Nothing was changed."] = "Dieses punktverknüpfte Layout lässt sich nicht importieren: %s. Nichts wurde geändert.",
	["This profile"] = "Dieses Profil",
	["This profile is set up already, so Apply keeps its scale, layout, look, role, Blizzard UI switches and convenience features, and sets up this character's chat tabs, game settings and other addons' profiles."] = "Dieses Profil ist bereits eingerichtet, daher behält Übernehmen Skalierung, Layout, Optik, Rolle, Blizzard-UI-Schalter und Komfortfunktionen und richtet Chatreiter, Spieleinstellungen und die Profile anderer Addons für diesen Charakter ein.",
	["This session"] = "Diese Sitzung",
	["This skin has one look."] = "Dieser Skin hat nur eine Optik.",
	["This string doesn't say which game it was made for. EldoUI reads it as a WoW: Forever layout: positions, sizes and visibility carry over. Skipped: %s."] = "Dieser String verrät nicht, für welches Spiel er erstellt wurde. EldoUI liest ihn als Layout für WoW: Forever: Positionen, Größen und Sichtbarkeit werden übernommen. Übersprungen: %s.",
	["This string holds a list your EldoUI doesn't have (%s)."] = "Dieser String enthält eine Liste, die Euer EldoUI nicht hat (%s).",
	["This string is for the %s module, which isn't installed."] = "Dieser String ist für das Modul %s, das nicht installiert ist.",
	["This string was made for another version of the game (%s), not WoW: Forever. EldoUI imports what Forever has: positions, sizes and visibility. Skipped: %s."] = "Dieser String wurde für eine andere Version des Spiels erstellt (%s), nicht für WoW: Forever. EldoUI importiert, was Forever hat: Positionen, Größen und Sichtbarkeit. Übersprungen: %s.",
	["This week's cap"] = "Obergrenze dieser Woche",
	["This window can't be moved or scaled in combat."] = "Dieses Fenster lässt sich im Kampf nicht verschieben oder skalieren.",
	["Threat"] = "Bedrohung",
	["Threat border"] = "Bedrohungsrand",
	["Threat colors and the threat meter."] = "Bedrohungsfarben und der Bedrohungsmesser.",
	["Threat colors on nameplates and EldoUI's threat meter at its placed spot. Main tank frames show in raids. Nothing else moves."] = "Bedrohungsfarben auf Namensplaketten und EldoUIs Bedrohungsmesser an seinem Platz. Haupttankrahmen erscheinen in Schlachtzügen. Sonst bewegt sich nichts.",
	["Thursday"] = "Donnerstag",
	["Time left"] = "Verbleibende Zeit",
	["Tint"] = "Tönung",
	["To"] = "An",
	["To keep your saved file small, EldoUI let go of its %d oldest backup copies. Your journal's newest copy from before an update is always kept."] = { one = "Damit Eure gespeicherte Datei klein bleibt, hat EldoUI seine älteste Sicherungskopie verworfen. Die neueste Kopie Eures Tagebuchs von vor einem Update bleibt immer erhalten.", other = "Damit Eure gespeicherte Datei klein bleibt, hat EldoUI seine %d ältesten Sicherungskopien verworfen. Die neueste Kopie Eures Tagebuchs von vor einem Update bleibt immer erhalten." },
	["Toasts, banners, talking head, raid warnings, red error text, zone text, ready check and pop-ups, tutorials."] = "Hinweise, Banner, sprechender Kopf, Schlachtzugswarnungen, roter Fehlertext, Gebietstext, Bereitschaftscheck und Pop-ups, Tutorials.",
	["Too large for the %s layout's spots."] = "Zu groß für die Plätze des Layouts %s.",
	["Too large for the %s layout: it would cover the %s."] = "Zu groß für das Layout %s, es würde Folgendes verdecken: %s.",
	["Tools"] = "Werkzeuge",
	["Tooltips"] = "Tooltips",
	["Tooltips: Pointing at a player in a battleground no longer shows an error when a part of EldoUI that adds tooltip lines turns on or off."] = "Tooltips: Zeigt Ihr auf einem Schlachtfeld auf einen Spieler, erscheint kein Fehler mehr, wenn ein Teil von EldoUI, der Tooltipzeilen hinzufügt, ein- oder ausgeschaltet wird.",
	["Top"] = "Oben",
	["Top left"] = "Oben links",
	["Top right"] = "Oben rechts",
	["Totem and shield reminders"] = "Totem- und Schilderinnerungen",
	["Totem bar for your role, reminders and an Ankh counter"] = "Totemleiste für Eure Rolle, Erinnerungen und ein Ankh-Zähler",
	["Totem loadout: %s"] = "Totemzusammenstellung: %s",
	["Totem nameplates"] = "Totem-Namensplaketten",
	["Totem range"] = "Totemreichweite",
	["Totem slots can hold hidden combat data, so EldoUI moves and skins Blizzard's own totem bar instead."] = "Totemplätze können verborgene Kampfdaten enthalten, daher verschiebt und skinnt EldoUI stattdessen Blizzards eigene Totemleiste.",
	["Tour helps"] = "Tour-Hilfen",
	["Tour helps explain new parts of EldoUI the first time you meet them, and a new character on an account you already set up gets one short page instead of the whole setup."] = "Tour-Hilfen erklären neue Teile von EldoUI, wenn Ihr ihnen zum ersten Mal begegnet, und ein neuer Charakter auf einem bereits eingerichteten Account erhält eine kurze Seite statt der ganzen Einrichtung.",
	["Tour helps explain new things once, like this one. Turn them off here; Show tour helps again brings them back."] = "Tour-Hilfen erklären Neues einmal, so wie diese hier. Schaltet sie hier aus; „Tour-Hilfen wieder anzeigen“ holt sie zurück.",
	["Tour helps: /eui tour %s, or /eui tour reset to see them all again."] = "Tour-Hilfen: /eui tour %s oder /eui tour reset, um alle erneut zu sehen.",
	["Tracked Buffs"] = "Verfolgte Stärkungszauber",
	["Tracked buffs"] = "Verfolgte Stärkungszauber",
	["Trade"] = "Handel",
	["Trade window"] = "Handelsfenster",
	["Trades health for mana."] = "Tauscht Gesundheit gegen Mana.",
	["Trainer"] = "Lehrer",
	["Tranquility is the healer's; your own pick."] = "Gelassenheit ist Sache des Heilers; Eure eigene Wahl.",
	["Transmogrify"] = "Transmogrifikation",
	["Trav"] = "Reise",
	["Travel"] = "Reisen",
	["Travel Form and Aquatic Form are on the stance bar."] = "Reisegestalt und Wassergestalt liegen auf der Haltungsleiste.",
	["Tritanopia (blue)"] = "Tritanopie (Blau)",
	["Trivial"] = "Trivial",
	["Troubleshooting"] = "Fehlerbehebung",
	["Try it"] = "Ausprobieren",
	["Try tags"] = "Tags testen",
	["Tuesday"] = "Dienstag",
	["Turn"] = "Drehen",
	["Turn all off"] = "Alle ausschalten",
	["Turn all on"] = "Alle einschalten",
	["Turn every %s switch off and put your own game settings back?"] = "Alle Schalter von %s ausschalten und Eure eigenen Spieleinstellungen wiederherstellen?",
	["Turn every switch off and put your own game settings back. If a part needs a reload to look like Blizzard's again, you are asked once."] = "Schaltet alle Schalter aus und stellt Eure eigenen Spieleinstellungen wieder her. Braucht ein Teil ein Neuladen, um wieder wie bei Blizzard auszusehen, werdet Ihr einmal gefragt.",
	["Turn every switch on this tab off and put your own game settings back."] = "Schaltet alle Schalter auf diesem Reiter aus und stellt Eure eigenen Spieleinstellungen wieder her.",
	["Turn every switch on this tab off and put your own game settings back? The choices you made on this tab are lost."] = "Alle Schalter auf diesem Reiter ausschalten und Eure eigenen Spieleinstellungen wiederherstellen? Eure Auswahl auf diesem Reiter geht verloren.",
	["Turn it on on the Modules page (%s), or type %s."] = "Schaltet es auf der Seite Module ein (%s) oder gebt %s ein.",
	["Turn off"] = "Ausschalten",
	["Turn off %s"] = "%s ausschalten",
	["Turn off the bar page keys"] = "Tasten zum Leistenblättern ausschalten",
	["Turn on"] = "Einschalten",
	["Turn on \"%s\" first."] = "Schaltet zuerst \"%s\" ein.",
	["Turn on %s"] = "%s einschalten",
	["Turn on Blizzard UI > %s first."] = "Schaltet zuerst Blizzard-UI > %s ein.",
	["Turn on Blizzard UI > %s: %s first."] = "Schaltet zuerst Blizzard-UI > %s: %s ein.",
	["Turn on the %s module first."] = "Schaltet zuerst das Modul %s ein.",
	["Turn on the Consumable Bar"] = "Verbrauchsgüterleiste einschalten",
	["Turn on the resources and frames your class uses (combo points, form mana, totem timers, pet frames)."] = "Schaltet die Ressourcen und Rahmen ein, die Eure Klasse nutzt (Kombopunkte, Gestaltmana, Totemtimer, Begleiterrahmen).",
	["Turn on the resources, reminders and spells your class uses, on top of the role."] = "Schaltet zusätzlich zur Rolle die Ressourcen, Erinnerungen und Zauber ein, die Eure Klasse nutzt.",
	["Turning it off takes full effect after a reload."] = "Das Ausschalten wirkt erst nach einem Neuladen vollständig.",
	["Turns %s off for this character, after a reload, and EldoUI does all of its jobs."] = "Schaltet %s für diesen Charakter nach einem Neuladen aus, und EldoUI übernimmt alle seine Aufgaben.",
	["Turns %s off for this character, after a reload, so EldoUI's %s runs."] = "Schaltet %s für diesen Charakter nach einem Neuladen aus, damit EldoUIs %s läuft.",
	["Turns on Large text at the size named above. Undo puts back what you had."] = "Schaltet „Große Schrift“ in der oben genannten Größe ein. „Rückgängig“ stellt Euren vorherigen Stand wieder her.",
	["Turns the enemy into a sheep; damage breaks it."] = "Verwandelt den Gegner in ein Schaf; Schaden bricht die Verwandlung.",
	["Turns the note off for good. The switch on the What's new page turns it back on."] = "Schaltet den Hinweis dauerhaft aus. Der Schalter auf der Seite Neuigkeiten schaltet ihn wieder ein.",
	["Turns the paging off on those bars and shows the keys on bars 1 to 3. The paging can be changed back on the Action Bars page, the keys on the Keybinds page."] = "Schaltet den Seitenwechsel auf diesen Leisten aus und zeigt die Tasten auf den Leisten 1 bis 3. Der Seitenwechsel lässt sich auf der Seite „Aktionsleisten“ zurückstellen, die Tasten auf der Seite „Tastenbelegungen“.",
	["Tutorials, help tips and cinematic frames"] = "Tutorials, Hilfetipps und Zwischensequenzrahmen",
	["Twin Orbs"] = "Twin Orbs",
	["Twin Orbs (1440p)"] = "Twin Orbs (1440p)",
	["Twin Orbs adds an eleventh layout, with health and power orbs, a shared action-bar tray and the Infernal Stone skin."] = "Twin Orbs bringt ein elftes Layout mit Gesundheits- und Ressourcenkugeln, einer gemeinsamen Aktionsleistenablage und dem Skin Infernal Stone.",
	["Two things get in the way of your keys:"] = "Zwei Dinge stören Eure Tasten:",
	["Type"] = "Typ",
	["Type %s in chat or use the EldoUI button in the Game Menu to open the EldoUI options."] = "Gebt %s im Chat ein oder nutzt die EldoUI-Schaltfläche im Spielmenü, um die EldoUI-Optionen zu öffnen.",
	["Type %s to choose."] = "Gebt %s ein, um zu wählen.",
	["Type /eui locale track first, then open the pages you want to check."] = "Gebt zuerst /eui locale track ein und öffnet dann die Seiten, die Ihr prüfen wollt.",
	["Type /reload after combat to apply this."] = "Gebt nach dem Kampf /reload ein, um dies zu übernehmen.",
	["Type a name and press Enter. New lists start as block lists."] = "Gebt einen Namen ein und drückt die Eingabetaste. Neue Listen beginnen als Sperrlisten.",
	["Type a name and press Enter: a new profile with default settings, used by this character from now on."] = "Gebt einen Namen ein und drückt die Eingabetaste: ein neues Profil mit Standardeinstellungen, das dieser Charakter ab jetzt nutzt.",
	["Type a new name and press Enter. Built-in lists keep their name."] = "Gebt einen neuen Namen ein und drückt die Eingabetaste. Eingebaute Listen behalten ihren Namen.",
	["Type a new name for this profile and press Enter. Characters, profile rules and class defaults follow the new name."] = "Gebt einen neuen Namen für dieses Profil ein und drückt die Eingabetaste. Charaktere, Profilregeln und Klassenstandards folgen dem neuen Namen.",
	["Type and press Enter to search."] = "Eingeben und Eingabetaste drücken, um zu suchen.",
	["Type tags and press Enter to see the result below."] = "Gebt Tags ein und drückt die Eingabetaste, um unten das Ergebnis zu sehen.",
	["Type these in chat. Words in <> are yours to fill in. /eui help <command> shows one."] = "Gebt diese im Chat ein. Wörter in <> füllt Ihr selbst aus. /eui help <command> zeigt einen davon.",
	["UI amount"] = "UI-Umfang",
	["UI amount as set"] = "UI-Umfang wie eingestellt",
	["UI amount: %s"] = "UI-Umfang: %s",
	["UI amount: %s (%s)"] = "UI-Umfang: %s (%s)",
	["UI amount: %s, %s."] = "UI-Umfang: %s, %s.",
	["UI amount: %s, your modules already match it."] = "UI-Umfang: %s, Eure Module entsprechen dem bereits.",
	["UI amount: stays as set."] = "UI-Umfang: bleibt wie eingestellt.",
	["UI scale"] = "UI-Skalierung",
	["UI scale is %s (%.4f). Use %s (1440p), %s or a number from 0.4 to 1.2."] = "Die UI-Skalierung ist %s (%.4f). Verwendet %s (1440p), %s oder eine Zahl von 0.4 bis 1.2.",
	["UI scale set to %.4f."] = "UI-Skalierung auf %.4f gesetzt.",
	["UI scale: %s"] = "UI-Skalierung: %s",
	["UI scale: keep"] = "UI-Skalierung: behalten",
	["UI widgets (top center, below minimap, encounter power bar)"] = "UI-Widgets (oben mittig, unter der Minikarte, Begegnungs-Ressourcenleiste)",
	["UK"] = "UK",
	["UK English keyboard (ISO): a tall Enter key and a key left of Z."] = "Britische Tastatur (ISO): eine hohe Eingabetaste und eine Taste links von Z.",
	["US"] = "US",
	["US English keyboard (ANSI): a long Shift key, no key left of Z."] = "US-amerikanische Tastatur (ANSI): eine lange Umschalttaste, keine Taste links von Z.",
	["Uncheck every module below: each one goes back to the visibility it had before."] = "Entfernt das Häkchen bei allen Modulen unten: Jedes erhält wieder die Sichtbarkeit, die es vorher hatte.",
	["Undo"] = "Rückgängig",
	["Undo UI amount"] = "UI-Umfang rückgängig",
	["Undo all"] = "Alles rückgängig",
	["Undo changes"] = "Änderungen rückgängig",
	["Undo for layout, pack and setup changes keeps the last three changes of each profile across reloads."] = "Rückgängig für Layout-, Paket- und Einrichtungsänderungen merkt sich die letzten drei Änderungen jedes Profils auch über ein Neuladen hinweg.",
	["Undo last"] = "Schritt zurück",
	["Undo last (Ctrl+Z) brings them back."] = "„Schritt zurück“ (Strg+Z) holt sie zurück.",
	["Undo last key set"] = "Letzten Tastensatz rückgängig",
	["Undo last setup change"] = "Letzte Einrichtungsänderung rückgängig",
	["Undo the last setup"] = "Letzte Einrichtung rückgängig machen",
	["Undo the restore of %s? It goes back to how it was just before, and what it holds now is kept in its place."] = "Die Wiederherstellung von %s rückgängig machen? Es kehrt zum Stand von eben zurück, und was es jetzt enthält, wird an seiner Stelle aufbewahrt.",
	["Undo the setup?"] = "Einrichtung rückgängig machen?",
	["Undo the whole setup"] = "Ganze Einrichtung rückgängig machen",
	["Undo the whole setup puts it back"] = "„Ganze Einrichtung rückgängig machen“ stellt es wieder her",
	["Undo waits for the end of combat."] = "Rückgängig wartet bis zum Ende des Kampfes.",
	["Undoes the previews and pauses the setup. /eui install goes on where you stopped."] = "Macht die Vorschauen rückgängig und unterbricht die Einrichtung. /eui install macht dort weiter, wo Ihr aufgehört habt.",
	["Undone: %s."] = "Rückgängig gemacht: %s.",
	["Unfriendly"] = "Unfreundlich",
	["Unhide"] = "Einblenden",
	["Unit Frames"] = "Einheitenrahmen",
	["Unit frames"] = "Einheitenrahmen",
	["Unit frames, group frames, action bars, chat and windows keep their own switches on their pages."] = "Einheitenrahmen, Gruppenrahmen, Aktionsleisten, Chat und Fenster haben ihre eigenen Schalter auf ihren Seiten.",
	["Unit frames, nameplates and auras"] = "Einheitenrahmen, Namensplaketten und Auren",
	["Unit states and effects"] = "Einheitenzustände und Effekte",
	["Unit, party and raid frames, nameplates and eight action bars, with unit-frame graphics in your skin's materials."] = "Einheiten-, Gruppen- und Schlachtzugsrahmen, Namensplaketten und acht Aktionsleisten, mit Einheitenrahmen-Grafiken in den Materialien Eures Skins.",
	["Unit, party, raid and boss frames, cast bar, class resources, buffs, private auras and nameplates. Secure: they change out of combat."] = "Einheiten-, Gruppen-, Schlachtzugs- und Bossrahmen, Zauberleiste, Klassenressourcen, Stärkungszauber, private Auren und Namensplaketten. Geschützt: Sie ändern sich außerhalb des Kampfes.",
	["Unit-frame graphics"] = "Einheitenrahmen-Grafiken",
	["Unit-frame graphics are not available in this version."] = "Einheitenrahmen-Grafiken sind in dieser Version nicht verfügbar.",
	["Unit-frame graphics: %s"] = "Einheitenrahmen-Grafiken: %s",
	["Unknown addon"] = "Unbekanntes Addon",
	["Unknown category. Try all, general, positions, global, a module name from /eui modules, or one of these lists: %s."] = "Unbekannte Kategorie. Versucht all, general, positions, global, einen Modulnamen aus /eui modules oder eine dieser Listen: %s.",
	["Unknown command %q. Did you mean %s/eui %s|r? %s lists everything."] = "Unbekannter Befehl %q. Meintet Ihr %s/eui %s|r? %s listet alles auf.",
	["Unknown command %q. Type %s for the full list."] = "Unbekannter Befehl %q. Gebt %s für die vollständige Liste ein.",
	["Unlock EldoUI's frames so you can drag them. It opens on your fight screen (Combat mode); pick All frames or a group on the move panel for the rest. Done in move mode brings this window back."] = "Entsperrt EldoUIs Rahmen, damit Ihr sie ziehen könnt. Es öffnet sich mit Eurem Kampfbildschirm (Kampfmodus); wählt auf dem Verschiebepanel „Alle Rahmen“ oder eine Gruppe für den Rest. „Fertig“ im Verschiebemodus holt dieses Fenster zurück.",
	["Unlock every EldoUI frame to drag it into place. This window steps aside until you press Done."] = "Entsperrt alle EldoUI-Rahmen, um sie an ihren Platz zu ziehen. Dieses Fenster tritt beiseite, bis Ihr auf Fertig drückt.",
	["Until it is on, %s stay free; then they use your potion, healthstone, and mana potion or bandage."] = "Bis sie an ist, bleiben %s frei; danach nutzen sie Euren Trank, Gesundheitsstein und Manatrank oder Verband.",
	["Until the window closes"] = "Bis das Fenster schließt",
	["Until you log out"] = "Bis zum Ausloggen",
	["Up from the screen point in the title to the same point of the frame: a higher number moves it up, a lower one down. Press Enter to apply."] = "Senkrecht vom Bildschirmpunkt im Titel zum selben Punkt des Rahmens: Eine höhere Zahl verschiebt ihn nach oben, eine niedrigere nach unten. Drückt die Eingabetaste zum Übernehmen.",
	["Update"] = "Aktualisieren",
	["Upgrade spell ranks automatically"] = "Zauberränge automatisch aktualisieren",
	["Usable area"] = "Nutzbarer Bereich",
	["Usage: /eui data [list | restore <part> [<name>] | follow <part> [<name>]]"] = "Verwendung: /eui data [list | restore <part> [<name>] | follow <part> [<name>]]",
	["Usage: /eui profile list | use <name> | new <name> | copy <from> | reset | delete <name>"] = "Verwendung: /eui profile list | use <name> | new <name> | copy <from> | reset | delete <name>",
	["Usage: /eui send <party | raid | guild | player> [what]"] = "Verwendung: /eui send <party | raid | guild | player> [what]",
	["Use"] = "Benutzen",
	["Use %s"] = "%s benutzen",
	["Use %s/eui %s on|r, %soff|r or %stoggle|r."] = "Verwendet %s/eui %s on|r, %soff|r oder %stoggle|r.",
	["Use EldoUI's"] = "EldoUI nutzen",
	["Use EldoUI's own frame and hide Blizzard's."] = "EldoUIs eigenen Rahmen verwenden und Blizzards ausblenden.",
	["Use Gamepad Mode UI"] = "Gamepad-Modus-UI verwenden",
	["Use general setting"] = "Allgemeine Einstellung verwenden",
	["Use it as it is"] = "So verwenden, wie es ist",
	["Use its look"] = "Seine Optik übernehmen",
	["Use on, off or toggle after %s. Type %s for the list."] = "Verwendet on, off oder toggle nach %s. Gebt %s für die Liste ein.",
	["Use the EldoUI font for the whole game"] = "EldoUI-Schrift für das ganze Spiel verwenden",
	["Use the EldoUI profile as it is"] = "EldoUI-Profil so verwenden, wie es ist",
	["Use the Hearthstone (Consumable Bar)"] = "Ruhestein benutzen (Verbrauchsgüterleiste)",
	["Use the Never show list"] = "Liste „Nie anzeigen“ verwenden",
	["Use the best %s (Consumable Bar)"] = "Beste Sorte benutzen: %s (Verbrauchsgüterleiste)",
	["Use the game's class colors"] = "Klassenfarben des Spiels verwenden",
	["Use the layout's spot"] = "Platz des Layouts verwenden",
	["Use the new buttons in a whisper window to invite, look up, add, or ignore the contact, or open your saved conversation."] = "Mit den neuen Schaltflächen im Flüsterfenster könnt Ihr den Kontakt einladen, nachschlagen, hinzufügen oder ignorieren oder Euer gespeichertes Gespräch öffnen.",
	["Use the quest item (Objective Tracker)"] = "Questgegenstand benutzen (Zielverfolgung)",
	["Use the rules below when your talent group or content changes."] = "Die Regeln unten anwenden, wenn sich Eure Talentgruppe oder der Inhalt ändert.",
	["Use the suggested size"] = "Vorgeschlagene Größe verwenden",
	["Use this color preset? Colors you picked yourself on this page are replaced."] = "Diese Farbvorlage verwenden? Farben, die Ihr auf dieser Seite selbst gewählt habt, werden ersetzt.",
	["Use this group. With no group on, every aura of the widget's kind shows."] = "Diese Gruppe verwenden. Ist keine Gruppe an, erscheint jede Aura der Art dieses Elements.",
	["Use your execute spell"] = "Euren Hinrichtungszauber verwenden",
	["Use your mana gem (Consumable Bar)"] = "Euren Manaedelstein benutzen (Verbrauchsgüterleiste)",
	["Used for highlights, the EldoUI name and cast bars. Layout presets set their own."] = "Wird für Hervorhebungen, den EldoUI-Namen und Zauberleisten verwendet. Layoutvorlagen setzen ihre eigene.",
	["Uses guild bank repair money when your guild allows it, then your own gold."] = "Nutzt das Reparaturgeld der Gildenbank, wenn Eure Gilde es erlaubt, danach Euer eigenes Gold.",
	["Uses the Unit-frame graphics row at the top of this tab."] = "Nutzt die Zeile Einheitenrahmen-Grafiken oben auf diesem Reiter.",
	["Uses the skin your layout was made for (now %s). It changes with the next layout you pick."] = "Nutzt den Skin, für den Euer Layout gemacht wurde (jetzt %s). Er wechselt mit dem nächsten Layout, das Ihr wählt.",
	["Using profile %s."] = "Profil %s wird verwendet.",
	["Util"] = "Nutzen",
	["Utility Cooldowns"] = "Nützliche Abklingzeiten",
	["Utility cooldowns"] = "Nützliche Abklingzeiten",
	["Values set aside"] = "Beiseitegelegte Werte",
	["Vanilla"] = "Vanilla",
	["Vanilla Original"] = "Vanilla Original",
	["Vanilla Original (1440p)"] = "Vanilla Original (1440p)",
	["Vanilla Refined"] = "Vanilla Refined",
	["Vanish is on this button outside Stealth."] = "Verschwinden liegt außerhalb von Verstohlenheit auf dieser Taste.",
	["Vehicle, possess and override bars (with leave button and seat indicator)"] = "Fahrzeug-, Besessenheits- und Ersatzleisten (mit Aussteigen-Taste und Sitzanzeige)",
	["Version %s"] = "Version %s",
	["Version %s was seen in your guild or group."] = "Version %s wurde in Eurer Gilde oder Gruppe gesehen.",
	["Version %s, game version %s (Interface %s)."] = "Version %s, Spielversion %s (Interface %s).",
	["Version check"] = "Versionsprüfung",
	["Very hard"] = "Sehr schwer",
	["Victory Rush: usable after a kill, it heals you."] = "Siegesrausch: benutzbar, nachdem Ihr einen Gegner getötet habt; heilt Euch.",
	["Visibility preset"] = "Sichtbarkeitsvorlage",
	["Visibility preset %s applied."] = "Sichtbarkeitsvorlage %s übernommen.",
	["Volume channel for EldoUI's sounds (Fanfare and modules set to Default). Master plays even with game sound effects off."] = "Lautstärkekanal für EldoUIs Sounds (Fanfare und Module auf Standard). Master spielt auch bei ausgeschalteten Soundeffekten des Spiels.",
	["Volume panel"] = "Lautstärkeregler",
	["W S move, A D strafe. Bar 1: 1-5 R F E Q Z X C."] = "W S laufen, A D seitwärts. Leiste 1: 1-5 R F E Q Z X C.",
	["W S move, A D turn. Bar 1: 1-5 R F G V X Z C."] = "W S laufen, A D drehen. Leiste 1: 1-5 R F G V X Z C.",
	["W and S move forward and back, A and D strafe, and you turn with the mouse. The side buttons send the number row keys, so 1 to = on the keyboard press the same buttons."] = "W und S laufen vor und zurück, A und D seitwärts, und gedreht wird mit der Maus. Die Seitentasten senden die Tasten der Zahlenreihe, daher drücken 1 bis = auf der Tastatur dieselben Tasten.",
	["W and S move forward and back, A and D strafe. You turn with the right mouse button held, which frees Q and E for abilities."] = "W und S laufen vor und zurück, A und D seitwärts. Gedreht wird mit gedrückter rechter Maustaste, was Q und E für Fähigkeiten frei macht.",
	["W and S move forward and back, A and D turn, Q and E strafe: the game's own movement keys."] = "W und S laufen vor und zurück, A und D drehen, Q und E seitwärts: die Bewegungstasten des Spiels.",
	["W and S move, A and D strafe, and you turn with the mouse. Bar 1: 1-5 R F E Q Z X C, bar 2: Shift + the same keys, bar 3: Ctrl + the same keys. Character moves to the comma key."] = "W und S laufen, A und D seitwärts, und gedreht wird mit der Maus. Leiste 1: 1-5 R F E Q Z X C, Leiste 2: Umschalt + dieselben Tasten, Leiste 3: Strg + dieselben Tasten. Das Charakterfenster wandert auf die Kommataste.",
	["W and S move, A and D turn, Q and E strafe. Bar 1: 1-5 R F G V X Z C, bar 2: Shift + the same keys, bar 3: Ctrl + the same keys. Character moves to the comma key."] = "W und S laufen, A und D drehen, Q und E seitwärts. Leiste 1: 1-5 R F G V X Z C, Leiste 2: Umschalt + dieselben Tasten, Leiste 3: Strg + dieselben Tasten. Das Charakterfenster wandert auf die Kommataste.",
	["Warcraft Parchment"] = "Warcraft Parchment",
	["Warlocks have no movement spell: Banish takes this key."] = "Hexenmeister haben keinen Bewegungszauber: Verbannen bekommt diese Taste.",
	["Warm dark panels in the bronze frame line of the WoW: Forever action bars and micro menu, drawn from the game's own art. The accent turns Sand when it was still the default blue."] = "Warme dunkle Panels in der bronzenen Rahmenlinie der Aktionsleisten und des Mikromenüs von WoW: Forever, nach der Grafik des Spiels gestaltet. Der Akzent wird zu Sand, wenn er noch das Standardblau war.",
	["Warning"] = "Warnung",
	["Warns you when a frame's health drops below the value you set, with a red edge, tint or glow. The game's own red screen edge is a separate setting in Options > Combat."] = "Warnt Euch, wenn die Gesundheit eines Rahmens unter den eingestellten Wert fällt, mit rotem Rand, Tönung oder Leuchten. Der eigene rote Bildschirmrand des Spiels ist eine separate Einstellung unter Optionen > Kampf.",
	["Warriors have no ally spell."] = "Krieger haben keinen Zauber für Verbündete.",
	["Warriors have no cleanse."] = "Krieger haben keine Reinigung.",
	["Warriors have no offensive dispel."] = "Krieger haben kein offensives Bannen.",
	["Warriors have no resurrection."] = "Krieger haben keine Wiederbelebung.",
	["Waypoint arrow"] = "Wegpunktpfeil",
	["Waypoints"] = "Wegpunkte",
	["Weather density"] = "Wetterdichte",
	["Wednesday"] = "Mittwoch",
	["Welcome"] = "Willkommen",
	["Welcome to EldoUI"] = "Willkommen bei EldoUI",
	["What"] = "Was",
	["What Apply changes"] = "Was Übernehmen ändert",
	["What EldoUI found in your saved data at this login. Repaired means a small fix that loses nothing, such as a gap in a list closed up."] = "Was EldoUI bei diesem Login in Euren gespeicherten Daten gefunden hat. Repariert bedeutet eine kleine Korrektur, bei der nichts verloren geht, etwa eine geschlossene Lücke in einer Liste.",
	["What changed in each EldoUI version."] = "Was sich in jeder EldoUI-Version geändert hat.",
	["What happens on a character whose keys differ from this key set. Ask me shows one alert with a preview; Automatic sets its keys out of combat, with a backup and Undo."] = "Was auf einem Charakter passiert, dessen Tasten von diesem Tastensatz abweichen. „Mich fragen“ zeigt einen Hinweis mit Vorschau; „Automatisch“ setzt seine Tasten außerhalb des Kampfes, mit Sicherung und Rückgängig.",
	["What it changes"] = "Was es ändert",
	["What it is."] = "Was es ist.",
	["What the tag string shows on your own character right now. Typing here changes nothing."] = "Was der Tag-String gerade auf Eurem eigenen Charakter zeigt. Eingaben hier ändern nichts.",
	["What the tag string shows on your target. Target something to see it."] = "Was der Tag-String auf Eurem Ziel zeigt. Nehmt etwas ins Ziel, um es zu sehen.",
	["What this text shows. Custom tags lets you write your own, e.g. [name:short] [health:percent]; the Text tags page lists every tag."] = "Was dieser Text zeigt. Mit „Eigene Tags“ schreibt Ihr Eure eigenen, z. B. [name:short] [health:percent]; die Seite Text-Tags listet alle Tags auf.",
	["What's new"] = "Neuigkeiten",
	["Wheel step"] = "Mausradschritt",
	["When EldoUI adds a layout to Blizzard's Edit Mode, make it the active one."] = "Wenn EldoUI dem Bearbeitungsmodus von Blizzard ein Layout hinzufügt, wird es zum aktiven.",
	["When a newly installed plugin has setup pages, they open once after login. Off: run them from this page."] = "Hat ein neu installiertes Plugin Einrichtungsseiten, öffnen sie sich einmal nach dem Einloggen. Aus: Startet sie von dieser Seite aus.",
	["When active"] = "Wenn aktiv",
	["When another addon does a job EldoUI also does, EldoUI stands back. Pick who handles each job; EldoUI never turns an addon off for you."] = "Erledigt ein anderes Addon eine Aufgabe, die auch EldoUI übernimmt, tritt EldoUI zurück. Wählt, wer welche Aufgabe übernimmt; EldoUI schaltet nie von sich aus ein Addon aus.",
	["When the frame is shown. Outside the rule it fades to the faded alpha. Hovering a faded frame shows it again."] = "Wann der Rahmen angezeigt wird. Außerhalb der Regel blendet er auf die Ausblend-Deckkraft ab. Mit der Maus über einem ausgeblendeten Rahmen erscheint er wieder.",
	["When the frame is shown. Outside the rule it fades to the faded alpha; at 0 it is hidden for real, so it takes no clicks (When active only fades it, so it still takes clicks). Hovering shows it again."] = "Wann der Rahmen angezeigt wird. Außerhalb der Regel blendet er auf die Ausblend-Deckkraft ab; bei 0 ist er wirklich ausgeblendet und nimmt keine Klicks an („Wenn aktiv“ blendet ihn nur ab, er nimmt also weiter Klicks an). Mit der Maus darüber erscheint er wieder.",
	["When the game notices a controller, EldoUI asks once whether to place its frames for controller play. Nothing changes until you choose."] = "Erkennt das Spiel einen Controller, fragt EldoUI einmal, ob es seine Rahmen für das Spielen mit Controller anordnen soll. Nichts ändert sich, bis Ihr wählt.",
	["When you forget a character in the Alts window, its journal is backed up first and kept here until you put it back or remove it."] = "Wenn Ihr im Twinkfenster einen Charakter vergesst, wird sein Tagebuch zuerst gesichert und hier aufbewahrt, bis Ihr es zurückholt oder entfernt.",
	["Where a press starts a drag. Windows with secure parts always drag by the title bar."] = "Wo ein Drücken das Ziehen startet. Fenster mit geschützten Teilen werden immer an der Titelleiste gezogen.",
	["Where every frame sits. Click a layout to preview it, then Apply or go on; Back puts your old positions back."] = "Wo jeder Rahmen sitzt. Klickt auf ein Layout für eine Vorschau, dann auf Übernehmen oder Weiter; Zurück stellt Eure alten Positionen wieder her.",
	["Where the Healer role puts your party and raid frames. The cast bar and the cooldown rows stay where they are."] = "Wohin die Heilerrolle Eure Gruppen- und Schlachtzugsrahmen setzt. Die Zauberleiste und die Abklingzeitreihen bleiben, wo sie sind.",
	["Where the game's own shortcuts are"] = "Wo die Spielkürzel liegen",
	["Where the glow sits: under the icon's numbers and keybind, over them, or on top of everything on the frame."] = "Wo das Leuchten liegt: unter den Zahlen und der Tastenbelegung des Symbols, darüber oder über allem auf dem Rahmen.",
	["Which auras appear. The game does the filtering. Custom groups lets you combine up to four groups with your own spell lists and conditions."] = "Welche Auren erscheinen. Das Spiel übernimmt das Filtern. Mit „Eigene Gruppen“ kombiniert Ihr bis zu vier Gruppen mit eigenen Zauberlisten und Bedingungen.",
	["Which colors you mix up. Red and green kinds get blue for good and friendly; the blue kind gets green."] = "Welche Farben Ihr verwechselt. Die Rot- und Grün-Arten bekommen Blau für gut und freundlich; die Blau-Art bekommt Grün.",
	["Which of Blizzard's own frames and windows EldoUI may change. Anything EldoUI may not change stays exactly as Blizzard made it."] = "Welche von Blizzards eigenen Rahmen und Fenstern EldoUI ändern darf. Alles, was EldoUI nicht ändern darf, bleibt genau so, wie Blizzard es gemacht hat.",
	["Which parts of Blizzard's UI EldoUI may change (Blizzard UI page)."] = "Welche Teile von Blizzards UI EldoUI ändern darf (Seite Blizzard-UI).",
	["Which profile should the setup write into?"] = "In welches Profil soll die Einrichtung schreiben?",
	["While the setup is not finished: one chat line per login and a small alert. Off: the setup no longer opens by itself; /eui install still opens it."] = "Solange die Einrichtung nicht abgeschlossen ist: eine Chatzeile pro Login und ein kleiner Hinweis. Aus: Die Einrichtung öffnet sich nicht mehr von selbst; /eui install öffnet sie weiterhin.",
	["While you drag a frame, lines show where its edges or center line up with another frame or the screen center."] = "Während Ihr einen Rahmen zieht, zeigen Linien, wo seine Kanten oder seine Mitte mit einem anderen Rahmen oder der Bildschirmmitte fluchten.",
	["While you hold the Show HUD key (Key Bindings > AddOns > EldoUI), every faded EldoUI frame shows. Works in combat. A protected frame its rule hides for real stays hidden."] = "Solange Ihr die Taste zum Anzeigen des HUD haltet (Tastaturbelegung > AddOns > EldoUI), erscheint jeder ausgeblendete EldoUI-Rahmen. Funktioniert im Kampf. Ein geschützter Rahmen, den seine Regel wirklich ausblendet, bleibt verborgen.",
	["While you move"] = "Während Ihr Euch bewegt",
	["Whisper"] = "Flüstern",
	["Whispers"] = "Flüstern",
	["Whispers and Battle.net whispers also get their own tab. The main window keeps them too."] = "Flüstern und Battle.net-Flüstern bekommen auch einen eigenen Reiter. Das Hauptfenster behält sie ebenfalls.",
	["Whispers in the chat"] = "Flüstern im Chat",
	["Whispers tab"] = "Flüsterreiter",
	["Whispers, loot and the public channels have their own tabs now, so your main chat stays readable. Right-click a tab to change or close it."] = "Flüstern, Beute und die öffentlichen Kanäle haben jetzt eigene Reiter, damit Euer Hauptchat lesbar bleibt. Rechtsklickt auf einen Reiter, um ihn zu ändern oder zu schließen.",
	["White"] = "Weiß",
	["Who uses it?"] = "Wer nutzt es?",
	["Whole UI"] = "Ganze UI",
	["Whole screen"] = "Ganzer Bildschirm",
	["Whole screen: no limit. Centered 16:9: the width a 16:9 screen of the same height has (2560 on a 1440 px tall screen). Has no effect when the screen is not wider than the area."] = "Ganzer Bildschirm: keine Begrenzung. Zentriert 16:9: die Breite eines 16:9-Bildschirms gleicher Höhe (2560 bei einem 1440 px hohen Bildschirm). Wirkt nicht, wenn der Bildschirm nicht breiter als der Bereich ist.",
	["Wide center: cooldowns first, then resources and buffs, unit frames wide apart, side bars beside the bar stack."] = "Breite Mitte: zuerst Abklingzeiten, dann Ressourcen und Stärkungszauber, Einheitenrahmen weit auseinander, Seitenleisten neben dem Leistenstapel.",
	["Widescreen Edges"] = "Widescreen Edges",
	["Widescreen Edges (1440p)"] = "Widescreen Edges (1440p)",
	["Width of"] = "Breite von",
	["Width of the area in UI units, used with \"Custom width\". With the auto UI scale a 16:9 area is 2560 wide."] = "Breite des Bereichs in UI-Einheiten, verwendet mit „Eigene Breite“. Mit automatischer UI-Skalierung ist ein 16:9-Bereich 2560 breit.",
	["Width of the grid lines in screen pixels."] = "Breite der Rasterlinien in Bildschirmpixeln.",
	["Wild Berries"] = "Wildbeeren",
	["Wild Thornroot"] = "Wilde Dornwurzel",
	["Window"] = "Fenster",
	["Window look"] = "Fensteroptik",
	["Window scale"] = "Fensterskalierung",
	["Window size"] = "Fenstergröße",
	["Window titles use the skin's own font (now %s). Off keeps EldoUI's title font."] = "Fenstertitel verwenden die eigene Schrift des Skins (jetzt %s). Aus behält EldoUIs Titelschrift.",
	["Window titles use the skin's own font when it has one. This skin uses EldoUI's title font."] = "Fenstertitel verwenden die eigene Schrift des Skins, wenn er eine hat. Dieser Skin verwendet EldoUIs Titelschrift.",
	["Windows"] = "Fenster",
	["Windows EldoUI may change: %d of %d (in your skin: %d, original: %d)."] = "Fenster, die EldoUI ändern darf: %d von %d (in Eurem Skin: %d, original: %d).",
	["Windows and skins: The battleground results window opens without a stutter at the end of a large match, and the score table styling no longer logs time limit errors."] = "Fenster und Skins: Das Ergebnisfenster des Schlachtfelds öffnet sich am Ende eines großen Matches ohne Ruckler, und die Gestaltung der Punktetafel protokolliert keine Zeitlimitfehler mehr.",
	["Windows and toasts slide and fade in, glows move and switches change softly. Off shows every change at once and holds glows still, like Reduce motion on the Accessibility page."] = "Fenster und Hinweise gleiten und blenden ein, Leuchten bewegt sich und Schalter wechseln sanft. Aus zeigt jede Änderung sofort und hält Leuchten still, wie „Bewegung reduzieren“ auf der Seite Barrierefreiheit.",
	["Windows are locked (/eui windows unlock)."] = "Fenster sind gesperrt (/eui windows unlock).",
	["Windows are locked. Unlock them to drag, scale or reset a window."] = "Fenster sind gesperrt. Entsperrt sie, um ein Fenster zu ziehen, zu skalieren oder zurückzusetzen.",
	["Windows locked."] = "Fenster gesperrt.",
	["Windows unlocked."] = "Fenster entsperrt.",
	["With a target"] = "Mit Ziel",
	["With the Vanilla Original skin, the unit frames, the action bar tray, the minimap border and the micro menu wear the game's own classic art."] = "Mit dem Skin Vanilla Original tragen Einheitenrahmen, Aktionsleistenablage, Minikartenrand und Mikromenü die klassische Grafik des Spiels.",
	["WoW Forever"] = "WoW Forever",
	["Works in combat; needs a reagent."] = "Funktioniert im Kampf; braucht ein Reagenz.",
	["World and NPCs"] = "Welt und NPCs",
	["World and Travel"] = "Welt und Reisen",
	["World map and quest log"] = "Weltkarte und Questlog",
	["Worn gear at"] = "Abgenutzt ab",
	["Wowhead links"] = "Wowhead-Links",
	["Write a quick journal note"] = "Schnelle Tagebuchnotiz schreiben",
	["Writes the layout's spot into %s's own settings, so it stays there without EldoUI too. You see every value first; Undo puts them back."] = "Schreibt den Platz des Layouts in die eigenen Einstellungen von %s, damit er auch ohne EldoUI dort bleibt. Ihr seht zuerst jeden Wert; Rückgängig stellt sie wieder her.",
	["Writes this font into every module below that offers it."] = "Schreibt diese Schrift in jedes Modul unten, das sie anbietet.",
	["Writes this texture into every module below that offers it."] = "Schreibt diese Textur in jedes Modul unten, das sie anbietet.",
	["X"] = "X",
	["XP Bar"] = "EP-Leiste",
	["XP, reputation and honor bars"] = "EP-, Ruf- und Ehreleisten",
	["Y"] = "Y",
	["Yes"] = "Ja",
	["Yes: only auras you or your pet applied. No: only other people's."] = "Ja: nur Auren, die Ihr oder Euer Begleiter gewirkt habt. Nein: nur die von anderen.",
	["You already use %s."] = "Ihr nutzt bereits %s.",
	["You are not in a group."] = "Ihr seid in keiner Gruppe.",
	["You are not in a guild."] = "Ihr seid in keiner Gilde.",
	["You are not in a raid."] = "Ihr seid in keinem Schlachtzug.",
	["You are playing with a controller. EldoUI can place its frames for controller play: centered above the game's gamepad bar and clear of its radial menu. Your normal layout and dragged frames stay saved, and everything goes back when the game's gamepad interface is turned off."] = "Ihr spielt mit einem Controller. EldoUI kann seine Rahmen für das Spielen mit Controller anordnen: zentriert über der Gamepad-Leiste des Spiels und frei von seinem Radialmenü. Euer normales Layout und verschobene Rahmen bleiben gespeichert, und alles kehrt zurück, wenn die Gamepad-Oberfläche des Spiels ausgeschaltet wird.",
	["You are stunned, feared, rooted or silenced (the game's loss of control alert)."] = "Ihr seid betäubt, verängstigt, festgewurzelt oder zum Schweigen gebracht (die Kontrollverlust-Warnung des Spiels).",
	["You can apply it"] = "Ihr könnt sie wirken",
	["You die"] = "Ihr sterbt",
	["You enter combat: something attacks you, or you attack."] = "Ihr geratet in einen Kampf: Etwas greift Euch an, oder Ihr greift an.",
	["You have a controller. EldoUI can place its frames for controller play while the game's gamepad interface is on: centered above the game's gamepad bar and clear of its radial menu."] = "Ihr habt einen Controller. EldoUI kann seine Rahmen für das Spielen mit Controller anordnen, solange die Gamepad-Oberfläche des Spiels an ist: zentriert über der Gamepad-Leiste des Spiels und frei von seinem Radialmenü.",
	["You manage your own keys"] = "Ihr verwaltet Eure Tasten selbst",
	["You manage your own keys, so EldoUI writes no key. Untick \"I manage my own keys\" on the Keybinds page to use a key set."] = "Ihr verwaltet Eure Tasten selbst, daher schreibt EldoUI keine Taste. Entfernt auf der Seite „Tastenbelegungen“ den Haken bei „Ich verwalte meine Tasten selbst“, um einen Tastensatz zu nutzen.",
	["You manage your own keys: EldoUI leaves them as they are."] = "Ihr verwaltet Eure Tasten selbst: EldoUI lässt sie, wie sie sind.",
	["You manage your own keys: no key changes, and EldoUI never offers keys on your other characters."] = "Ihr verwaltet Eure Tasten selbst: Keine Taste ändert sich, und EldoUI bietet auf Euren anderen Charakteren nie Tasten an.",
	["You picked EldoUI over %s, but %s is still on, so EldoUI stands back. Type %s to choose."] = "Ihr habt EldoUI statt %s gewählt, aber %s ist noch an, daher tritt EldoUI zurück. Gebt %s ein, um zu wählen.",
	["You picked EldoUI over %s, but it is still on, so EldoUI stands back. Choose again, or turn it off in the addon list."] = "Ihr habt EldoUI statt %s gewählt, aber es ist noch an, daher tritt EldoUI zurück. Wählt erneut oder schaltet es in der Addon-Liste aus.",
	["You picked EldoUI, but %s is still on."] = "Ihr habt EldoUI gewählt, aber %s ist noch an.",
	["You ran the setup on this character before. Every step starts on \"keep\", so clicking through changes nothing, and EldoUI asks before it changes your profile."] = "Ihr habt die Einrichtung auf diesem Charakter schon einmal durchlaufen. Jeder Schritt beginnt auf „Behalten“, Durchklicken ändert also nichts, und EldoUI fragt, bevor es Euer Profil ändert.",
	["You set up EldoUI on this character before. Each step you apply now overwrites that part of your profile %s. A backup is kept: the Welcome step can undo it. Continue?"] = "Ihr habt EldoUI auf diesem Charakter schon einmal eingerichtet. Jeder Schritt, den Ihr jetzt übernehmt, überschreibt diesen Teil Eures Profils %s. Eine Sicherung bleibt erhalten: Der Schritt „Willkommen“ kann es rückgängig machen. Fortfahren?",
	["You use the %s layout. Apply it again?"] = "Ihr nutzt das Layout %s. Erneut übernehmen?",
	["Your EldoUI data from %s is here after a reload."] = "Eure EldoUI-Daten von %s sind nach einem Neuladen da.",
	["Your EldoUI settings were saved by a newer version of EldoUI. They are kept exactly as they are, including what this version doesn't know."] = "Eure EldoUI-Einstellungen wurden von einer neueren EldoUI-Version gespeichert. Sie bleiben genau so erhalten, einschließlich allem, was diese Version nicht kennt.",
	["Your EldoUI settings were updated for this version. Nothing was removed, and %d saved values EldoUI could not read are set aside. Type /eui data to see them."] = { one = "Eure EldoUI-Einstellungen wurden für diese Version aktualisiert. Nichts wurde entfernt, und %d gespeicherter Wert, den EldoUI nicht lesen konnte, ist beiseitegelegt. Gebt /eui data ein, um ihn zu sehen.", other = "Eure EldoUI-Einstellungen wurden für diese Version aktualisiert. Nichts wurde entfernt, und %d gespeicherte Werte, die EldoUI nicht lesen konnte, sind beiseitegelegt. Gebt /eui data ein, um sie zu sehen." },
	["Your EldoUI settings were updated for this version. Nothing was removed, and a copy from before the update is kept: type /eui data to see it."] = "Eure EldoUI-Einstellungen wurden für diese Version aktualisiert. Nichts wurde entfernt, und eine Kopie von vor dem Update bleibt erhalten: Gebt /eui data ein, um sie zu sehen.",
	["Your EldoUI settings were updated for this version. Nothing was removed."] = "Eure EldoUI-Einstellungen wurden für diese Version aktualisiert. Nichts wurde entfernt.",
	["Your EldoUI settings were updated for this version. Nothing was removed: a copy from before the update is kept, and %d saved values EldoUI could not read are set aside. Type /eui data to see them."] = { one = "Eure EldoUI-Einstellungen wurden für diese Version aktualisiert. Nichts wurde entfernt: Eine Kopie von vor dem Update bleibt erhalten, und %d gespeicherter Wert, den EldoUI nicht lesen konnte, ist beiseitegelegt. Gebt /eui data ein, um ihn zu sehen.", other = "Eure EldoUI-Einstellungen wurden für diese Version aktualisiert. Nichts wurde entfernt: Eine Kopie von vor dem Update bleibt erhalten, und %d gespeicherte Werte, die EldoUI nicht lesen konnte, sind beiseitegelegt. Gebt /eui data ein, um sie zu sehen." },
	["Your EldoUI setup"] = "Eure EldoUI-Einrichtung",
	["Your Felhunter's Devour Magic is on the pet bar."] = "Magie verschlingen Eures Teufelsjägers liegt auf der Begleiterleiste.",
	["Your UI is ready"] = "Eure UI ist bereit",
	["Your addons"] = "Eure Addons",
	["Your addons: no addon is turned off"] = "Eure Addons: Kein Addon wird ausgeschaltet",
	["Your armor, aura, shield or group buff."] = "Euer Rüstungs-, Aura-, Schild- oder Gruppenstärkungszauber.",
	["Your bars changed since the preview. Look at the preview again before you apply."] = "Eure Leisten haben sich seit der Vorschau geändert. Seht Euch die Vorschau vor dem Übernehmen noch einmal an.",
	["Your between-pulls bar: buffs, travel and resurrection. Point at it out of combat to use it; Ctrl and your keys work any time."] = "Eure Leiste für zwischen den Pulls: Stärkungszauber, Reisen und Wiederbelebung. Zeigt außerhalb des Kampfes darauf, um sie zu benutzen; Strg und Eure Tasten funktionieren jederzeit.",
	["Your between-pulls bar: buffs, travel and resurrection. Point at it out of combat to use it; its keys work any time."] = "Eure Leiste für zwischen den Pulls: Stärkungszauber, Reisen und Wiederbelebung. Zeigt außerhalb des Kampfes darauf, um sie zu benutzen; ihre Tasten funktionieren jederzeit.",
	["Your character dies."] = "Euer Charakter stirbt.",
	["Your chat windows for this character: EldoUI's tabs, a font size and class-colored names. The look of the chat panel itself is on the Styles step."] = "Eure Chatfenster für diesen Charakter: EldoUIs Reiter, eine Schriftgröße und Namen in Klassenfarben. Die Optik des Chatpanels selbst findet Ihr im Schritt „Stile“.",
	["Your choice."] = "Eure Wahl.",
	["Your class has no class details to add."] = "Eure Klasse hat keine Klassendetails hinzuzufügen.",
	["Your class has nothing to add."] = "Eure Klasse hat nichts hinzuzufügen.",
	["Your class setup also places %s; give them a free button."] = "Eure Klasseneinrichtung platziert auch %s; gebt ihnen eine freie Taste.",
	["Your class setup's character macros, each under its own name. A macro you already have by that name is never changed."] = "Die Charaktermakros Eurer Klasseneinrichtung, jedes unter eigenem Namen. Ein Makro, das Ihr unter diesem Namen schon habt, wird nie geändert.",
	["Your class spells on the game's controller bars, in the order of your key set: the fight's spells on page 1 and the spells between pulls on page 2. Each button shows its category, as on the keyboard. Nothing changes until you press Apply."] = "Eure Klassenzauber auf den Controller-Leisten des Spiels, in der Reihenfolge Eures Tastensatzes: die Kampfzauber auf Seite 1 und die Zauber zwischen den Pulls auf Seite 2. Jede Taste zeigt ihre Kategorie, wie auf der Tastatur. Nichts ändert sich, bis Ihr auf Übernehmen drückt.",
	["Your class's bars, totems, reminders and macros in one step."] = "Leisten, Totems, Erinnerungen und Makros Eurer Klasse in einem Schritt.",
	["Your current settings for this part are replaced."] = "Eure aktuellen Einstellungen für diesen Teil werden ersetzt.",
	["Your experience toward the next level in percent (45%). Empty at max level."] = "Eure Erfahrung bis zur nächsten Stufe in Prozent (45%). Leer auf Höchststufe.",
	["Your faction's materials in one shared frame."] = "Die Materialien Eurer Fraktion in einem gemeinsamen Rahmen.",
	["Your frames go back to your normal layout. The Layouts page turns Gamepad Mode UI on again."] = "Eure Rahmen kehren zu Eurem normalen Layout zurück. Auf der Seite Layouts schaltet Ihr die Gamepad-Modus-UI wieder ein.",
	["Your frames move for controller play whenever the game's gamepad interface is on."] = "Eure Rahmen werden für das Spielen mit Controller umgestellt, sobald die Gamepad-Oberfläche des Spiels an ist.",
	["Your hand rests one key to the right: E and D move, S and F strafe, and you turn with the mouse. Bar 1: R T G W 2 Q A V C X Z 4, bar 2: Shift + the same keys, bar 3: Ctrl + the same keys."] = "Eure Hand liegt eine Taste weiter rechts: E und D laufen, S und F seitwärts, und gedreht wird mit der Maus. Leiste 1: R T G W 2 Q A V C X Z 4, Leiste 2: Umschalt + dieselben Tasten, Leiste 3: Strg + dieselben Tasten.",
	["Your health and power as two liquid orbs at the ends of the action bars, with your target centered above the bars."] = "Eure Gesundheit und Ressource als zwei flüssige Kugeln an den Enden der Aktionsleisten, mit Eurem Ziel mittig über den Leisten.",
	["Your hunter pet's happiness as the game names it."] = "Die Zufriedenheit Eures Tiers, wie das Spiel sie nennt.",
	["Your hunter pet's loyalty level."] = "Die Loyalitätsstufe Eures Tiers.",
	["Your incoming heals"] = "Eure eingehenden Heilungen",
	["Your journal is back as it was before the update. Your journal as it was a moment ago is kept as a backup in My Adventure."] = "Euer Tagebuch ist wieder so wie vor dem Update. Euer Tagebuch von eben wird als Sicherung in Mein Abenteuer aufbewahrt.",
	["Your key set now belongs to your profile and knows US, UK, Nordic, German and French keyboards, and new spells land on their own key on bars 1 to 3."] = "Euer Tastensatz gehört jetzt zu Eurem Profil und kennt US-, UK-, nordische, deutsche und französische Tastaturen, und neue Zauber landen auf eigenen Tasten auf den Leisten 1 bis 3.",
	["Your key set: the keys of bars 1 to 3 and the class spells on them."] = "Euer Tastensatz: die Tasten der Leisten 1 bis 3 und die Klassenzauber darauf.",
	["Your keyboard: %s. The key sets use its keys from now on."] = "Eure Tastatur: %s. Die Tastensätze verwenden ab jetzt ihre Tasten.",
	["Your keys and spells change when combat ends."] = "Eure Tasten und Zauber ändern sich, wenn der Kampf endet.",
	["Your keys are saved for all your characters."] = "Eure Tasten werden für alle Eure Charaktere gespeichert.",
	["Your keys are saved for this character only."] = "Eure Tasten werden nur für diesen Charakter gespeichert.",
	["Your keys are set"] = "Eure Tasten sind belegt",
	["Your keys are shared by your account, so this changes the keys of all your characters. The copy for Undo is kept on this character."] = "Eure Tasten gelten für Euren ganzen Account, daher ändert dies die Tasten aller Eurer Charaktere. Die Kopie für Rückgängig wird auf diesem Charakter aufbewahrt.",
	["Your keys changed since the preview. Look at the preview again before you apply."] = "Eure Tasten haben sich seit der Vorschau geändert. Seht Euch die Vorschau vor dem Übernehmen noch einmal an.",
	["Your keys or action buttons changed since the preview. Look at the preview again before you apply."] = "Eure Tasten oder Aktionstasten haben sich seit der Vorschau geändert. Seht Euch die Vorschau vor dem Übernehmen noch einmal an.",
	["Your known class spells go on the empty buttons of their category on bars 1 to 3. A button with your own action keeps it, and a spell already on your bars is not moved."] = "Eure bekannten Klassenzauber kommen auf die leeren Tasten ihrer Kategorie auf den Leisten 1 bis 3. Eine Taste mit Eurer eigenen Aktion behält sie, und ein Zauber, der schon auf Euren Leisten liegt, wird nicht verschoben.",
	["Your layout %s is not installed. Your frames use the %s layout until you pick one; your own positions are kept."] = "Euer Layout %s ist nicht installiert. Eure Rahmen verwenden das Layout %s, bis Ihr eines wählt; Eure eigenen Positionen bleiben erhalten.",
	["Your layout asks for: %s."] = "Euer Layout verlangt: %s.",
	["Your layout places and sizes these addons out of combat. Their frames follow when you change layouts."] = "Euer Layout platziert diese Addons außerhalb des Kampfes und passt ihre Größe an. Ihre Rahmen folgen, wenn Ihr das Layout wechselt.",
	["Your layout, skin and styles stay as they are."] = "Euer Layout, Skin und Eure Stile bleiben, wie sie sind.",
	["Your main chat sits in EldoUI's chat panel and stays there after Edit Mode changes."] = "Euer Hauptchat sitzt im Chatpanel von EldoUI und bleibt nach Änderungen im Bearbeitungsmodus dort.",
	["Your main chat stays where the game puts it. The Blizzard UI step can let EldoUI move it into EldoUI's chat panel."] = "Euer Hauptchat bleibt, wo das Spiel ihn hinsetzt. Im Schritt Blizzard-UI könnt Ihr EldoUI erlauben, ihn in sein Chatpanel zu verschieben.",
	["Your main damage or healing cooldown."] = "Eure wichtigste Abklingzeit für Schaden oder Heilung.",
	["Your main damage or healing spells for your role, in the order you press them most."] = "Eure wichtigsten Schadens- oder Heilzauber für Eure Rolle, in der Reihenfolge, in der Ihr sie am häufigsten drückt.",
	["Your modules already match %s."] = "Eure Module entsprechen bereits %s.",
	["Your movement keys stay as they are. The keys 7 to = sit farther from your movement hand."] = "Eure Bewegungstasten bleiben, wie sie sind. Die Tasten 7 bis = liegen weiter von Eurer Bewegungshand entfernt.",
	["Your normal layout and dragged frames stay saved and come back when the game's gamepad interface is off. EldoUI never turns the game's gamepad interface on or off: that switch is in the game's Controller settings. Change this later in /eui > Layouts > Gamepad Mode UI."] = "Euer normales Layout und verschobene Rahmen bleiben gespeichert und kehren zurück, wenn die Gamepad-Oberfläche des Spiels aus ist. EldoUI schaltet die Gamepad-Oberfläche des Spiels nie ein oder aus: Dieser Schalter liegt in den Controller-Einstellungen des Spiels. Ändert das später unter /eui > Layouts > Gamepad-Modus-UI.",
	["Your other characters"] = "Eure anderen Charaktere",
	["Your own actions stay where they are: %s."] = "Eure eigenen Aktionen bleiben, wo sie sind: %s.",
	["Your own key map"] = "Eigene Tastenbelegung",
	["Your own keys"] = "Eigene Tasten",
	["Your own mix"] = "Eigene Mischung",
	["Your own pick for Bear Form."] = "Eure eigene Wahl für Bärengestalt.",
	["Your own pick for Berserker Stance."] = "Eure eigene Wahl für Berserkerhaltung.",
	["Your own pick for between pulls."] = "Eure eigene Wahl für zwischen den Pulls.",
	["Your own pick, such as a mount (the Consumable Bar can show yours too)."] = "Eure eigene Wahl, etwa ein Reittier (die Verbrauchsgüterleiste kann Eures auch zeigen).",
	["Your own pick, such as a mount; teleports and portals are in the travel menu."] = "Eure eigene Wahl, etwa ein Reittier; Teleports und Portale liegen im Reisemenü.",
	["Your own pick."] = "Eure eigene Wahl.",
	["Your own pick: totems sit on the totem bar."] = "Eure eigene Wahl: Totems liegen auf der Totemleiste.",
	["Your own tag string, used when the text is set to Custom tags. Example: [classcolor][name:medium][close] [level]"] = "Euer eigener Tag-String, verwendet, wenn der Text auf „Eigene Tags“ steht. Beispiel: [classcolor][name:medium][close] [level]",
	["Your potion, healthstone and mana potion or bandage on a small bar, each used by one key of bar 3."] = "Euer Trank, Gesundheitsstein und Manatrank oder Verband auf einer kleinen Leiste, jeweils mit einer Taste von Leiste 3 benutzt.",
	["Your profile %s now holds a copy of another profile."] = "Euer Profil %s enthält jetzt eine Kopie eines anderen Profils.",
	["Your profile %s now uses the layout %s from %s: %s."] = "Euer Profil %s verwendet jetzt das Layout %s aus %s: %s.",
	["Your profile %s was reset to its defaults."] = "Euer Profil %s wurde auf die Standardwerte zurückgesetzt.",
	["Your profile keeps its own look. Use %s's look (art, windows, styles)?"] = "Euer Profil behält seine eigene Optik. Die Optik von %s übernehmen (Grafik, Fenster, Stile)?",
	["Your profile uses %s, and %s on this character differ from it. Look at the keys before anything changes."] = "Euer Profil nutzt %s, und %s auf diesem Charakter weichen davon ab. Seht Euch die Tasten an, bevor sich etwas ändert.",
	["Your profile uses %s, so this character got its keys: %s. Keys you set yourself stayed."] = "Euer Profil nutzt %s, daher hat dieser Charakter dessen Tasten erhalten: %s. Selbst gesetzte Tasten sind geblieben.",
	["Your race's own break, cleanse or escape."] = "Die Befreiung, Reinigung oder Flucht Eures Volkes.",
	["Your race's own damage, heal or utility ability."] = "Die Schadens-, Heil- oder Hilfsfähigkeit Eures Volkes.",
	["Your rested experience, shortened. Empty when you are not rested or at max level."] = "Euer Erholungsbonus, gekürzt. Leer, wenn Ihr nicht ausgeruht oder auf Höchststufe seid.",
	["Your role and class: a small layer over the layout, and click-cast setup for healers."] = "Eure Rolle und Klasse: eine kleine Ebene über dem Layout und die Klickzauber-Einrichtung für Heiler.",
	["Your role has no class spell here."] = "Eure Rolle hat hier keinen Klassenzauber.",
	["Your role is now %s. %s of this role can go on your bars: on empty buttons, and on buttons where EldoUI put a spell of your old role. Your own actions stay."] = "Eure Rolle ist jetzt %s. %s dieser Rolle können auf Eure Leisten: auf leere Tasten und auf Tasten, auf die EldoUI einen Zauber Eurer alten Rolle gelegt hat. Eure eigenen Aktionen bleiben.",
	["Your safety net: copies kept before each update, values set aside instead of deleted, and what EldoUI checked at this login."] = "Euer Sicherheitsnetz: vor jedem Update aufbewahrte Kopien, beiseitegelegte statt gelöschte Werte und was EldoUI bei diesem Login geprüft hat.",
	["Your screen is %s. EldoUI is made for 1440p, so Auto draws every screen as the 2560x1440 canvas (%s), a little taller on a screen narrower than 16:9: every layout looks exactly as designed, smaller on a smaller screen and bigger on a bigger one."] = "Euer Bildschirm hat %s. EldoUI ist für 1440p gemacht, daher stellt Auto jeden Bildschirm als die 2560x1440-Fläche dar (%s), etwas höher auf einem Bildschirm, der schmaler als 16:9 ist: Jedes Layout sieht genau so aus wie entworfen, kleiner auf einem kleineren Bildschirm und größer auf einem größeren.",
	["Your settings, layout, dragged frames and journal carry over to this version, and a copy is kept first that the new Saved data page can put back."] = "Eure Einstellungen, Euer Layout, verschobene Rahmen und Euer Tagebuch werden in diese Version übernommen, und zuvor wird eine Kopie angelegt, die die neue Seite „Gespeicherte Daten“ zurückholen kann.",
	["Your setup"] = "Eure Einrichtung",
	["Your skin keeps its own background: tints color the flat skins (Modern, Minimal Modern, Blizzard and WoW Forever)."] = "Euer Skin behält seinen eigenen Hintergrund: Tönungen färben die flachen Skins (Modern, Minimal Modern, Blizzard und WoW Forever).",
	["Your text style hides the keys on the action buttons. This shows them on bars 1 to 3 only, so you can see the keys you set; the other bars keep the style."] = "Euer Textstil blendet die Tasten auf den Aktionstasten aus. Dies zeigt sie nur auf den Leisten 1 bis 3, damit Ihr die gesetzten Tasten seht; die anderen Leisten behalten den Stil.",
	["Your threat state on this unit (no numbers)."] = "Euer Bedrohungszustand bei dieser Einheit (ohne Zahlen).",
	["Your totems protect the group: the totem bar."] = "Eure Totems schützen die Gruppe: die Totemleiste.",
	["Your weapon poison (an item)."] = "Euer Waffengift (ein Gegenstand).",
	["Your whole look in one place: a complete look, its layout, the UI amount and Blizzard's windows, applied together."] = "Eure gesamte Optik an einem Ort: eine Komplettoptik, ihr Layout, der UI-Umfang und Blizzards Fenster, gemeinsam übernommen.",
	["Your windows stay. The tabs checked below get their own window, docked next to the main chat."] = "Eure Fenster bleiben. Die unten angehakten Reiter bekommen ein eigenes Fenster, angedockt neben dem Hauptchat.",
	["Zone ability"] = "Zonenfähigkeit",
	["Zone and subzone text"] = "Gebiets- und Untergebietstext",
	["Zone: %s"] = "Gebiet: %s",
	["[<profile> | none]  the profile new characters of your class start with"] = "[<profile> | none]  das Profil, mit dem neue Charaktere Eurer Klasse beginnen",
	["[<profile>]  put this character on a profile you already set up, as it is, with its own chat tabs, game settings and class spells"] = "[<profile>]  diesen Charakter auf ein bereits eingerichtetes Profil setzen, so wie es ist, mit eigenen Chatreitern, Spieleinstellungen und Klassenzaubern",
	["[<step> | undo]  run the EldoUI setup again, open one step (layout, role, modules ...) or undo the last setup"] = "[<step> | undo]  die EldoUI-Einrichtung erneut starten, einen Schritt öffnen (layout, role, modules ...) oder die letzte Einrichtung rückgängig machen",
	["[<step>]  same as /eui install: run the EldoUI setup again"] = "[<step>]  wie /eui install: die EldoUI-Einrichtung erneut starten",
	["[all | general | positions | global | <module> | <list>]  export settings as a readable Lua table"] = "[all | general | positions | global | <module> | <list>]  Einstellungen als lesbare Lua-Tabelle exportieren",
	["[all | general | positions | global | <module> | <list>]  export settings as a share string"] = "[all | general | positions | global | <module> | <list>]  Einstellungen als Teilen-String exportieren",
	["[check | keyboard | hidden]  where bags, map and the other game keys are; check your keys or your keyboard"] = "[check | keyboard | hidden]  wo Taschen, Karte und die anderen Spieltasten liegen; Eure Tasten oder Eure Tastatur prüfen",
	["[clear]  open EldoUI's error log, or empty it"] = "[clear]  EldoUIs Fehlerprotokoll öffnen oder leeren",
	["[command]  this list, or how to use one command"] = "[command]  diese Liste oder wie ein Befehl verwendet wird",
	["[copy | force]  version, modules, restrictions and secret values; copy = for a bug report; force = test switch for combat restrictions"] = "[copy | force]  Version, Module, Einschränkungen und geheime Werte; copy = für einen Fehlerbericht; force = Testschalter für Kampfeinschränkungen",
	["[copy]  copy Blizzard's active Edit Mode layout as text, or open the import window"] = "[copy]  Blizzards aktives Bearbeitungsmodus-Layout als Text kopieren oder das Importfenster öffnen",
	["[element] [on | off | toggle] | <element> skin | move | hide | replace | improve on | off | reset [category]  which Blizzard parts EldoUI may change"] = "[element] [on | off | toggle] | <element> skin | move | hide | replace | improve on | off | reset [category]  welche Blizzard-Teile EldoUI ändern darf",
	["[list | restore <part> [<name>] | follow <part> [<name>]]  your saved data's safety net: open the Saved data page, list the copies kept before updates, put one back, or let a restored part follow updates again"] = "[list | restore <part> [<name>] | follow <part> [<name>]]  das Sicherheitsnetz Eurer gespeicherten Daten: die Seite „Gespeicherte Daten“ öffnen, die vor Updates aufbewahrten Kopien auflisten, eine zurückholen oder einen wiederhergestellten Teil wieder Updates folgen lassen",
	["[list | setup [name]]  the Plugins page; list = print them; setup = their setup pages again"] = "[list | setup [name]]  die Seite Plugins; list = sie im Chat auflisten; setup = ihre Einrichtungsseiten erneut",
	["[lock | unlock | reset | list]  move and scale Blizzard windows"] = "[lock | unlock | reset | list]  Blizzard-Fenster verschieben und skalieren",
	["[movement | strafe | numbers | mouse | esdf | restore]  keybind mode, or the preview of a key set (its id or its name)"] = "[movement | strafe | numbers | mouse | esdf | restore]  Tastenbelegungsmodus oder die Vorschau eines Tastensatzes (seine ID oder sein Name)",
	["[name | reset]  list the tour helps, show one again, or show them all again"] = "[name | reset]  die Tour-Hilfen auflisten, eine erneut zeigen oder alle erneut zeigen",
	["[page | use <addon> | keep <addon> | fit [on | off] [addon]]  which other addons do an EldoUI job; page = the Other addons page; use = EldoUI does that addon's jobs; keep = the addon does; fit = the layout spots for other addons"] = "[page | use <addon> | keep <addon> | fit [on | off] [addon]]  welche anderen Addons eine Aufgabe von EldoUI übernehmen; page = die Seite „Andere Addons“; use = EldoUI übernimmt die Aufgaben dieses Addons; keep = das Addon übernimmt sie; fit = die Layoutplätze für andere Addons",
